window.__HW_VOCAB_SHARED__ = [{"term":"product","termEs":"producto","def":"The answer to a times problem.","defEs":"La respuesta de multiplicar.","example":"3 × 4 = 12","img":"/assets/vocab-images/product.svg","imgAlt":"Illustration of product: The answer to a times problem.","cs":false,"formal":"The answer when you multiply.","formalEs":"El resultado de multiplicar.","exampleEs":"3 × 4 = 12"},{"term":"quotient","termEs":"cociente","def":"The answer when you divide.","defEs":"La respuesta de dividir.","example":"12 ÷ 3 = 4","img":"/assets/vocab-images/quotient.svg","imgAlt":"Illustration of quotient: The answer when you divide.","cs":false,"formalEs":"El resultado de dividir.","exampleEs":"12 ÷ 3 = 4"},{"term":"factor","termEs":"factor","def":"A number that goes into a number with none left.","defEs":"Un número que divide a otro sin que sobre nada.","example":"3 × 4 = 12, so 3 and 4 are factors","img":"/assets/vocab-images/factor.svg","imgAlt":"Illustration of factor: A number that goes into a number with none left.","cs":false,"formal":"A factor of a whole number divides it evenly, with no remainder. For example, 3 is a factor of 12 because 12 ÷ 3 = 4.","formalEs":"Un factor de un número entero lo divide exactamente, sin dejar residuo. Por ejemplo, 3 es un factor de 12 porque 12 ÷ 3 = 4.","exampleEs":"3 × 4 = 12, así que 3 y 4 son factores"},{"term":"remainder","termEs":"residuo","def":"What is left over when you divide.","defEs":"Lo que sobra al dividir.","example":"13 ÷ 4 = 3 with 1 left over","img":"/assets/vocab-images/remainder.svg","imgAlt":"Illustration of remainder: What is left over when you divide.","cs":false,"formal":"What is left over after dividing.","formalEs":"Lo que sobra después de dividir.","exampleEs":"13 ÷ 4 = 3 y sobra 1"},{"term":"digit","termEs":"dígito","def":"One of the symbols 0 to 9.","defEs":"Uno de los símbolos del 0 al 9.","example":"","img":"/assets/vocab-images/place-value.svg","imgAlt":"Illustration of digit: One of the symbols 0 to 9.","cs":false,"formal":"Any of the symbols 0–9 used to write numbers.","formalEs":"Cualquiera de los símbolos 0–9 que se usan para escribir números."},{"term":"multi-digit","termEs":"de varios dígitos","def":"With more than one digit.","defEs":"Con más de un dígito.","example":"26 and 1,344 have more than one digit","img":"/assets/vocab-images/multi-digit.svg","imgAlt":"Illustration of multi-digit: With more than one digit.","cs":false,"formal":"Having more than one digit — 26, 348, and 1,344 are all multi-digit numbers.","formalEs":"Que tiene más de un dígito: 26, 348 y 1,344 son números de varios dígitos.","exampleEs":"26 y 1,344 tienen más de un dígito"},{"term":"prime factorization","termEs":"factorización prima","def":"A number written as a product of primes.","defEs":"Un número escrito como producto de números primos.","example":"12 = 2 × 2 × 3","img":"/assets/vocab-images/prime-factorization.svg","imgAlt":"Illustration of prime factorization: A number written as a product of primes.","cs":false,"formal":"Writing a number as a product of only prime numbers.","formalEs":"Escribir un número como un producto de solo números primos.","exampleEs":"12 = 2 × 2 × 3"},{"term":"greatest common factor","termEs":"máximo común divisor","def":"The biggest number that goes into both.","defEs":"El número más grande que divide a ambos.","example":"For 12 and 18, the biggest shared number is 6","img":"/assets/vocab-images/greatest-common-factor.svg","imgAlt":"Illustration of greatest common factor: The biggest number that goes into both.","cs":false,"formal":"The largest factor that two numbers share.","formalEs":"El factor más grande que comparten dos números.","exampleEs":"Para 12 y 18, el número compartido más grande es 6"},{"term":"least common multiple","termEs":"mínimo común múltiplo","def":"The smallest number both numbers count up to.","defEs":"El número más pequeño al que llegan ambos al contar.","example":"Counting by 4 and 6 first meets at 12","img":"/assets/vocab-images/least-common-multiple.svg","imgAlt":"Illustration of least common multiple: The smallest number both numbers count up to.","cs":false,"formal":"The smallest multiple that two numbers share.","formalEs":"El múltiplo más pequeño que comparten dos números.","exampleEs":"Contando de 4 y de 6, primero coinciden en 12"},{"term":"exponent","termEs":"exponente","def":"A small raised number. It counts the times a number is used.","defEs":"Un número pequeño arriba. Cuenta las veces que se usa un número.","example":"In 2^3, the exponent is 3","img":"/assets/vocab-images/exponent.svg","imgAlt":"Illustration of exponent: A small raised number. It counts the times a number is used.","cs":false,"formal":"A small number that tells how many times to multiply the base by itself.","formalEs":"Un número pequeño que indica cuántas veces multiplicar la base por sí misma.","exampleEs":"En 2^3, el exponente es 3"},{"term":"algorithm","termEs":"algoritmo","def":"A set of steps you follow the same way every time.","defEs":"Pasos que sigues de la misma manera cada vez.","example":"Long division repeats: divide, multiply, subtract, bring down.","img":"/assets/vocab-images/concept-long-division.svg","imgAlt":"Illustration of algorithm: A set of steps you follow the same way every time.","cs":false,"formal":"A set of steps you repeat the same way every time to get an answer.","formalEs":"Un conjunto de pasos que repites igual cada vez para obtener una respuesta."},{"term":"long division","termEs":"división larga","def":"Divide big numbers one step at a time.","defEs":"Dividir números grandes un paso a la vez.","example":"156 ÷ 12 = 13","img":"/assets/vocab-images/concept-long-division.svg","imgAlt":"Illustration of long division: Divide big numbers one step at a time.","cs":false,"formal":"A way to divide big numbers by repeating four steps: divide, multiply, subtract, bring down.","formalEs":"Una forma de dividir números grandes repitiendo cuatro pasos: divide, multiplica, resta y baja el siguiente dígito.","exampleEs":"156 ÷ 12 = 13","exampleFormal":"Divide → Multiply → Subtract → Bring down, then repeat."},{"term":"bring down","termEs":"bajar el dígito","def":"In long division, move the next digit down beside what is left.","defEs":"En la división larga, baja el siguiente dígito junto a lo que sobró.","example":"After subtracting, bring the next digit down and start the cycle again.","img":"/assets/vocab-images/concept-bring-down.svg","imgAlt":"Illustration of bring down: In long division, move the next digit down beside what is left.","cs":false,"formal":"The fourth step of long division: move the next digit down next to what is left.","formalEs":"El cuarto paso de la división larga: baja el siguiente dígito junto a lo que quedó."},{"term":"regroup","termEs":"reagrupar","def":"Trade 10 of one place for 1 of the next.","defEs":"Cambiar 10 de un lugar por 1 del siguiente.","example":"10 ones make 1 ten","img":"/assets/vocab-images/place-value.svg","imgAlt":"Illustration of regroup: Trade 10 of one place for 1 of the next.","cs":false,"formal":"Trade 10 of one place for 1 of the next place (or the other way around).","formalEs":"Cambiar 10 de un lugar por 1 del siguiente lugar (o al revés).","exampleEs":"10 unidades forman 1 decena","exampleFormal":"10 ones regroup into 1 ten."},{"term":"place value","termEs":"valor posicional","def":"What a digit is worth by where it sits.","defEs":"Lo que vale un dígito según dónde está.","example":"In 352, the 5 is worth 50","img":"/assets/vocab-images/place-value.svg","imgAlt":"Illustration of place value: What a digit is worth by where it sits.","cs":false,"formal":"What a digit is worth because of the column it sits in.","formalEs":"Lo que vale un dígito según la columna en la que está.","exampleEs":"En 352, el 5 vale 50","exampleFormal":"In 3.47, the 4 is 4 tenths and the 7 is 7 hundredths."},{"term":"estimate","termEs":"estimar","def":"An answer that is close, found without exact work.","defEs":"Una respuesta cercana, sin hacer el cálculo exacto.","example":"18.576 is about 20","img":"/assets/vocab-images/estimate.svg","imgAlt":"Illustration of estimate: An answer that is close, found without exact work.","cs":false,"formal":"A close-enough answer you find quickly, without doing the exact math.","formalEs":"Una respuesta cercana que hallas rápido, sin hacer la cuenta exacta.","exampleEs":"18.576 es casi 20","exampleFormal":"18.9 ÷ 6.3 is about 18 ÷ 6 = 3."},{"term":"decimal point","termEs":"punto decimal","def":"The dot between whole numbers and parts.","defEs":"El punto que separa los enteros de las partes.","example":"","img":"/assets/vocab-images/decimal-point.svg","imgAlt":"Illustration of decimal point: The dot between whole numbers and parts.","cs":false,"formal":"The dot that separates whole numbers from parts of a whole.","formalEs":"El punto que separa los enteros de las partes de un entero."},{"term":"numerator","termEs":"numerador","def":"The top number of a fraction. It counts the parts you have.","defEs":"El número de arriba de una fracción. Cuenta las partes que tienes.","example":"In 3/4, the top number is 3","img":"/assets/vocab-images/numerator.svg","imgAlt":"Illustration of numerator: The top number of a fraction. It counts the parts you have.","cs":false,"formal":"The top number of a fraction — how many parts you have.","formalEs":"El número de arriba de una fracción — cuántas partes tienes.","exampleEs":"En 3/4, el número de arriba es 3"},{"term":"denominator","termEs":"denominador","def":"The bottom number of a fraction. It tells how many equal parts.","defEs":"El número de abajo de una fracción. Dice cuántas partes iguales hay.","example":"In 3/4, the bottom number is 4","img":"/assets/vocab-images/denominator.svg","imgAlt":"Illustration of denominator: The bottom number of a fraction. It tells how many equal parts.","cs":false,"formal":"The bottom number of a fraction — how many equal parts in the whole.","formalEs":"El número de abajo de una fracción — en cuántas partes iguales se divide el entero.","exampleEs":"En 3/4, el número de abajo es 4"},{"term":"equivalent","termEs":"equivalente","def":"The same value shown in a new way.","defEs":"El mismo valor escrito de otra manera.","example":"1/2 and 0.5 have the same value","img":"/assets/vocab-images/fraction.svg","imgAlt":"Illustration of equivalent: The same value shown in a new way.","cs":false,"formal":"Equal in value, even if written differently (1/2 and 2/4).","formalEs":"Igual en valor, aunque se escriba diferente (1/2 y 2/4).","exampleEs":"1/2 y 0.5 tienen el mismo valor"},{"term":"reciprocal","termEs":"recíproco","def":"A fraction turned upside down.","defEs":"Una fracción volteada de arriba abajo.","example":"2/3 turned upside down is 3/2","img":"/assets/vocab-images/reciprocal.svg","imgAlt":"Illustration of reciprocal: A fraction turned upside down.","cs":false,"formal":"A fraction flipped upside down; two reciprocals multiply to 1.","formalEs":"Una fracción volteada; dos recíprocos multiplicados dan 1.","exampleEs":"2/3 al revés es 3/2"},{"term":"mixed number","termEs":"número mixto","def":"A whole number and a fraction together, like 2 1/2.","defEs":"Un número entero y una fracción juntos, como 2 1/2.","example":"","img":"/assets/vocab-images/mixed-number.svg","imgAlt":"Illustration of mixed number: A whole number and a fraction together, like 2 1/2.","cs":false,"formal":"A whole number and a fraction together, like 2 1/3.","formalEs":"Un número entero y una fracción juntos, como 2 1/3."},{"term":"decimal","termEs":"decimal","def":"A number with a dot, like 0.5, that shows a part.","defEs":"Un número con un punto, como 0.5, que muestra una parte.","example":"0.5 is half of one whole.","img":"/assets/vocab-images/decimal.svg","imgAlt":"Illustration of decimal: A number with a dot, like 0.5, that shows a part.","cs":false,"formal":"A number with a point in it that shows part of a whole, like 0.5 or 18.9.","formalEs":"Un número con punto que muestra parte de un entero, como 0.5 o 18.9."},{"term":"tenths","termEs":"décimas","def":"The first digit after the dot. It counts parts of 10.","defEs":"El primer dígito después del punto. Cuenta partes de 10.","example":"In 0.7, the 7 is 7 tenths","img":"/assets/vocab-images/tenths.svg","imgAlt":"Illustration of tenths: The first digit after the dot. It counts parts of 10.","cs":false,"formal":"The first place after the decimal point — one whole split into 10 equal parts.","formalEs":"El primer lugar después del punto decimal — un entero dividido en 10 partes.","exampleEs":"En 0.7, el 7 son 7 décimas","exampleFormal":"In 0.4 the 4 is 4 tenths."},{"term":"hundredths","termEs":"centésimas","def":"The second digit after the dot. It counts parts of 100.","defEs":"El segundo dígito después del punto. Cuenta partes de 100.","example":"In 0.47, the 7 is 7 hundredths","img":"/assets/vocab-images/hundredths.svg","imgAlt":"Illustration of hundredths: The second digit after the dot. It counts parts of 100.","cs":false,"formal":"The second place after the decimal point — one whole split into 100 equal parts.","formalEs":"El segundo lugar después del punto decimal — un entero dividido en 100 partes.","exampleEs":"En 0.47, el 7 son 7 centésimas","exampleFormal":"In 0.07 the 7 is 7 hundredths."},{"term":"improper fraction","termEs":"fracción impropia","def":"A fraction that is 1 or more, like 5/2.","defEs":"Una fracción que es 1 o más, como 5/2.","example":"7/4 is more than one whole.","img":"/assets/vocab-images/improper-fraction.svg","imgAlt":"Illustration of improper fraction: A fraction that is 1 or more, like 5/2.","cs":false,"formal":"A fraction whose top number is bigger than its bottom number, so it is 1 or more.","formalEs":"Una fracción cuyo numerador es mayor que su denominador, así que vale 1 o más."},{"term":"simplify","termEs":"simplificar","def":"Write it in a smaller form with the same value.","defEs":"Escribirlo de forma más corta con el mismo valor.","example":"2/4 = 1/2","img":"/assets/vocab-images/fraction.svg","imgAlt":"Illustration of simplify: Write it in a smaller form with the same value.","cs":false,"formal":"Rewrite something in its smallest, cleanest equal form.","formalEs":"Reescribir algo en su forma equivalente más simple.","exampleEs":"2/4 = 1/2","exampleFormal":"6/8 simplifies to 3/4."},{"term":"ratio","termEs":"razón","def":"A way to compare two amounts, like 3 to 2.","defEs":"Una manera de comparar dos cantidades, como 3 a 2.","example":"2 red for every 3 blue","img":"/assets/vocab-images/ratio.svg","imgAlt":"Illustration of ratio: A way to compare two amounts, like 3 to 2.","cs":false,"formal":"A comparison of two quantities, like 2 to 3.","formalEs":"Una comparación de dos cantidades, como 2 a 3.","exampleEs":"2 rojas por cada 3 azules"},{"term":"unit rate","termEs":"tasa unitaria","def":"The amount for just 1 of something.","defEs":"La cantidad para solo 1 de algo.","example":"$6 for 3 pens is $2 for 1 pen","img":"/assets/vocab-images/unit-rate.svg","imgAlt":"Illustration of unit rate: The amount for just 1 of something.","cs":false,"formal":"A rate for exactly one of something (miles per 1 hour).","formalEs":"Una tasa por exactamente uno de algo (millas por 1 hora).","exampleEs":"$6 por 3 bolígrafos son $2 por 1 bolígrafo"},{"term":"percent","termEs":"por ciento","def":"A number out of 100, shown with the % sign.","defEs":"Un número de cada 100, con el signo %.","example":"30% means 30 out of 100","img":"/assets/vocab-images/percent.svg","imgAlt":"Illustration of percent: A number out of 100, shown with the % sign.","cs":false,"formal":"A part out of 100.","formalEs":"Una parte de 100.","exampleEs":"30 % significa 30 de cada 100"},{"term":"proportion","termEs":"proporción","def":"A math sentence that says two ratios are equal.","defEs":"Una oración matemática que dice que dos razones son iguales.","example":"1/2 = 3/6","img":"/assets/vocab-images/proportion.svg","imgAlt":"Illustration of proportion: A math sentence that says two ratios are equal.","cs":false,"formal":"An equation that says two ratios are equal.","formalEs":"Una ecuación que dice que dos razones son iguales.","exampleEs":"1/2 = 3/6"},{"term":"variable","termEs":"variable","def":"A letter that stands for a number.","defEs":"Una letra que representa un número.","example":"In 3n + 2, the letter n can change","img":"/assets/vocab-images/variable.svg","imgAlt":"Illustration of variable: A letter that stands for a number.","cs":false,"formal":"A letter that stands for a number that is unknown or can change.","formalEs":"Una letra que representa un número desconocido o que puede cambiar.","exampleEs":"En 3n + 2, la letra n puede cambiar"},{"term":"expression","termEs":"expresión","def":"A math phrase. It has no equal sign.","defEs":"Una frase matemática. No tiene signo de igual.","example":"3n + 4","img":"/assets/vocab-images/expression.svg","imgAlt":"Illustration of expression: A math phrase. It has no equal sign.","cs":false,"formal":"Numbers, variables, and operations with no equals sign.","formalEs":"Números, variables y operaciones sin signo de igual.","exampleEs":"3n + 4"},{"term":"coefficient","termEs":"coeficiente","def":"The number in front of a letter, like 3 in 3x.","defEs":"El número que va delante de una letra, como el 3 en 3x.","example":"","img":"/assets/vocab-images/coefficient.svg","imgAlt":"Illustration of coefficient: The number in front of a letter, like 3 in 3x.","cs":false,"formal":"The number multiplied by a variable (the 3 in 3x).","formalEs":"El número multiplicado por una variable (el 3 en 3x)."},{"term":"substitute","termEs":"sustituir","def":"Put a number in place of a letter.","defEs":"Poner un número en lugar de una letra.","example":"n + 4 with n = 3 becomes 3 + 4","img":"/assets/vocab-images/substitute.svg","imgAlt":"Illustration of substitute: Put a number in place of a letter.","cs":false,"formal":"Replace a variable with a number, then simplify.","formalEs":"Reemplazar una variable por un número y luego simplificar.","exampleEs":"n + 4 con n = 3 pasa a 3 + 4"},{"term":"inequality","termEs":"desigualdad","def":"A math sentence that compares sides with <, >, ≤, or ≥.","defEs":"Una oración matemática que compara lados con <, >, ≤ o ≥.","example":"x > 3 means x is more than 3","img":"/assets/vocab-images/inequality.svg","imgAlt":"Illustration of inequality: A math sentence that compares sides with <, >, ≤, or ≥.","cs":false,"formal":"A math sentence that uses <, >, ≤ or ≥ instead of an equal sign.","formalEs":"Una oración matemática que usa <, >, ≤ o ≥ en lugar del signo igual.","exampleEs":"x > 3 significa que x es más que 3","exampleFormal":"x > 5 means x is any number bigger than 5."},{"term":"evaluate","termEs":"evaluar","def":"Find the value by putting in numbers for the letters.","defEs":"Hallar el valor poniendo números en lugar de las letras.","example":"n + 4 with n = 3 is 7","img":"/assets/vocab-images/expression.svg","imgAlt":"Illustration of evaluate: Find the value by putting in numbers for the letters.","cs":false,"formal":"Work out the value of an expression.","formalEs":"Hallar el valor de una expresión.","exampleEs":"n + 4 con n = 3 es 7","exampleFormal":"Evaluate 3n when n = 4 to get 12."},{"term":"like terms","termEs":"términos semejantes","def":"Terms with the same letter and the same power.","defEs":"Términos con la misma letra y la misma potencia.","example":"2x and 5x have the same letter","img":"/assets/vocab-images/like-terms.svg","imgAlt":"Illustration of like terms: Terms with the same letter and the same power.","cs":false,"formal":"Terms with exactly the same variable part, so they can be combined.","formalEs":"Términos con la misma parte variable, así que se pueden combinar.","exampleEs":"2x y 5x tienen la misma letra","exampleFormal":"5x and 2x are like terms; 5x and 2y are not."},{"term":"integer","termEs":"entero","def":"A whole number or its opposite, like 2 and −2.","defEs":"Un número de contar, su opuesto o el cero, como 2, −2 y 0.","example":"","img":"/assets/vocab-images/integer.svg","imgAlt":"Illustration of integer: A whole number or its opposite, like 2 and −2.","cs":false,"formal":"Whole numbers and their opposites, like -2, -1, 0, 1, 2.","formalEs":"Un número entero que puede ser positivo, negativo o cero."},{"term":"absolute value","termEs":"valor absoluto","def":"How far a number is from zero.","defEs":"Qué tan lejos está un número del cero.","example":"−3 is 3 steps from 0, so |−3| = 3","img":"/assets/vocab-images/absolute-value.svg","imgAlt":"Illustration of absolute value: How far a number is from zero.","cs":false,"formal":"A number's distance from zero — always positive.","formalEs":"La distancia de un número desde cero — siempre positiva.","exampleEs":"|−3| = 3: −3 está a 3 pasos de 0"},{"term":"opposite","termEs":"opuesto","def":"A number the same distance from 0 on the other side.","defEs":"Un número a la misma distancia del 0, del otro lado.","example":"3 and −3 are both 3 steps from 0","img":"/assets/vocab-images/opposite.svg","imgAlt":"Illustration of opposite: A number the same distance from 0 on the other side.","cs":false,"formal":"A number the same distance from zero but on the other side (3 and −3).","formalEs":"Un número a la misma distancia de cero pero del otro lado (3 y −3).","exampleEs":"3 y −3 están a 3 pasos del 0"},{"term":"coordinate plane","termEs":"plano de coordenadas","def":"A flat grid for placing points with two numbers.","defEs":"Una cuadrícula plana para ubicar puntos con dos números.","example":"","img":"/assets/vocab-images/coordinate-plane.svg","imgAlt":"Illustration of coordinate plane: A flat grid for placing points with two numbers.","cs":false,"formal":"A grid made by a horizontal and a vertical number line.","formalEs":"Una cuadrícula formada por una recta numérica horizontal y una vertical."},{"term":"ordered pair","termEs":"par ordenado","def":"Two numbers (x, y) that tell where a point is.","defEs":"Dos números (x, y) que dicen dónde está un punto.","example":"","img":"/assets/vocab-images/ordered-pair.svg","imgAlt":"Illustration of ordered pair: Two numbers (x, y) that tell where a point is.","cs":false,"formal":"Two numbers (x, y) that name a point on the grid.","formalEs":"Dos números (x, y) que nombran un punto en la cuadrícula."},{"term":"perimeter","termEs":"perímetro","def":"The distance around a shape.","defEs":"La distancia alrededor de una figura.","example":"Sides 3, 4, 5: perimeter is 12","img":"/assets/vocab-images/perimeter.svg","imgAlt":"Illustration of perimeter: The distance around a shape.","cs":false,"formal":"The total distance around the outside of a shape.","formalEs":"La distancia total alrededor de una figura.","exampleEs":"Lados 3, 4, 5: el perímetro es 12"},{"term":"volume","termEs":"volumen","def":"How much space is inside a solid shape.","defEs":"Cuánto espacio hay dentro de un cuerpo sólido.","example":"A 2 by 3 by 4 box holds 24 cubes","img":"/assets/vocab-images/volume.svg","imgAlt":"Illustration of volume: How much space is inside a solid shape.","cs":false,"formal":"The amount of space inside a 3-D solid.","formalEs":"La cantidad de espacio dentro de un sólido en 3-D.","exampleEs":"Una caja de 2 por 3 por 4 tiene 24 cubos"},{"term":"surface area","termEs":"área de superficie","def":"The area of all the flat sides added together.","defEs":"El área de todos los lados planos sumados.","example":"Cube with edge 2: 6 faces × 4 = 24","img":"/assets/vocab-images/surface-area.svg","imgAlt":"Illustration of surface area: The area of all the flat sides added together.","cs":false,"formal":"The total area of all the flat sides of a solid.","formalEs":"El área total de todos los lados planos de un sólido.","exampleEs":"Cubo de arista 2: 6 caras × 4 = 24"},{"term":"area","termEs":"área","def":"How much flat space a shape covers.","defEs":"Cuánto espacio plano cubre una figura.","example":"A 3 by 4 rectangle covers 12 square units","img":"/assets/vocab-images/area.svg","imgAlt":"Illustration of area: How much flat space a shape covers.","cs":false,"formal":"How much flat space a shape covers, counted in square units.","formalEs":"Cuánto espacio plano cubre una figura, contado en unidades cuadradas.","exampleEs":"Un rectángulo de 3 por 4 cubre 12 unidades cuadradas","exampleFormal":"A 3 × 4 rectangle covers 12 square units."},{"term":"triangle","termEs":"triángulo","def":"A shape with three sides.","defEs":"Una figura de tres lados.","example":"","img":"/assets/vocab-images/triangle.svg","imgAlt":"Illustration of triangle: A shape with three sides.","cs":false,"formal":"A closed shape with 3 straight sides.","formalEs":"Una figura cerrada con 3 lados rectos."},{"term":"rectangle","termEs":"rectángulo","def":"A shape with 4 sides and 4 square corners.","defEs":"Una figura con 4 lados y 4 esquinas cuadradas.","example":"","img":"/assets/vocab-images/rectangle.svg","imgAlt":"Illustration of rectangle: A shape with 4 sides and 4 square corners.","cs":false,"formal":"A 4-sided shape with 4 square corners.","formalEs":"Una figura de 4 lados con 4 esquinas rectas."},{"term":"parallelogram","termEs":"paralelogramo","def":"A shape with four sides. Opposite sides are parallel.","defEs":"Una figura de cuatro lados. Los lados opuestos son paralelos.","example":"","img":"/assets/vocab-images/parallelogram.svg","imgAlt":"Illustration of parallelogram: A shape with four sides. Opposite sides are parallel.","cs":false,"formal":"A 4-sided shape whose opposite sides are parallel and the same length.","formalEs":"Una figura de 4 lados cuyos lados opuestos son paralelos e iguales."},{"term":"trapezoid","termEs":"trapecio","def":"A shape with four sides and just one pair of parallel sides.","defEs":"Una figura de cuatro lados con un solo par de lados paralelos.","example":"","img":"/assets/vocab-images/trapezoid.svg","imgAlt":"Illustration of trapezoid: A shape with four sides and just one pair of parallel sides.","cs":false,"formal":"A 4-sided shape with exactly one pair of parallel sides.","formalEs":"Una figura de 4 lados con exactamente un par de lados paralelos."},{"term":"rhombus","termEs":"rombo","def":"A shape with four sides that are all the same length.","defEs":"Una figura de cuatro lados que miden lo mismo.","example":"","img":"/assets/vocab-images/rhombus.svg","imgAlt":"Illustration of rhombus: A shape with four sides that are all the same length.","cs":false,"formal":"A 4-sided shape whose four sides are all the same length.","formalEs":"Una figura de 4 lados con los cuatro lados iguales."},{"term":"polygon","termEs":"polígono","def":"A closed shape with straight sides.","defEs":"Una figura cerrada con lados rectos.","example":"","img":"/assets/vocab-images/regular-polygon.svg","imgAlt":"Illustration of polygon: A closed shape with straight sides.","cs":false,"formal":"A closed shape made only of straight sides.","formalEs":"Una figura cerrada formada solo por lados rectos."},{"term":"prism","termEs":"prisma","def":"A 3-D solid with two matching ends and flat sides.","defEs":"Un sólido 3-D con dos extremos iguales y lados planos.","example":"","img":"/assets/vocab-images/rectangular-prism.svg","imgAlt":"Illustration of prism: A 3-D solid with two matching ends and flat sides.","cs":false,"formal":"A 3-D solid with two identical ends joined by flat sides.","formalEs":"Un sólido en 3-D con dos extremos idénticos unidos por lados planos."},{"term":"pyramid","termEs":"pirámide","def":"A solid with a flat bottom and triangles that meet on top.","defEs":"Un sólido con fondo plano y lados triangulares que se juntan arriba.","example":"","img":"/assets/vocab-images/pyramid.svg","imgAlt":"Illustration of pyramid: A solid with a flat bottom and triangles that meet on top.","cs":false,"formal":"A 3-D solid with one base whose sides are triangles meeting at a point.","formalEs":"Un sólido en 3-D con una base cuyos lados son triángulos que se unen en un punto."},{"term":"net","termEs":"plantilla","def":"A flat shape that folds into a solid.","defEs":"Una figura plana que se dobla para formar un sólido.","example":"","img":"/assets/vocab-images/net.svg","imgAlt":"Illustration of net: A flat shape that folds into a solid.","cs":false,"formal":"A flat pattern that folds up into a 3-D solid.","formalEs":"Un patrón plano que se dobla para formar un sólido en 3-D."},{"term":"vertex","termEs":"vértice","def":"A corner where edges or sides meet.","defEs":"Una esquina donde se unen aristas o lados.","example":"","img":"/assets/vocab-images/ordered-pair.svg","imgAlt":"Illustration of vertex: A corner where edges or sides meet.","cs":false,"formal":"A corner point where sides or edges meet.","formalEs":"Un punto de esquina donde se juntan lados o aristas."},{"term":"edge","termEs":"arista","def":"Where two flat sides of a solid meet.","defEs":"Donde se unen dos lados planos de un sólido.","example":"","img":"/assets/vocab-images/edge.svg","imgAlt":"Illustration of edge: Where two flat sides of a solid meet.","cs":false,"formal":"The line where two flat sides of a solid meet.","formalEs":"La línea donde se juntan dos caras planas de un sólido."},{"term":"segment","termEs":"segmento","def":"A piece of a line with a start and an end.","defEs":"Un pedazo de una línea, con principio y fin.","example":"","img":"/assets/vocab-images/segment.svg","imgAlt":"Illustration of segment: A piece of a line with a start and an end.","cs":false,"formal":"A piece of a line, a number line, or a length that has a beginning and an end. Equal segments are the same-size pieces a whole is cut into — a 3 1/2-mile route split into 1/4-mile segments has 14 of them.","formalEs":"Un pedazo de una recta, de una recta numérica o de una longitud, con un principio y un final. Los segmentos iguales son las partes del mismo tamaño en que se divide un entero: una ruta de 3 1/2 millas dividida en segmentos de 1/4 de milla tiene 14."},{"term":"line segment","termEs":"segmento de recta","def":"A straight piece of a line with two ends.","defEs":"Un pedazo recto de una recta, con dos extremos.","example":"","img":"/assets/vocab-images/segment.svg","imgAlt":"Illustration of line segment: A straight piece of a line with two ends.","cs":false,"formal":"The straight path between two endpoints. It does not keep going the way a line does — it stops at both ends.","formalEs":"El camino recto entre dos extremos. No sigue sin fin como una recta: termina en los dos extremos."},{"term":"median","termEs":"mediana","def":"The middle number when they are in order.","defEs":"El número del medio cuando están en orden.","example":"3, 5, 9: the median is 5","img":"/assets/vocab-images/median.svg","imgAlt":"Illustration of median: The middle number when they are in order.","cs":false,"formal":"The middle number when you put them in order.","formalEs":"El número del medio cuando los pones en orden.","exampleEs":"3, 5, 9: la mediana es 5"},{"term":"outlier","termEs":"valor atípico","def":"A number far bigger or smaller than the rest.","defEs":"Un número mucho mayor o menor que los demás.","example":"2, 3, 3, 4, 40: 40 is far away","img":"/assets/vocab-images/outlier.svg","imgAlt":"Illustration of outlier: A number far bigger or smaller than the rest.","cs":false,"formal":"A data value much larger or smaller than the rest.","formalEs":"Un dato mucho mayor o menor que los demás.","exampleEs":"2, 3, 3, 4, 40: el 40 está lejos"},{"term":"interquartile range","termEs":"rango intercuartílico","def":"The distance across the middle half of the data.","defEs":"La distancia que cubre la mitad central de los datos.","example":"Q3 − Q1 = 10 − 4 = 6","img":"/assets/vocab-images/interquartile-range.svg","imgAlt":"Illustration of interquartile range: The distance across the middle half of the data.","cs":false,"formal":"The spread of the middle half of the data.","formalEs":"La dispersión de la mitad central de los datos.","exampleEs":"Q3 − Q1 = 10 − 4 = 6"},{"term":"mean absolute deviation","termEs":"desviación media absoluta","def":"The typical distance of the data from the mean.","defEs":"La distancia típica de los datos a la media.","example":"A small one means the data clump near the mean; a big one means they spread out.","img":"/assets/vocab-images/mean-absolute-deviation.svg","imgAlt":"Illustration of mean absolute deviation: The typical distance of the data from the mean.","cs":false,"formal":"The average distance each data value sits from the mean.","formalEs":"La distancia promedio entre cada dato y la media."},{"term":"keep-change-flip","termEs":"mantén-cambia-invierte","def":"Keep the first, change ÷ to ×, flip the second.","defEs":"Deja la primera, cambia ÷ por × y voltea la segunda.","example":"1/2 ÷ 1/4 → 1/2 × 4/1 = 2","img":"/assets/vocab-images/reciprocal.svg","imgAlt":"Illustration of keep-change-flip: Keep the first, change ÷ to ×, flip the second.","cs":false,"formal":"A way to remember dividing by a fraction: keep the first fraction, change ÷ to ×, and flip the second fraction.","formalEs":"Una forma de recordar cómo dividir entre una fracción: mantén la primera fracción, cambia ÷ por ×, e invierte la segunda fracción.","exampleEs":"1/2 ÷ 1/4 → 1/2 × 4/1 = 2","exampleFormal":"3/4 ÷ 2/5 becomes 3/4 × 5/2."},{"term":"data","termEs":"datos","def":"Facts and numbers you collect.","defEs":"Información y números que reúnes, como respuestas de una encuesta.","example":"","img":"/assets/vocab-images/data.svg","imgAlt":"Illustration of data: Facts and numbers you collect.","cs":false,"formal":"The numbers or answers you collect to study a question.","formalEs":"Los números o respuestas que reúnes para estudiar una pregunta."},{"term":"histogram","termEs":"histograma","def":"A bar graph with touching bars. Each bar counts one group.","defEs":"Una gráfica de barras que se tocan. Cada barra cuenta un grupo.","example":"","img":"/assets/vocab-images/histogram.svg","imgAlt":"Illustration of histogram: A bar graph with touching bars. Each bar counts one group.","cs":false,"formal":"A bar graph that shows how many values fall in each equal-size interval.","formalEs":"Una gráfica de barras que muestra cuántos valores caen en cada intervalo igual."},{"term":"box plot","termEs":"diagrama de caja","def":"A graph that sums up data with five key numbers.","defEs":"Una gráfica que resume los datos con cinco números clave.","example":"","img":"/assets/vocab-images/box-plot.svg","imgAlt":"Illustration of box plot: A graph that sums up data with five key numbers.","cs":false,"formal":"A graph that shows a data set split into four equal parts by its quartiles.","formalEs":"Una gráfica que muestra un conjunto de datos dividido en cuatro partes iguales."},{"term":"dot plot","termEs":"diagrama de puntos","def":"A number line with one dot for each value.","defEs":"Una recta numérica con un punto por cada valor.","example":"Values 2, 3, 3: two dots stack above 3","img":"/assets/vocab-images/data.svg","imgAlt":"Illustration of dot plot: A number line with one dot for each value.","cs":false,"formal":"A graph that stacks one dot above the number line for each value.","formalEs":"Una gráfica que apila un punto sobre la recta numérica por cada valor.","exampleEs":"Valores 2, 3, 3: dos puntos juntos sobre el 3"},{"term":"quartile","termEs":"cuartil","def":"One of three numbers that split data into four equal parts.","defEs":"Uno de tres números que dividen los datos en cuatro partes iguales.","example":"","img":"/assets/vocab-images/quartile.svg","imgAlt":"Illustration of quartile: One of three numbers that split data into four equal parts.","cs":false,"formal":"One of the three values that cut ordered data into four equal groups.","formalEs":"Uno de los tres valores que dividen los datos ordenados en cuatro grupos iguales."},{"term":"frequency","termEs":"frecuencia","def":"How many times a value shows up.","defEs":"Cuántas veces aparece un valor.","example":"In 2, 3, 3, 5, the 3 shows up twice","img":"/assets/vocab-images/frequency.svg","imgAlt":"Illustration of frequency: How many times a value shows up.","cs":false,"formal":"How many times a value shows up in the data.","formalEs":"Cuántas veces aparece un valor en los datos.","exampleEs":"En 2, 3, 3, 5, el 3 aparece dos veces"},{"term":"distribution","termEs":"distribución","def":"Where the values sit and how far apart they are.","defEs":"Dónde están los valores y qué tan separados están.","example":"","img":"/assets/vocab-images/distribution.svg","imgAlt":"Illustration of distribution: Where the values sit and how far apart they are.","cs":false,"formal":"The overall shape of the data — where it clumps up and where it spreads out.","formalEs":"La forma general de los datos — dónde se agrupan y dónde se dispersan."},{"term":"cluster","termEs":"agrupación","def":"Values that are near each other.","defEs":"Valores que están cerca unos de otros.","example":"","img":"/assets/vocab-images/cluster.svg","imgAlt":"Illustration of cluster: Values that are near each other.","cs":false,"formal":"A group of data values bunched close together.","formalEs":"Un grupo de valores de datos muy juntos."},{"term":"scale factor","termEs":"factor de escala","def":"The number you multiply both parts by.","defEs":"El número por el que multiplicas ambas partes.","example":"2:3 → 4:6 uses scale factor 2","img":"/assets/vocab-images/scale-factor.svg","imgAlt":"Illustration of scale factor: The number you multiply both parts by.","cs":false,"formal":"The number you multiply every part of a ratio (or figure) by to make an equivalent one.","formalEs":"El número por el que multiplicas cada parte de una razón (o figura) para formar una equivalente.","exampleEs":"2:3 → 4:6 usa el factor de escala 2"},{"term":"equivalent ratio","termEs":"razón equivalente","def":"Ratios that compare in the same way.","defEs":"Razones que comparan de la misma manera.","example":"1:2 and 2:4 compare the same way","img":"/assets/vocab-images/equivalent-ratio.svg","imgAlt":"Illustration of equivalent ratio: Ratios that compare in the same way.","cs":false,"formal":"A ratio that shows the same comparison, made by multiplying or dividing both parts by the same number.","formalEs":"Una razón que muestra la misma comparación, formada al multiplicar o dividir ambas partes por el mismo número.","exampleEs":"1:2 y 2:4 comparan de la misma manera"},{"term":"equivalent expression","termEs":"expresión equivalente","def":"Math phrases that look different but give the same value.","defEs":"Frases matemáticas que se ven distintas pero dan el mismo valor.","example":"2(x + 3) and 2x + 6 always match","img":"/assets/vocab-images/expression.svg","imgAlt":"Illustration of equivalent expression: Math phrases that look different but give the same value.","cs":false,"formal":"An expression that always has the same value as another, just written a different way.","formalEs":"Una expresión que siempre tiene el mismo valor que otra, solo escrita de otra manera.","exampleEs":"2(x + 3) y 2x + 6 siempre coinciden"},{"term":"equivalent fraction","termEs":"fracción equivalente","def":"Fractions that name the same amount.","defEs":"Fracciones que nombran la misma cantidad.","example":"1/2 and 2/4 name the same amount","img":"/assets/vocab-images/fraction.svg","imgAlt":"Illustration of equivalent fraction: Fractions that name the same amount.","cs":false,"formal":"A fraction that names the same amount as another (1/2 and 2/4).","formalEs":"Una fracción que nombra la misma cantidad que otra (1/2 y 2/4).","exampleEs":"1/2 y 2/4 nombran la misma cantidad"},{"term":"common factor","termEs":"factor común","def":"A number that divides two numbers with none left over.","defEs":"Un número que divide a dos números sin que sobre nada.","example":"4 divides both 8 and 12","img":"/assets/vocab-images/factor.svg","imgAlt":"Illustration of common factor: A number that divides two numbers with none left over.","cs":false,"formal":"A number that divides evenly into two or more numbers.","formalEs":"Un número que divide exactamente a dos o más números.","exampleEs":"El 4 divide al 8 y al 12"},{"term":"common multiple","termEs":"múltiplo común","def":"A number you reach when counting by each number.","defEs":"Un número al que llegas contando de a saltos con cada número.","example":"Counting by 4 and by 6 both land on 12","img":"/assets/vocab-images/least-common-multiple.svg","imgAlt":"Illustration of common multiple: A number you reach when counting by each number.","cs":false,"formal":"A number that is a multiple of two or more numbers.","formalEs":"Un número que es múltiplo de dos o más números.","exampleEs":"Contando de 4 y de 6: ambos llegan a 12"},{"term":"least common denominator","termEs":"mínimo común denominador","def":"The smallest bottom number both can use.","defEs":"El número de abajo más pequeño que ambas pueden usar.","example":"1/2 and 1/3 can both use 6","img":"/assets/vocab-images/least-common-multiple.svg","imgAlt":"Illustration of least common denominator: The smallest bottom number both can use.","cs":false,"formal":"The smallest denominator two fractions can share so you can compare or add them.","formalEs":"El denominador más pequeño que dos fracciones pueden compartir para compararlas o sumarlas.","exampleEs":"1/2 y 1/3 pueden usar 6","exampleFormal":"For 3/5 and 4/7 the least common denominator is 35: 21/35 and 20/35."},{"term":"prime factor","termEs":"factor primo","def":"A factor that is also a prime number.","defEs":"Un factor que también es un número primo.","example":"12 = 2 × 2 × 3, so 2 and 3 are prime","img":"/assets/vocab-images/factor.svg","imgAlt":"Illustration of prime factor: A factor that is also a prime number.","cs":false,"formal":"A prime factor is a factor that is also a prime number. For example, the prime factors of 12 are 2 and 3 because 12 = 2 × 2 × 3.","formalEs":"Un factor primo es un factor que también es un número primo. Por ejemplo, los factores primos de 12 son 2 y 3 porque 12 = 2 × 2 × 3.","exampleEs":"12 = 2 × 2 × 3, así que 2 y 3 son primos"},{"term":"conversion factor","termEs":"factor de conversión","def":"A ratio you use to change units.","defEs":"Una razón que usas para cambiar de unidad.","example":"12 inches for each 1 foot","img":"/assets/vocab-images/measurement.svg","imgAlt":"Illustration of conversion factor: A ratio you use to change units.","cs":false,"formal":"A rate you multiply by to change one unit into another.","formalEs":"Una tasa por la que multiplicas para cambiar una unidad por otra.","exampleEs":"12 pulgadas por cada 1 pie"},{"term":"algebraic expression","termEs":"expresión algebraica","def":"A math phrase that uses a letter for a number.","defEs":"Una frase matemática que usa una letra para un número.","example":"3n + 2","img":"/assets/vocab-images/expression.svg","imgAlt":"Illustration of algebraic expression: A math phrase that uses a letter for a number.","cs":false,"formal":"An expression that uses at least one variable.","formalEs":"Una expresión que usa al menos una variable.","exampleEs":"3n + 2"},{"term":"LCM","termEs":"mínimo común múltiplo","def":"The smallest number both numbers count up to.","defEs":"El número más pequeño al que llegan ambos al contar.","example":"Counting by 4 and 6 first meets at 12","img":"/assets/vocab-images/least-common-multiple.svg","imgAlt":"Illustration of LCM: The smallest number both numbers count up to.","cs":true,"formal":"The smallest multiple that two numbers share.","formalEs":"El múltiplo más pequeño que comparten dos números.","exampleEs":"Contando de 4 y de 6, primero coinciden en 12"},{"term":"MCM","termEs":"mínimo común múltiplo","def":"The smallest number both numbers count up to.","defEs":"El número más pequeño al que llegan ambos al contar.","example":"Counting by 4 and 6 first meets at 12","img":"/assets/vocab-images/least-common-multiple.svg","imgAlt":"Illustration of MCM: The smallest number both numbers count up to.","cs":true,"formal":"The smallest multiple that two numbers share.","formalEs":"El múltiplo más pequeño que comparten dos números.","exampleEs":"Contando de 4 y de 6, primero coinciden en 12"},{"term":"GCF","termEs":"máximo común divisor","def":"The biggest number that goes into both.","defEs":"El número más grande que divide a ambos.","example":"For 12 and 18, the biggest shared number is 6","img":"/assets/vocab-images/greatest-common-factor.svg","imgAlt":"Illustration of GCF: The biggest number that goes into both.","cs":true,"formal":"The largest factor that two numbers share.","formalEs":"El factor más grande que comparten dos números.","exampleEs":"Para 12 y 18, el número compartido más grande es 6"},{"term":"MCD","termEs":"máximo común divisor","def":"The biggest number that goes into both.","defEs":"El número más grande que divide a ambos.","example":"For 12 and 18, the biggest shared number is 6","img":"/assets/vocab-images/greatest-common-factor.svg","imgAlt":"Illustration of MCD: The biggest number that goes into both.","cs":true,"formal":"The largest factor that two numbers share.","formalEs":"El factor más grande que comparten dos números.","exampleEs":"Para 12 y 18, el número compartido más grande es 6"},{"term":"GCD","termEs":"máximo común divisor","def":"The biggest number that goes into both.","defEs":"El número más grande que divide a ambos.","example":"For 12 and 18, the biggest shared number is 6","img":"/assets/vocab-images/greatest-common-factor.svg","imgAlt":"Illustration of GCD: The biggest number that goes into both.","cs":true,"formal":"The largest factor that two numbers share.","formalEs":"El factor más grande que comparten dos números.","exampleEs":"Para 12 y 18, el número compartido más grande es 6"},{"term":"LCD","termEs":"mínimo común denominador","def":"The smallest bottom number both can use.","defEs":"El número de abajo más pequeño que ambas pueden usar.","example":"1/2 and 1/3 can both use 6","img":"/assets/vocab-images/least-common-multiple.svg","imgAlt":"Illustration of LCD: The smallest bottom number both can use.","cs":true,"formal":"The smallest denominator two fractions can share so you can compare or add them.","formalEs":"El denominador más pequeño que dos fracciones pueden compartir para compararlas o sumarlas.","exampleEs":"1/2 y 1/3 pueden usar 6","exampleFormal":"For 3/5 and 4/7 the least common denominator is 35: 21/35 and 20/35."},{"term":"IQR","termEs":"rango intercuartílico","def":"The distance across the middle half of the data.","defEs":"La distancia que cubre la mitad central de los datos.","example":"Q3 − Q1 = 10 − 4 = 6","img":"/assets/vocab-images/interquartile-range.svg","imgAlt":"Illustration of IQR: The distance across the middle half of the data.","cs":true,"formal":"The spread of the middle half of the data.","formalEs":"La dispersión de la mitad central de los datos.","exampleEs":"Q3 − Q1 = 10 − 4 = 6"},{"term":"RIC","termEs":"rango intercuartílico","def":"The distance across the middle half of the data.","defEs":"La distancia que cubre la mitad central de los datos.","example":"Q3 − Q1 = 10 − 4 = 6","img":"/assets/vocab-images/interquartile-range.svg","imgAlt":"Illustration of RIC: The distance across the middle half of the data.","cs":true,"formal":"The spread of the middle half of the data.","formalEs":"La dispersión de la mitad central de los datos.","exampleEs":"Q3 − Q1 = 10 − 4 = 6"},{"term":"MAD","termEs":"desviación media absoluta","def":"The typical distance of the data from the mean.","defEs":"La distancia típica de los datos a la media.","example":"A small one means the data clump near the mean; a big one means they spread out.","img":"/assets/vocab-images/mean-absolute-deviation.svg","imgAlt":"Illustration of MAD: The typical distance of the data from the mean.","cs":true,"formal":"The average distance each data value sits from the mean.","formalEs":"La distancia promedio entre cada dato y la media."},{"term":"DMA","termEs":"desviación media absoluta","def":"The typical distance of the data from the mean.","defEs":"La distancia típica de los datos a la media.","example":"A small one means the data clump near the mean; a big one means they spread out.","img":"/assets/vocab-images/mean-absolute-deviation.svg","imgAlt":"Illustration of DMA: The typical distance of the data from the mean.","cs":true,"formal":"The average distance each data value sits from the mean.","formalEs":"La distancia promedio entre cada dato y la media."},{"term":"DAM","termEs":"desviación media absoluta","def":"The typical distance of the data from the mean.","defEs":"La distancia típica de los datos a la media.","example":"A small one means the data clump near the mean; a big one means they spread out.","img":"/assets/vocab-images/mean-absolute-deviation.svg","imgAlt":"Illustration of DAM: The typical distance of the data from the mean.","cs":true,"formal":"The average distance each data value sits from the mean.","formalEs":"La distancia promedio entre cada dato y la media."},{"term":"SA","termEs":"área de superficie","def":"The area of all the flat sides added together.","defEs":"El área de todos los lados planos sumados.","example":"Cube with edge 2: 6 faces × 4 = 24","img":"/assets/vocab-images/surface-area.svg","imgAlt":"Illustration of SA: The area of all the flat sides added together.","cs":true,"formal":"The total area of all the flat sides of a solid.","formalEs":"El área total de todos los lados planos de un sólido.","exampleEs":"Cubo de arista 2: 6 caras × 4 = 24"},{"term":"KCF","termEs":"mantén-cambia-invierte","def":"Keep the first, change ÷ to ×, flip the second.","defEs":"Deja la primera, cambia ÷ por × y voltea la segunda.","example":"1/2 ÷ 1/4 → 1/2 × 4/1 = 2","img":"/assets/vocab-images/reciprocal.svg","imgAlt":"Illustration of KCF: Keep the first, change ÷ to ×, flip the second.","cs":true,"formal":"A way to remember dividing by a fraction: keep the first fraction, change ÷ to ×, and flip the second fraction.","formalEs":"Una forma de recordar cómo dividir entre una fracción: mantén la primera fracción, cambia ÷ por ×, e invierte la segunda fracción.","exampleEs":"1/2 ÷ 1/4 → 1/2 × 4/1 = 2","exampleFormal":"3/4 ÷ 2/5 becomes 3/4 × 5/2."},{"term":"MCI","termEs":"mantén-cambia-invierte","def":"Keep the first, change ÷ to ×, flip the second.","defEs":"Deja la primera, cambia ÷ por × y voltea la segunda.","example":"1/2 ÷ 1/4 → 1/2 × 4/1 = 2","img":"/assets/vocab-images/reciprocal.svg","imgAlt":"Illustration of MCI: Keep the first, change ÷ to ×, flip the second.","cs":true,"formal":"A way to remember dividing by a fraction: keep the first fraction, change ÷ to ×, and flip the second fraction.","formalEs":"Una forma de recordar cómo dividir entre una fracción: mantén la primera fracción, cambia ÷ por ×, e invierte la segunda fracción.","exampleEs":"1/2 ÷ 1/4 → 1/2 × 4/1 = 2","exampleFormal":"3/4 ÷ 2/5 becomes 3/4 × 5/2."},{"term":"Add and Subtract Decimals","termEs":"Sumar y restar decimales","def":"Line up the decimal points, then add or subtract.","defEs":"Alinea los puntos decimales y luego suma o resta.","example":"2.5 + 0.75 = 3.25","img":"/assets/vocab-images/concept-add-and-subtract-decimals.svg","imgAlt":"Illustration of Add and Subtract Decimals: Line up the decimal points, then add or subtract.","cs":false,"formal":"Combine or find the difference between decimals by lining up equal place values.","formalEs":"Combinar o hallar la diferencia entre decimales alineando valores posicionales iguales.","exampleEs":"2.5 + 0.75 = 3.25","exampleFormal":"15.70 − 8.36 = 7.34; line up the decimal points."},{"term":"Addition Property of Equality","termEs":"Propiedad de adición de la igualdad","def":"Add the same number to both sides. They stay equal.","defEs":"Suma el mismo número a ambos lados. Siguen siendo iguales.","example":"x − 3 = 7 → x = 10","img":"/assets/vocab-images/equation.svg","imgAlt":"Illustration of Addition Property of Equality: Add the same number to both sides. They stay equal.","cs":false,"formal":"Adding the same amount to both sides keeps an equation balanced.","formalEs":"Sumar la misma cantidad a ambos lados mantiene una ecuación equilibrada.","exampleEs":"x − 3 = 7 → x = 10","exampleFormal":"Both sides + 9"},{"term":"Additive pattern","termEs":"Patrón aditivo","def":"Each column grows by adding its own fixed number.","defEs":"Cada columna crece sumando su propio número fijo.","example":"2:3 → 4:6 → 6:9 (add 2 and 3 each time)","img":"/assets/vocab-images/pattern.svg","imgAlt":"Illustration of Additive pattern: Each column grows by adding its own fixed number.","cs":false,"formal":"Building new rows of a ratio table by adding each column's own constant amount, so the two columns grow together.","formalEs":"Formar nuevas filas de una tabla de razones sumando a cada columna su propia cantidad constante, para que las dos columnas crezcan juntas."},{"term":"Annex a zero","termEs":"Agregar un cero","def":"Put a zero at the end of a decimal. The value stays.","defEs":"Escribe un cero al final del decimal. El valor no cambia.","example":"0.5 = 0.50","img":"/assets/vocab-images/decimal-division-algorithm.svg","imgAlt":"Illustration of Annex a zero: Put a zero at the end of a decimal. The value stays.","cs":false,"formal":"Write a zero after the last decimal digit without changing the value.","formalEs":"Escribir un cero después del último dígito decimal sin cambiar el valor.","exampleEs":"0.5 = 0.50","exampleFormal":"7.2 → 7.20"},{"term":"Annex zeros","termEs":"Agregar ceros","def":"Put zeros at the end of a decimal. The value stays.","defEs":"Escribe ceros al final de un decimal. El valor no cambia.","example":"4.2 = 4.200","img":"/assets/vocab-images/decimal.svg","imgAlt":"Illustration of Annex zeros: Put zeros at the end of a decimal. The value stays.","cs":false,"formal":"Adding zeros at the end of a decimal so numbers line up evenly.","formalEs":"Agregar ceros al final de un decimal para que los números se alineen.","exampleEs":"4.2 = 4.200","exampleFormal":"15.7 becomes 15.70 so you can subtract 15.70 − 8.36 with aligned place values"},{"term":"Apex","termEs":"Ápice","def":"The top point of a pyramid, where the sides meet.","defEs":"El punto de arriba de una pirámide, donde se unen los lados.","example":"The pointy top of a pyramid — all the slanted edges connect here","img":"/assets/vocab-images/pyramid.svg","imgAlt":"Illustration of Apex: The top point of a pyramid, where the sides meet.","cs":false,"formal":"The point at the top of a pyramid where the sides meet.","formalEs":"El punto en la parte de arriba de una pirámide donde se unen los lados."},{"term":"Appropriate Measures of Center","termEs":"Medidas de centro apropiadas","def":"The mean, median, or mode that best fits the data.","defEs":"La media, mediana o moda que mejor describe los datos.","example":"Use the median when an outlier would pull the mean too far.","img":"/assets/vocab-images/concept-appropriate-measures-of-center.svg","imgAlt":"Illustration of Appropriate Measures of Center: The mean, median, or mode that best fits the data.","cs":false,"formal":"A mean, median, or mode chosen because it describes a data set fairly.","formalEs":"Una media, mediana o moda elegida porque describe un conjunto de datos de manera justa."},{"term":"Approximately","termEs":"Aproximadamente","def":"Close to, but not exactly equal.","defEs":"Cerca de, pero no exactamente igual.","example":"3.9 is close to 4, so 3.9 ≈ 4","img":"/assets/vocab-images/estimate.svg","imgAlt":"Illustration of Approximately: Close to, but not exactly equal.","cs":false,"formal":"Close to, but not exactly equal. A rounded conversion factor gives an approximate result, written with ≈; an exact conversion uses =.","formalEs":"Cercano, pero no exactamente igual. Un factor de conversión redondeado da un resultado aproximado, escrito con ≈; una conversión exacta usa =.","exampleEs":"3.9 está cerca de 4, así que 3.9 ≈ 4","exampleFormal":"1 km ≈ 0.6 mi, not exactly 0.6"},{"term":"Area of a Triangle","termEs":"Área de un triángulo","def":"Space inside a triangle: half the base times the height.","defEs":"Espacio dentro de un triángulo: la mitad de la base por la altura.","example":"Base 6, height 4: area is 12","img":"/assets/vocab-images/area-of-triangles.svg","imgAlt":"Illustration of Area of a Triangle: Space inside a triangle: half the base times the height.","cs":false,"formal":"The space inside a triangle. A triangle is half of a rectangle with the same base and height, so A = ½ × b × h.","formalEs":"El espacio dentro de un triángulo. Un triángulo es la mitad de un rectángulo con la misma base y altura, por eso A = ½ × b × h.","exampleEs":"Base 6, altura 4: el área es 12","exampleFormal":"A = ½ × b × h; if b = 8 and h = 5, then A = ½ × 8 × 5 = 20 square units"},{"term":"Area of Composite Figures","termEs":"Área de figuras compuestas","def":"The space inside a figure built from simple shapes.","defEs":"El espacio dentro de una figura hecha de figuras simples.","example":"Total area = area of rectangle 1 + area of rectangle 2.","img":"/assets/vocab-images/area-of-composite-figures.svg","imgAlt":"Illustration of Area of Composite Figures: The space inside a figure built from simple shapes.","cs":false,"formal":"The total space inside a figure made of basic shapes. Formula: A = A₁ + A₂ — add the parts (or subtract a missing piece).","formalEs":"El espacio total dentro de una figura formada por figuras básicas. Fórmula: A = A₁ + A₂ — suma las partes (o resta la pieza que falta)."},{"term":"Area of Parallelograms","termEs":"Área de paralelogramos","def":"Base times height. Measure the height straight up.","defEs":"Base por altura. Mide la altura en línea recta hacia arriba.","example":"Base 5, height 3: area is 15","img":"/assets/vocab-images/area-of-parallelograms.svg","imgAlt":"Illustration of Area of Parallelograms: Base times height. Measure the height straight up.","cs":false,"formal":"The space inside a parallelogram. Formula: A = b × h, using the perpendicular height.","formalEs":"El espacio dentro de un paralelogramo. Fórmula: A = b × h, usando la altura perpendicular.","exampleEs":"Base 5, altura 3: el área es 15","exampleFormal":"A = b × h; if b = 10 cm and h = 6 cm, A = 60 cm²."},{"term":"Area of Regular Polygons","termEs":"Área de polígonos regulares","def":"Split it into equal triangles, then add their areas.","defEs":"Divídelo en triángulos iguales y suma sus áreas.","example":"A hexagon splits into 6 identical triangles: (½ × 4 × 3.5) × 6 = 42 square units","img":"/assets/vocab-images/area-of-regular-polygons.svg","imgAlt":"Illustration of Area of Regular Polygons: Split it into equal triangles, then add their areas.","cs":false,"formal":"The space a regular polygon covers. Split it from the center into identical triangles, find one triangle's area, then multiply by how many there are.","formalEs":"El espacio que cubre un polígono regular. Divídelo desde el centro en triángulos idénticos, halla el área de uno y multiplícala por cuántos hay."},{"term":"Area of Trapezoids","termEs":"Área de trapecios","def":"Add the two bases, halve it, then multiply by the height.","defEs":"Suma las dos bases, toma la mitad y multiplica por la altura.","example":"Bases 4 and 8, height 5: area is 30","img":"/assets/vocab-images/area-of-trapezoids.svg","imgAlt":"Illustration of Area of Trapezoids: Add the two bases, halve it, then multiply by the height.","cs":false,"formal":"The space inside a trapezoid. Formula: A = 1/2(b₁ + b₂)h.","formalEs":"El espacio dentro de un trapecio. Fórmula: A = 1/2(b₁ + b₂)h.","exampleEs":"Bases 4 y 8, altura 5: el área es 30","exampleFormal":"A = 1/2(b₁ + b₂)h"},{"term":"argument","termEs":"argumento","def":"A claim backed by reasons that others can check.","defEs":"Una afirmación con razones que otros pueden revisar.","example":"“Two jumbo boxes hold more, because 400 × 2 = 800 > 720.”","img":"/assets/vocab-images/argument.svg","imgAlt":"Illustration of argument: A claim backed by reasons that others can check.","cs":false,"formal":"A chain of reasons — equations, drawings, or words — used to defend your thinking.","formalEs":"Una cadena de razones — ecuaciones, dibujos o palabras — que usas para defender tu pensamiento."},{"term":"Associative Property","termEs":"Propiedad asociativa","def":"Changing the grouping does not change the answer.","defEs":"Cambiar la agrupación no cambia el resultado.","example":"(2+3)+4 = 2+(3+4)","img":"/assets/vocab-images/associative-property.svg","imgAlt":"Illustration of Associative Property: Changing the grouping does not change the answer.","cs":false,"formal":"You can change the grouping and get the same answer.","formalEs":"Puedes cambiar la agrupación y obtener la misma respuesta.","exampleEs":"(2+3)+4 = 2+(3+4)","exampleFormal":"(2 + 3) + 4 = 5 + 4 = 9 and 2 + (3 + 4) = 2 + 7 = 9 — same answer, different grouping"},{"term":"at least","termEs":"al menos","def":"That amount or more.","defEs":"Esa cantidad o más.","example":"At least 42 means 42 or more","img":"/assets/vocab-images/inequality.svg","imgAlt":"Illustration of at least: That amount or more.","cs":false,"formal":"That amount or more — the smallest amount that still works.","formalEs":"Esa cantidad o más — la cantidad mínima que todavía funciona.","exampleEs":"Al menos 42 significa 42 o más","exampleFormal":"“At least $500” means $500 counts, and so does anything more."},{"term":"At least / At most","termEs":"Al menos / A lo más","def":"≥ means that amount or more. ≤ means that amount or less.","defEs":"≥ significa esa cantidad o más. ≤ significa esa cantidad o menos.","example":"'At least 10 players' → p ≥ 10 (could be 10, 11, 12, ...); 'At most 5 tries' → t ≤ 5 (could be 5, 4, 3, ...)","img":"/assets/vocab-images/inequality.svg","imgAlt":"Illustration of At least / At most: ≥ means that amount or more. ≤ means that amount or less.","cs":false,"formal":"'At least' means ≥. 'At most' means ≤.","formalEs":"'Al menos' significa ≥. 'Como máximo' significa ≤."},{"term":"Average","termEs":"Promedio","def":"The amount each one gets when the total is shared equally.","defEs":"Lo que recibe cada uno si el total se reparte igual.","example":"3, 5, 7 share 15 equally: 5 each","img":"/assets/vocab-images/mean.svg","imgAlt":"Illustration of Average: The amount each one gets when the total is shared equally.","cs":false,"formal":"Another word for the mean — the amount each value would be if the total were shared equally.","formalEs":"Otra palabra para la media: la cantidad que tendría cada valor si el total se repartiera en partes iguales.","exampleEs":"3, 5 y 7 suman 15: a cada uno le toca 5","exampleFormal":"A player averages 15 points per game, so over 10 games she scores 15 × 10 = 150 points in all."},{"term":"Axis","termEs":"Eje","def":"One of the two number lines that mark a graph.","defEs":"Una de las dos rectas numéricas que marcan una gráfica.","example":"The x-axis goes left-right; the y-axis goes up-down; they cross at (0, 0)","img":"/assets/vocab-images/axis.svg","imgAlt":"Illustration of Axis: One of the two number lines that mark a graph.","cs":false,"formal":"One of the two number lines that frame a graph: the x-axis runs across, the y-axis runs up and down.","formalEs":"Una de las dos rectas numéricas que enmarcan una gráfica: el eje x va horizontal y el eje y va vertical."},{"term":"balance","termEs":"equilibrio","def":"Doing the same thing to both sides so they stay equal.","defEs":"Hacer lo mismo en ambos lados para que sigan siendo iguales.","example":"Two matching halves — neither side feels heavier than the other.","img":"/assets/vocab-images/equation.svg","imgAlt":"Illustration of balance: Doing the same thing to both sides so they stay equal.","cs":false,"formal":"An even, steady arrangement — neither side feels heavier than the other.","formalEs":"Una disposición pareja y estable: ningún lado se siente más pesado que el otro."},{"term":"Balance point","termEs":"Punto de equilibrio","def":"The point where the data evens out. It is the mean.","defEs":"El punto donde los datos quedan parejos. Es la media.","example":"With a target mean of 15, points totaling 13 below must be matched by points totaling 13 above.","img":"/assets/vocab-images/mean.svg","imgAlt":"Illustration of Balance point: The point where the data evens out. It is the mean.","cs":false,"formal":"The value where the total distance of the data above it equals the total distance below it. The mean is the balance point.","formalEs":"El valor donde la distancia total de los datos por encima es igual a la distancia total por debajo. La media es el punto de equilibrio."},{"term":"Base","termEs":"Base","def":"The number you take the percent of.","defEs":"El número del que sacas el porcentaje.","example":"In 25% of 80, the base is 80","img":"/assets/vocab-images/percent-base.svg","imgAlt":"Illustration of Base: The number you take the percent of.","cs":false,"formal":"The number you take the percent OF — it is the number right after the word 'of'.","formalEs":"El número del que sacas el porcentaje — es el número que va después de la palabra 'de'.","exampleEs":"En 25 % de 80, la base es 80","exampleFormal":"In '25% of 80,' the base is 80. In '140% of 145,' the base is still 145."},{"term":"Base 1 (b1)","termEs":"Base 1 (b1)","def":"A side of a trapezoid. It is one of two parallel sides.","defEs":"Un lado de un trapecio. Es uno de los dos lados paralelos.","example":"If the bottom of the trapezoid is 10 ft, then b₁ = 10 ft in the formula A = ½(b₁ + b₂) × h","img":"/assets/vocab-images/base-1-trapezoid.svg","imgAlt":"Illustration of Base 1 (b1): A side of a trapezoid. It is one of two parallel sides.","cs":false,"formal":"One of the two parallel sides of a trapezoid.","formalEs":"Uno de los dos lados paralelos de un trapecio."},{"term":"Base 2 (b2)","termEs":"Base 2 (b2)","def":"A side of a trapezoid. It is the other parallel side.","defEs":"Un lado de un trapecio. Es el otro lado paralelo.","example":"If the top of the trapezoid is 6 ft, then b₂ = 6 ft; both bases are parallel to each other","img":"/assets/vocab-images/base-2-trapezoid.svg","imgAlt":"Illustration of Base 2 (b2): A side of a trapezoid. It is the other parallel side.","cs":false,"formal":"The other parallel side of a trapezoid.","formalEs":"El otro lado paralelo de un trapecio."},{"term":"Base area","termEs":"Área de la base","def":"The space covered by the bottom of a solid.","defEs":"El espacio que cubre el fondo de un sólido.","example":"If the base is 6 × 4 = 24 cm² and h = 3, then V = 24 × 3 = 72 cm³","img":"/assets/vocab-images/base-area-prism.svg","imgAlt":"Illustration of Base area: The space covered by the bottom of a solid.","cs":false,"formal":"The area of the bottom of a solid. Volume = base area × height.","formalEs":"El área del fondo de un sólido. Volumen = área de la base × altura."},{"term":"Benchmark","termEs":"Punto de referencia","def":"An easy number you use to estimate, like 50%.","defEs":"Un número fácil que usas para estimar, como 50 %.","example":"12 pounds for both stores.","img":"/assets/vocab-images/number.svg","imgAlt":"Illustration of Benchmark: An easy number you use to estimate, like 50%.","cs":false,"formal":"A shared amount you scale both choices to so you can compare them.","formalEs":"Una cantidad compartida a la que escalas ambas opciones para poder compararlas."},{"term":"benchmark percent","termEs":"porcentaje de referencia","def":"An easy percent you can find in your head.","defEs":"Un porcentaje fácil que puedes hallar mentalmente.","example":"50% of 80 is half of 80: 40","img":"/assets/vocab-images/percent.svg","imgAlt":"Illustration of benchmark percent: An easy percent you can find in your head.","cs":false,"formal":"A friendly percent — 1%, 10%, 25%, 50%, 75%, 100% — used as a landmark for estimating.","formalEs":"Un porcentaje amigable — 1%, 10%, 25%, 50%, 75%, 100% — que sirve de punto de referencia.","exampleEs":"50 % de 80 es la mitad de 80: 40","exampleFormal":"1% · 10% · 25% · 50% · 75% · 100% — the landmarks you can find mentally."},{"term":"Better Buy","termEs":"Mejor compra","def":"The choice that costs less for each item.","defEs":"La opción que cuesta menos por cada artículo.","example":"$6 for 3 ($2 each) beats $8 for 2","img":"/assets/vocab-images/unit-rate.svg","imgAlt":"Illustration of Better Buy: The choice that costs less for each item.","cs":false,"exampleEs":"$6 por 3 ($2 c/u) es mejor que $8 por 2","exampleFormal":"Pack A: $0.50 per pencil vs Pack B: $0.40 per pencil — Pack B is the better buy"},{"term":"bilateral symmetry","termEs":"simetría bilateral","def":"Both halves of a living thing match, like mirror images.","defEs":"Las dos mitades de un ser vivo son como un espejo.","example":"All 17,000+ butterfly species have it — two sides, one mirror line.","img":"/assets/vocab-images/symmetric.svg","imgAlt":"Illustration of bilateral symmetry: Both halves of a living thing match, like mirror images.","cs":false,"formal":"Reflective symmetry in plants and animals — the two sides of the body mirror each other.","formalEs":"La simetría reflectiva en plantas y animales: los dos lados del cuerpo se reflejan entre sí."},{"term":"Boundary point","termEs":"Punto límite","def":"The number at the edge of the solutions on a number line.","defEs":"El número en el borde de las soluciones en la recta numérica.","example":"For x > 5, the boundary point is 5, shown with an open circle.","img":"/assets/vocab-images/boundary-point.svg","imgAlt":"Illustration of Boundary point: The number at the edge of the solutions on a number line.","cs":false,"formal":"The number on the number line where the solution set starts.","formalEs":"El número en la recta numérica donde comienza el conjunto solución."},{"term":"Closed circle","termEs":"Círculo cerrado","def":"A filled circle. The number is part of the answer.","defEs":"Un círculo relleno. El número es parte de la respuesta.","example":"x ≥ 5: closed circle at 5 means 5 IS a solution, and so are 6, 7, 8, ...","img":"/assets/vocab-images/closed-circle.svg","imgAlt":"Illustration of Closed circle: A filled circle. The number is part of the answer.","cs":false,"formal":"A filled-in circle showing a number IS included.","formalEs":"Un círculo relleno que muestra que un número SÍ está incluido."},{"term":"Colon notation","termEs":"Notación con dos puntos","def":"Write a ratio with two dots between the numbers, like 3:2.","defEs":"Escribir una razón con dos puntos entre los números, como 3:2.","example":"3 to 2 can be written as 3:2","img":"/assets/vocab-images/ratio.svg","imgAlt":"Illustration of Colon notation: Write a ratio with two dots between the numbers, like 3:2.","cs":false,"formal":"Writing a ratio with two dots between the numbers, like 3:2."},{"term":"Common denominator","termEs":"Denominador común","def":"A bottom number that two fractions share.","defEs":"Un número de abajo que comparten dos fracciones.","example":"1/2 and 1/3 can share 6","img":"/assets/vocab-images/fraction.svg","imgAlt":"Illustration of Common denominator: A bottom number that two fractions share.","cs":false,"formal":"A bottom number that two fractions can share so you can compare them.","formalEs":"Un número de abajo que dos fracciones pueden compartir para compararlas.","exampleEs":"1/2 y 1/3 pueden compartir 6","exampleFormal":"To compare 3/5 and 4/7, use LCD 35: 21/35 vs 20/35"},{"term":"Common form","termEs":"Forma común","def":"The same form for every value, like all percents.","defEs":"La misma forma para todos los valores, como porcentajes.","example":"All written as percents before ordering.","img":"/assets/vocab-images/percent.svg","imgAlt":"Illustration of Common form: The same form for every value, like all percents.","cs":false,"formal":"One form, such as percents, that every value in a list is rewritten in.","formalEs":"Una forma, como porcentajes, en la que se reescriben todos los valores de una lista."},{"term":"community","termEs":"comunidad","def":"The people and places around you.","defEs":"Las personas y los lugares a tu alrededor.","example":"The people and places where math shows up — home, work, the neighborhood.","img":"/assets/vocab-images/community.svg","imgAlt":"Illustration of community: The people and places around you.","cs":false,"formal":"The people and places around you — where math shows up outside the classroom.","formalEs":"Las personas y los lugares que te rodean, donde las matemáticas aparecen fuera del aula."},{"term":"community agreement","termEs":"acuerdo comunitario","def":"A rule the whole class agrees to follow.","defEs":"Una norma que toda la clase acepta cumplir.","example":"“We take turns sharing, and we critique ideas, not people.”","img":"/assets/vocab-images/community-agreement.svg","imgAlt":"Illustration of community agreement: A rule the whole class agrees to follow.","cs":false,"formal":"A rule the whole class agrees to so that everyone can learn together.","formalEs":"Una norma que toda la clase acepta para que todos puedan aprender juntos."},{"term":"Commutative Property","termEs":"Propiedad conmutativa","def":"Changing the order does not change the answer.","defEs":"Cambiar el orden no cambia el resultado.","example":"3 + 5 = 5 + 3","img":"/assets/vocab-images/commutative-property.svg","imgAlt":"Illustration of Commutative Property: Changing the order does not change the answer.","cs":false,"formal":"You can change the order and get the same answer.","formalEs":"Puedes cambiar el orden y obtener la misma respuesta.","exampleEs":"3 + 5 = 5 + 3","exampleFormal":"3 + 7 = 7 + 3 = 10 both ways; 4 × 5 = 5 × 4 = 20 both ways — order does not matter"},{"term":"Compare and Order Integers","termEs":"Comparar y ordenar enteros","def":"Tell which integers are bigger. Then put them in order.","defEs":"Decir cuál entero es mayor y ponerlos en orden.","example":"−5, −1, 0, 3 go from least to greatest","img":"/assets/vocab-images/concept-compare-and-order-integers.svg","imgAlt":"Illustration of Compare and Order Integers: Tell which integers are bigger. Then put them in order.","cs":false,"formal":"Use a number line to decide which integers are greater or less and place them in order.","formalEs":"Usar una recta numérica para decidir cuáles enteros son mayores o menores y colocarlos en orden.","exampleEs":"−5, −1, 0, 3 van de menor a mayor","exampleFormal":"−5 < −2 < 0 < 3"},{"term":"Compare Ratios","termEs":"Comparar razones","def":"Decide which ratio is bigger, smaller, or the same.","defEs":"Decidir cuál razón es mayor, menor o igual.","example":"Compare 6:2 and 8:4 using unit rates: 3 > 2.","img":"/assets/vocab-images/concept-compare-ratios.svg","imgAlt":"Illustration of Compare Ratios: Decide which ratio is bigger, smaller, or the same.","cs":false,"formal":"Decide which ratio is greater, less, or equal by using equivalent ratios or unit rates.","formalEs":"Decidir cuál razón es mayor, menor o igual usando razones equivalentes o tasas unitarias."},{"term":"Comparison","termEs":"Comparación","def":"Looking at two amounts to see how they relate.","defEs":"Mirar dos cantidades para ver cómo se relacionan.","example":"5 eggs vs. 3 eggs — which recipe uses more?","img":"/assets/vocab-images/ratio.svg","imgAlt":"Illustration of Comparison: Looking at two amounts to see how they relate.","cs":false,"formal":"Looking at two or more amounts to see how they are related.","formalEs":"Mirar dos o más cantidades para ver cómo se relacionan."},{"term":"compatible numbers","termEs":"números compatibles","def":"Numbers near the real ones that are easy to work with.","defEs":"Números cercanos a los reales con los que es fácil calcular.","example":"For 8.6% of 216, use 10% and 200","img":"/assets/vocab-images/estimate.svg","imgAlt":"Illustration of compatible numbers: Numbers near the real ones that are easy to work with.","cs":false,"formal":"Numbers close to the originals that are easy to compute with mentally.","formalEs":"Números cercanos a los originales con los que es fácil calcular mentalmente.","exampleEs":"Para 8.6 % de 216, usa 10 % y 200","exampleFormal":"8.6% of 216 → 10% of 220: both nudged to numbers that divide nicely."},{"term":"Composite","termEs":"Compuesto","def":"Made of two or more simple shapes.","defEs":"Formado por dos o más figuras simples.","example":"6 triangles, each with area 15 sq ft, combine to form a hexagon with total area = 6 × 15 = 90 sq ft","img":"/assets/vocab-images/composite-figure.svg","imgAlt":"Illustration of Composite: Made of two or more simple shapes.","cs":false,"formal":"Made by putting two or more simple shapes together.","formalEs":"Formada al juntar dos o más figuras simples."},{"term":"Composite figure","termEs":"Figura compuesta","def":"A shape made of simple shapes joined together.","defEs":"Una figura hecha de figuras simples juntas.","example":"An L-shaped room = a 10×8 rectangle joined to a 4×5 rectangle; total area = 80 + 20 = 100 sq ft","img":"/assets/vocab-images/composite-figure.svg","imgAlt":"Illustration of Composite figure: A shape made of simple shapes joined together.","cs":false,"formal":"A shape made by putting two or more simple shapes together.","formalEs":"Una figura formada al juntar dos o más figuras simples."},{"term":"Composite number","termEs":"Número compuesto","def":"A number over 1 that is not prime.","defEs":"Un número mayor que 1 que no es primo.","example":"6 is composite: 2 × 3 = 6","img":"/assets/vocab-images/composite-number.svg","imgAlt":"Illustration of Composite number: A number over 1 that is not prime.","cs":false,"formal":"A number bigger than 1 that you can divide by more than just 1 and itself.","formalEs":"Un número mayor que 1 que se puede dividir entre más números, no solo 1 y sí mismo.","exampleEs":"6 es compuesto: 2 × 3 = 6","exampleFormal":"12 = 1 × 12, 2 × 6, 3 × 4 — six factors, so 12 is composite"},{"term":"confidence","termEs":"confianza","def":"Trusting yourself to try a hard problem.","defEs":"Creer en ti para atreverte a probar un problema difícil.","example":"Starting a hard problem before you are sure it will work.","img":"/assets/vocab-images/confidence.svg","imgAlt":"Illustration of confidence: Trusting yourself to try a hard problem.","cs":false,"formal":"Trusting yourself to try a problem, even when the first attempt might fail.","formalEs":"Confiar en ti mismo para intentar un problema, aunque el primer intento pueda fallar."},{"term":"Congruent","termEs":"Congruente","def":"Exactly the same size and shape.","defEs":"Exactamente del mismo tamaño y forma.","example":"The 8 center triangles of a regular octagon all match.","img":"/assets/vocab-images/regular-polygon.svg","imgAlt":"Illustration of Congruent: Exactly the same size and shape.","cs":false},{"term":"conjecture","termEs":"conjetura","def":"A math idea you think is true but have not proved.","defEs":"Una idea matemática que crees cierta pero no has probado.","example":"“A bigger box ALWAYS holds more cereal” — believed, not yet proven.","img":"/assets/vocab-images/conjecture.svg","imgAlt":"Illustration of conjecture: A math idea you think is true but have not proved.","cs":false,"formal":"A mathematical statement you believe is true but have not yet proven.","formalEs":"Una afirmación matemática que crees verdadera pero que aún no has probado."},{"term":"Constant","termEs":"Constante","def":"A number that stays the same.","defEs":"Un número que se queda igual.","example":"In 3x + 5, the constant is 5","img":"/assets/vocab-images/constant.svg","imgAlt":"Illustration of Constant: A number that stays the same.","cs":false,"formal":"A speed, price, or rate that stays the same.","formalEs":"Una velocidad, un precio o una tasa que se mantiene igual.","exampleEs":"En 3x + 5, la constante es 5","exampleFormal":"The same amount every hour."},{"term":"Constraint","termEs":"Restricción","def":"A rule an answer must follow.","defEs":"Una regla que la respuesta debe cumplir.","example":"A voter must be 18 or older.","img":"/assets/vocab-images/inequality.svg","imgAlt":"Illustration of Constraint: A rule an answer must follow.","cs":false,"formal":"A limit that a solution must satisfy.","formalEs":"Un límite que una solución debe cumplir."},{"term":"Convert","termEs":"Convertir","def":"Change to a new unit or form; the amount stays the same.","defEs":"Cambiar a otra unidad o forma sin cambiar la cantidad.","example":"4 ft and 48 in are the same height, written two ways","img":"/assets/vocab-images/measurement.svg","imgAlt":"Illustration of Convert: Change to a new unit or form; the amount stays the same.","cs":false,"formal":"To change a measurement from one unit to another without changing how much it is.","formalEs":"Cambiar una medida de una unidad a otra sin cambiar la cantidad que representa."},{"term":"Convert Measurement Units","termEs":"Convertir unidades de medida","def":"Say a measure in a different unit. The amount stays the same.","defEs":"Decir una medida en otra unidad sin cambiar la cantidad.","example":"3 feet = 36 inches","img":"/assets/vocab-images/concept-convert-measurement-units.svg","imgAlt":"Illustration of Convert Measurement Units: Say a measure in a different unit. The amount stays the same.","cs":false,"formal":"Rename a measurement in a different unit without changing its amount.","formalEs":"Expresar una medida en una unidad diferente sin cambiar su cantidad.","exampleEs":"3 pies = 36 pulgadas","exampleFormal":"3 feet × 12 inches per foot = 36 inches."},{"term":"Convert Measurements Between Systems","termEs":"Convertir medidas entre sistemas","def":"Change US units to metric units, or back.","defEs":"Cambiar unidades usuales a métricas, o al revés.","example":"1 mile ≈ 1.6 kilometers","img":"/assets/vocab-images/concept-convert-measurements-between-systems.svg","imgAlt":"Illustration of Convert Measurements Between Systems: Change US units to metric units, or back.","cs":false,"formal":"Rewriting a customary measurement as a metric one, or the reverse, so two amounts can be compared.","formalEs":"Reescribir una medida usual como métrica, o al revés, para poder comparar dos cantidades.","exampleEs":"1 milla ≈ 1.6 kilómetros","exampleFormal":"100 kilometers ≈ 60 miles"},{"term":"Convert Measurements within the Same System","termEs":"Convertir medidas dentro del mismo sistema","def":"Switch to a new unit in the same system.","defEs":"Pasar a otra unidad del mismo sistema.","example":"3 feet = 36 inches","img":"/assets/vocab-images/concept-convert-measurements-within-the-same-system.svg","imgAlt":"Illustration of Convert Measurements within the Same System: Switch to a new unit in the same system.","cs":false,"formal":"Rewriting a measurement in a different unit of the SAME system, such as feet into inches or liters into milliliters.","formalEs":"Reescribir una medida en otra unidad del MISMO sistema, como pies a pulgadas o litros a mililitros.","exampleEs":"3 pies = 36 pulgadas","exampleFormal":"4 feet = 48 inches; 4 liters = 4,000 milliliters"},{"term":"Coordinates","termEs":"Coordenadas","def":"The two numbers that tell where a point is.","defEs":"Los dos números que dicen dónde está un punto.","example":"(3, 2) is 3 right, 2 up","img":"/assets/vocab-images/ordered-pair.svg","imgAlt":"Illustration of Coordinates: The two numbers that tell where a point is.","cs":false,"formal":"The x-value and y-value that locate a point.","formalEs":"El valor de x y el valor de y que ubican un punto.","exampleEs":"(3, 2) es 3 a la derecha, 2 arriba","exampleFormal":"x first, then y: (4, 20)"},{"term":"counterexample","termEs":"contraejemplo","def":"One example that shows it is not always true.","defEs":"Un ejemplo que muestra que no siempre es cierto.","example":"One jumbo box sold half full of air breaks “bigger always holds more”.","img":"/assets/vocab-images/counterexample.svg","imgAlt":"Illustration of counterexample: One example that shows it is not always true.","cs":false,"formal":"A single example that shows a statement is not always true.","formalEs":"Un solo ejemplo que muestra que una afirmación no siempre es verdadera."},{"term":"critique","termEs":"criticar constructivamente","def":"Look at an idea and say what works and what does not.","defEs":"Revisar una idea y decir qué funciona y qué no.","example":"“That step assumes the boxes are full — how do we know?”","img":"/assets/vocab-images/critique.svg","imgAlt":"Illustration of critique: Look at an idea and say what works and what does not.","cs":false,"formal":"To examine an idea and say what is convincing or not — about the idea, never about the person.","formalEs":"Examinar una idea y decir qué es convincente o no — sobre la idea, nunca sobre la persona."},{"term":"Cross-multiply","termEs":"Multiplicación cruzada","def":"Multiply across. See if the ratios match.","defEs":"Multiplicar en cruz para ver si las razones son iguales.","example":"2/3 and 4/6: 2 × 6 = 3 × 4","img":"/assets/vocab-images/proportion.svg","imgAlt":"Illustration of Cross-multiply: Multiply across. See if the ratios match.","cs":false,"formal":"Multiplying across two ratios to check if they are equal.","formalEs":"Multiplicar en cruz dos razones para ver si son iguales.","exampleEs":"2/3 y 4/6: 2 × 6 = 3 × 4","exampleFormal":"2/3 = 8/12 → 2×12 = 24 and 3×8 = 24 ✓"},{"term":"Cubed","termEs":"Al cubo","def":"A number written three times in a product.","defEs":"Un número escrito tres veces en un producto.","example":"2^3 = 2 × 2 × 2 = 8","img":"/assets/vocab-images/exponent.svg","imgAlt":"Illustration of Cubed: A number written three times in a product.","cs":false,"formal":"A base used as a factor three times.","formalEs":"Una base usada como factor tres veces.","exampleEs":"2^3 = 2 × 2 × 2 = 8","exampleFormal":"4^3 = 4 × 4 × 4"},{"term":"cubic unit","termEs":"unidad cúbica","def":"A cube with sides 1 unit long. It measures volume.","defEs":"Un cubo de 1 unidad por lado. Sirve para medir volumen.","example":"One cube, 1 unit on every edge — the block volume is counted in.","img":"/assets/vocab-images/cubic-units.svg","imgAlt":"Illustration of cubic unit: A cube with sides 1 unit long. It measures volume.","cs":false,"formal":"A cube with edges 1 unit long — the unit used to measure volume.","formalEs":"Un cubo cuyas aristas miden 1 unidad — la unidad que se usa para medir el volumen."},{"term":"Customary system","termEs":"Sistema usual","def":"Units like inches and pounds, used in the US.","defEs":"Unidades como pulgadas y libras, usadas en Estados Unidos.","example":"in · ft · mi · oz · lb · qt · gal","img":"/assets/vocab-images/concept-customary-system.svg","imgAlt":"Illustration of Customary system: Units like inches and pounds, used in the US.","cs":false,"formal":"The measurement system used in the United States: inches, feet, miles, ounces, pounds, cups, quarts, gallons.","formalEs":"El sistema de medidas que se usa en Estados Unidos: pulgadas, pies, millas, onzas, libras, tazas, cuartos y galones."},{"term":"Customary units","termEs":"Unidades usuales (sistema inglés)","def":"Units like inches, feet, and pounds.","defEs":"Unidades como pulgadas, pies y libras.","example":"12 inches = 1 foot, 3 feet = 1 yard, 16 ounces = 1 pound","img":"/assets/vocab-images/measurement.svg","imgAlt":"Illustration of Customary units: Units like inches, feet, and pounds.","cs":false,"formal":"The U.S. way of measuring, like inches, feet, and pounds.","formalEs":"La forma de medir de EE. UU., como pulgadas, pies y libras."},{"term":"Data distribution","termEs":"Distribución de datos","def":"Where the values sit and how far apart they are.","defEs":"Dónde están los valores y qué tan separados están.","example":"A distribution is symmetric when its left and right sides have approximately matching shapes around the center.","img":"/assets/vocab-images/distribution.svg","imgAlt":"Illustration of Data distribution: Where the values sit and how far apart they are.","cs":false,"formal":"How the data looks: where it sits and how spread out it is.","formalEs":"Cómo se ven los datos: dónde están y qué tan separados están."},{"term":"Data set","termEs":"Conjunto de datos","def":"All the values that were collected.","defEs":"Todos los valores que se reunieron.","example":"Sofia's points in games 1–9 — 12, 20, 16, 11, 17, 14, 15, 10, 18 — form one data set.","img":"/assets/vocab-images/data.svg","imgAlt":"Illustration of Data set: All the values that were collected.","cs":false,"formal":"The whole collection of values that were gathered or measured.","formalEs":"Toda la colección de valores que se recopilaron o midieron."},{"term":"Decimal Division Algorithm","termEs":"Algoritmo de división decimal","def":"Slide both decimal points right the same amount. Then divide.","defEs":"Mueve ambos puntos decimales a la derecha igual cantidad de lugares. Luego divide.","example":"1.2 ÷ 0.4 becomes 12 ÷ 4 = 3","img":"/assets/vocab-images/decimal-division-algorithm.svg","imgAlt":"Illustration of Decimal Division Algorithm: Slide both decimal points right the same amount. Then divide.","cs":false,"formal":"The steps for dividing decimals: slide the divisor's decimal point right until the divisor is a whole number, slide the dividend's point right the same number of places, then divide.","formalEs":"Los pasos para dividir decimales: desliza el punto decimal del divisor a la derecha hasta que sea un número entero, desliza el punto del dividendo a la derecha el mismo número de lugares y luego divide.","exampleEs":"1.2 ÷ 0.4 pasa a 12 ÷ 4 = 3","exampleFormal":"8.4 ÷ 2.1 → move the point in both → 84 ÷ 21 → divide, multiply, subtract, bring down → 4"},{"term":"Decimal grid","termEs":"Cuadrícula decimal","def":"A grid of 100 squares. Each square is one percent.","defEs":"Una cuadrícula de 100 cuadros. Cada cuadro es el uno por ciento.","example":"40 shaded squares out of 100 = 40%","img":"/assets/vocab-images/percent-part.svg","imgAlt":"Illustration of Decimal grid: A grid of 100 squares. Each square is one percent.","cs":false,"formal":"A 10-by-10 grid of 100 squares. Shading squares shows a percent directly, one square per percent.","formalEs":"Una cuadrícula de 10 por 10 con 100 cuadros. Sombrear cuadros muestra un porcentaje directamente, un cuadro por cada uno por ciento."},{"term":"Decimal places","termEs":"Cifras decimales","def":"How many digits are after the dot.","defEs":"Cuántos dígitos hay después del punto decimal.","example":"3.14 has two digits after the dot","img":"/assets/vocab-images/decimal.svg","imgAlt":"Illustration of Decimal places: How many digits are after the dot.","cs":false,"formal":"How many digits come after the decimal point.","exampleEs":"3.14 tiene dos dígitos después del punto","exampleFormal":"3.4 (1 place) × 2.6 (1 place) = 8.84 (2 places total)"},{"term":"decompose","termEs":"descomponer","def":"Break a number or shape into smaller parts.","defEs":"Separar un número o una figura en partes más pequeñas.","example":"78.5 = 70 + 8.5","img":"/assets/vocab-images/decompose.svg","imgAlt":"Illustration of decompose: Break a number or shape into smaller parts.","cs":false,"formal":"To break a number into parts that add, subtract, multiply, or divide back to it.","formalEs":"Separar un número en partes que se combinan para volver a formarlo.","exampleEs":"78.5 = 70 + 8.5","exampleFormal":"78.5 = 70 + 8.5, and also 157 ÷ 2 — both rebuild the same number."},{"term":"define the variables","termEs":"definir las variables","def":"Say what each letter stands for.","defEs":"Decir qué representa cada letra.","example":"“Let m = months and c = total cost” — written before you solve.","img":"/assets/vocab-images/variable.svg","imgAlt":"Illustration of define the variables: Say what each letter stands for.","cs":false,"formal":"To state exactly what quantity each letter in an equation stands for.","formalEs":"Decir exactamente qué cantidad representa cada letra de una ecuación."},{"term":"dependent variable","termEs":"variable dependiente","def":"The amount that changes when the other does.","defEs":"La cantidad que cambia cuando cambia la otra.","example":"Total cost = $24.95 × months — the cost RESPONDS to the months.","img":"/assets/vocab-images/variable.svg","imgAlt":"Illustration of dependent variable: The amount that changes when the other does.","cs":false,"formal":"The quantity that changes in response to the independent variable.","formalEs":"La cantidad que cambia en respuesta a la variable independiente."},{"term":"depends on","termEs":"depende de","def":"It changes when the other one changes.","defEs":"Cambia cuando la otra cantidad cambia.","example":"“Total cost depends on the number of months.” Responder first, chooser last.","img":"/assets/vocab-images/variable.svg","imgAlt":"Illustration of depends on: It changes when the other one changes.","cs":false,"formal":"One quantity depends on another when changing the first causes the second to change.","formalEs":"Una cantidad depende de otra cuando cambiar la primera hace cambiar la segunda."},{"term":"Describe the Data Using the Median","termEs":"Describir los datos con la mediana","def":"Use the middle value to say what is typical.","defEs":"Usa el valor del medio para decir qué es típico.","example":"3, 5, 9: the middle is 5","img":"/assets/vocab-images/median.svg","imgAlt":"Illustration of Describe the Data Using the Median: Use the middle value to say what is typical.","cs":false,"formal":"Using the middle value of the ordered data to say what is typical for the whole set.","formalEs":"Usar el valor del medio de los datos ordenados para decir qué es típico en todo el conjunto.","exampleEs":"3, 5, 9: el del medio es 5","exampleFormal":"2, 4, 4, 6, 9 → median 4"},{"term":"Determine the Whole Given the Part and Percent","termEs":"Hallar el total dados la parte y el porcentaje","def":"Use a part and its percent to find the whole.","defEs":"Usar una parte y su porcentaje para hallar el total.","example":"30 is 20% of what? 30 ÷ 0.2 = 150","img":"/assets/vocab-images/percent-base.svg","imgAlt":"Illustration of Determine the Whole Given the Part and Percent: Use a part and its percent to find the whole.","cs":false,"formal":"Working backwards from a part and its percent to find the whole amount it came from.","formalEs":"Trabajar al revés a partir de una parte y su porcentaje para hallar el total del que proviene.","exampleEs":"30 es el 20 % de qué? 30 ÷ 0.2 = 150","exampleFormal":"$42 is 60% of what? → $70"},{"term":"Deviation","termEs":"Desviación","def":"How far a number is from the mean.","defEs":"Qué tan lejos está un número de la media.","example":"If mean = 20 and value = 17, deviation = 17 − 20 = −3 (3 below the mean)","img":"/assets/vocab-images/mean-absolute-deviation.svg","imgAlt":"Illustration of Deviation: How far a number is from the mean.","cs":false},{"term":"Diagonal","termEs":"Diagonal","def":"A line between two corners that are not side by side.","defEs":"Una línea entre dos esquinas que no están una al lado de la otra.","example":"Corner to opposite corner.","img":"/assets/vocab-images/rhombus.svg","imgAlt":"Illustration of Diagonal: A line between two corners that are not side by side.","cs":false,"formal":"A segment that joins two corners that are not next to each other.","formalEs":"Un segmento que une dos esquinas que no están una junto a la otra."},{"term":"Dimensions","termEs":"Dimensiones","def":"How long, how wide, and how tall something is.","defEs":"Qué tan largo, ancho y alto es algo.","example":"A box with dimensions 4 × 3 × 2 means l = 4, w = 3, h = 2","img":"/assets/vocab-images/dimensions.svg","imgAlt":"Illustration of Dimensions: How long, how wide, and how tall something is.","cs":false,"formal":"How long, how wide, and how tall a shape is.","formalEs":"Qué tan largo, ancho y alto es una figura."},{"term":"Discount","termEs":"Descuento","def":"Money taken off a price.","defEs":"Dinero que se quita al precio.","example":"$40 minus a $10 discount is $30","img":"/assets/vocab-images/discount.svg","imgAlt":"Illustration of Discount: Money taken off a price.","cs":false,"formal":"Money taken off the first price to make it cheaper.","formalEs":"Dinero que se quita del precio original para que sea más barato.","exampleEs":"$40 menos $10 de descuento son $30","exampleFormal":"20% off $50 → discount is $10"},{"term":"Display Data with Box Plots","termEs":"Representar datos con diagramas de caja","def":"Draw a box plot from five key numbers.","defEs":"Dibujar un diagrama de caja con cinco números clave.","example":"minimum | Q1 [ median ] Q3 | maximum","img":"/assets/vocab-images/concept-display-data-with-box-plots.svg","imgAlt":"Illustration of Display Data with Box Plots: Draw a box plot from five key numbers.","cs":false,"formal":"Show a data set's five-number summary in a box-and-whisker display.","formalEs":"Mostrar el resumen de cinco números de un conjunto de datos en un diagrama de caja y bigotes."},{"term":"Display Data with Histograms","termEs":"Representar datos con histogramas","def":"Sort data into groups and draw a bar for each group.","defEs":"Agrupar los datos y dibujar una barra para cada grupo.","example":"Each touching bar shows how many values fall in one interval.","img":"/assets/vocab-images/concept-display-data-with-histograms.svg","imgAlt":"Illustration of Display Data with Histograms: Sort data into groups and draw a bar for each group.","cs":false,"formal":"Group numerical data into intervals and show each interval's frequency with a bar.","formalEs":"Agrupar datos numéricos en intervalos y mostrar la frecuencia de cada intervalo con una barra."},{"term":"Distance","termEs":"Distancia","def":"How far apart two points are. It is never negative.","defEs":"Qué tan separados están dos puntos. Nunca es negativa.","example":"The distance from -3 to 4 on a number line is |-3| + |4| = 3 + 4 = 7 units","img":"/assets/vocab-images/distance.svg","imgAlt":"Illustration of Distance: How far apart two points are. It is never negative.","cs":false,"formalEs":"Qué tan separados están dos puntos. Nunca es negativo."},{"term":"distance between vertices","termEs":"distancia entre vértices","def":"How far apart two corners are.","defEs":"Qué tan separadas están dos esquinas.","example":"From (5, 3) to (5, −3.75) is 6.75","img":"/assets/vocab-images/distance.svg","imgAlt":"Illustration of distance between vertices: How far apart two corners are.","cs":false,"formal":"When two vertices share an x- or y-coordinate, the distance between them is the absolute difference of the other coordinates.","formalEs":"Cuando dos vértices comparten una coordenada x o y, la distancia es la diferencia absoluta de las otras coordenadas.","exampleEs":"De (5, 3) a (5, −3.75) hay 6.75","exampleFormal":"(2, 4) and (5, 4) share y, so the side is |5 − 2| = 3 units."},{"term":"Distance on the Coordinate Plane","termEs":"Distancia en el plano de coordenadas","def":"How far apart two points are on a grid.","defEs":"Qué tan separados están dos puntos en una cuadrícula.","example":"From (−2, 3) to (5, 3): |5 − (−2)| = 7 units.","img":"/assets/vocab-images/concept-distance-on-the-coordinate-plane.svg","imgAlt":"Illustration of Distance on the Coordinate Plane: How far apart two points are on a grid.","cs":false,"formal":"The nonnegative distance between points, found from the absolute difference of coordinates on a horizontal or vertical line.","formalEs":"La distancia no negativa entre puntos, que se halla con la diferencia absoluta de las coordenadas en una línea horizontal o vertical."},{"term":"Distributive Property","termEs":"Propiedad distributiva","def":"Multiply by each part inside the ( ).","defEs":"Multiplicar por cada parte dentro del paréntesis.","example":"3(4 + 5) = 3 × 4 + 3 × 5","img":"/assets/vocab-images/distributive-property.svg","imgAlt":"Illustration of Distributive Property: Multiply by each part inside the ( ).","cs":false,"formal":"Multiplying a number by everything inside the parentheses: a(b + c) = ab + ac.","formalEs":"Multiplicar un número por todo lo que está dentro del paréntesis: a(b + c) = ab + ac.","exampleEs":"3(4 + 5) = 3 × 4 + 3 × 5","exampleFormal":"3(4 + 5) = 3×4 + 3×5 = 12 + 15 = 27 — the 3 gets 'distributed' to both the 4 and the 5"},{"term":"Divide Decimals","termEs":"Dividir decimales","def":"Slide both decimal points right, then divide.","defEs":"Desliza ambos puntos decimales a la derecha y luego divide.","example":"1.2 ÷ 0.4 becomes 12 ÷ 4","img":"/assets/vocab-images/concept-divide-decimals.svg","imgAlt":"Illustration of Divide Decimals: Slide both decimal points right, then divide.","cs":false,"formal":"Find a quotient with decimals by sliding both decimal points right until the divisor is a whole number.","formalEs":"Hallar un cociente con decimales deslizando ambos puntos decimales a la derecha hasta que el divisor sea un número entero.","exampleEs":"1.2 ÷ 0.4 pasa a 12 ÷ 4","exampleFormal":"8.4 ÷ 2.1 = 84 ÷ 21 = 4"},{"term":"Divide Fractions","termEs":"Dividir fracciones","def":"Keep the first, flip the second, then multiply.","defEs":"Deja la primera, voltea la segunda y luego multiplica.","example":"1/2 ÷ 1/4 = 1/2 × 4 = 2","img":"/assets/vocab-images/concept-divide-fractions.svg","imgAlt":"Illustration of Divide Fractions: Keep the first, flip the second, then multiply.","cs":false,"formal":"Multiply the first fraction by the reciprocal of the second fraction.","formalEs":"Multiplicar la primera fracción por el recíproco de la segunda fracción.","exampleEs":"1/2 ÷ 1/4 = 1/2 × 4 = 2","exampleFormal":"2/3 ÷ 1/4 = 2/3 × 4/1 = 8/3"},{"term":"Divide Mixed Numbers","termEs":"Dividir números mixtos","def":"Change both to improper fractions. Then divide the fractions.","defEs":"Cambia ambos a fracciones impropias. Luego divide las fracciones.","example":"2 1/2 ÷ 1 1/4 = 5/2 ÷ 5/4 = 5/2 × 4/5 = 2","img":"/assets/vocab-images/concept-divide-mixed-numbers.svg","imgAlt":"Illustration of Divide Mixed Numbers: Change both to improper fractions. Then divide the fractions.","cs":false,"formal":"Change mixed numbers to improper fractions, then multiply by the reciprocal.","formalEs":"Cambiar los números mixtos a fracciones impropias y luego multiplicar por el recíproco."},{"term":"Divide Multi-Digit Numbers","termEs":"Dividir números de varias cifras","def":"Split a big number into equal groups.","defEs":"Repartir un número grande en grupos iguales.","example":"1,344 ÷ 12 = 112","img":"/assets/vocab-images/concept-divide-multi-digit-numbers.svg","imgAlt":"Illustration of Divide Multi-Digit Numbers: Split a big number into equal groups.","cs":false,"formal":"Separate a multi-digit number into equal groups to find a quotient.","formalEs":"Separar un número de varias cifras en grupos iguales para hallar un cociente.","exampleEs":"1,344 ÷ 12 = 112","exampleFormal":"1,344 ÷ 12 = 112"},{"term":"Divide Whole Numbers by Fractions","termEs":"Dividir números enteros entre fracciones","def":"Find how many fraction pieces fit in the number.","defEs":"Hallar cuántas partes de la fracción caben en el número.","example":"6 ÷ 1/2 = 12 halves fit in 6","img":"/assets/vocab-images/concept-divide-whole-numbers-by-fractions.svg","imgAlt":"Illustration of Divide Whole Numbers by Fractions: Find how many fraction pieces fit in the number.","cs":false,"formal":"Find how many fractional groups fit in a whole number by multiplying by the reciprocal.","formalEs":"Hallar cuántos grupos fraccionarios caben en un número entero multiplicando por el recíproco.","exampleEs":"6 ÷ 1/2 = 12 mitades caben en 6","exampleFormal":"4 ÷ 1/2 = 4 × 2 = 8"},{"term":"Dividend","termEs":"Dividendo","def":"The number you split up.","defEs":"El número que se reparte en grupos.","example":"In 12 ÷ 3, the 12 is the dividend","img":"/assets/vocab-images/dividend.svg","imgAlt":"Illustration of Dividend: The number you split up.","cs":false,"formal":"The total number being divided into equal groups (the number inside the division bracket).","formalEs":"El número total que se divide en partes iguales (el número dentro de la casilla de división).","exampleEs":"En 12 ÷ 3, el 12 es el dividendo","exampleFormal":"In 156 ÷ 12 = 13, the dividend is 156 — it is the total being split up"},{"term":"Divisible","termEs":"Divisible","def":"Can be split with none left over.","defEs":"Se puede dividir sin que sobre nada.","example":"12 ÷ 3 = 4 with nothing left over","img":"/assets/vocab-images/divide.svg","imgAlt":"Illustration of Divisible: Can be split with none left over.","cs":false,"formal":"A number you can divide evenly, with nothing left over.","formalEs":"Un número que se puede dividir sin que sobre nada.","exampleEs":"12 ÷ 3 = 4 sin que sobre nada","exampleFormal":"15 ÷ 3 = 5 with no remainder, so 15 is divisible by 3"},{"term":"Division of Fractions","termEs":"División de fracciones","def":"Find how many small pieces fit in a big one.","defEs":"Hallar cuántas partes pequeñas caben en una grande.","example":"3 ÷ 1/2 asks how many halves fit in 3; the answer is 6.","img":"/assets/vocab-images/concept-division-of-fractions.svg","imgAlt":"Illustration of Division of Fractions: Find how many small pieces fit in a big one.","cs":false,"formal":"Finding how many groups of one fraction fit inside another amount.","formalEs":"Hallar cuántos grupos de una fracción caben dentro de otra cantidad."},{"term":"Division Property of Equality","termEs":"Propiedad de división de la igualdad","def":"Divide both sides by the same number, not zero. They stay equal.","defEs":"Divide ambos lados entre el mismo número, que no sea cero. Siguen siendo iguales.","example":"3x = 12 → x = 4","img":"/assets/vocab-images/equation.svg","imgAlt":"Illustration of Division Property of Equality: Divide both sides by the same number, not zero. They stay equal.","cs":false,"formal":"Dividing both sides by the same nonzero number keeps an equation balanced.","formalEs":"Dividir ambos lados entre el mismo número distinto de cero mantiene una ecuación equilibrada.","exampleEs":"3x = 12 → x = 4","exampleFormal":"Both sides ÷ 3"},{"term":"Divisor","termEs":"Divisor","def":"The number you divide by.","defEs":"El número entre el que divides.","example":"In 12 ÷ 3, the 3 is the divisor","img":"/assets/vocab-images/divisor.svg","imgAlt":"Illustration of Divisor: The number you divide by.","cs":false,"formal":"The number of equal groups you are dividing into (the number outside the division bracket).","formalEs":"El número de grupos iguales en que divides (el número fuera de la galera de división).","exampleEs":"En 12 ÷ 3, el 3 es el divisor","exampleFormal":"In 1,344 ÷ 12 = 112, the divisor is 12 — the number of equal groups"},{"term":"doer of math","termEs":"persona que hace matemáticas","def":"Anyone who uses math. That is all of us.","defEs":"Cualquiera que usa matemáticas. Somos todos.","example":"Splitting a bill 4 ways at dinner — that is a doer of math.","img":"/assets/vocab-images/doer-of-math.svg","imgAlt":"Illustration of doer of math: Anyone who uses math. That is all of us.","cs":false,"formal":"Anyone who uses mathematical thinking — which is everyone, every day.","formalEs":"Cualquiera que use el pensamiento matemático, es decir, todos, todos los días."},{"term":"Double number line","termEs":"Recta numérica doble","def":"Two number lines side by side. Marks that line up go together.","defEs":"Dos rectas numéricas juntas. Las marcas que coinciden van juntas.","example":"Cups of apple juice 0, 3, 6, 12 above cups of fruit drink 0, 5, 10, 20.","img":"/assets/vocab-images/number-line.svg","imgAlt":"Illustration of Double number line: Two number lines side by side. Marks that line up go together.","cs":false,"formal":"Two number lines lined up so matching tick marks show the two quantities in a ratio at the same time.","formalEs":"Dos rectas numéricas alineadas para que las marcas correspondientes muestren las dos cantidades de una razón al mismo tiempo."},{"term":"Equal sign","termEs":"Signo igual","def":"The = sign. Both sides are the same.","defEs":"El signo =. Ambos lados son iguales.","example":"7 + 3 = 10 — both sides equal 10","img":"/assets/vocab-images/equation.svg","imgAlt":"Illustration of Equal sign: The = sign. Both sides are the same.","cs":false,"formal":"The = sign, showing both sides are the same.","formalEs":"El signo =, que muestra que ambos lados son iguales."},{"term":"Equations and Inequalities Problem Solving","termEs":"Resolución de problemas con ecuaciones y desigualdades","def":"Use = for one exact answer, or < or > for many answers.","defEs":"Usar = para una respuesta exacta, o < o > para muchas respuestas.","example":"Exactly $20: 4x = 20. At most $20: 4x ≤ 20.","img":"/assets/vocab-images/concept-equations-and-inequalities-problem-solving.svg","imgAlt":"Illustration of Equations and Inequalities Problem Solving: Use = for one exact answer, or < or > for many answers.","cs":false,"formal":"Use an equation for one exact value or an inequality for a range of values in a real situation.","formalEs":"Usar una ecuación para un valor exacto o una desigualdad para un rango de valores en una situación real."},{"term":"Equivalent division","termEs":"División equivalente","def":"Multiply both numbers by 10 or 100. The answer is the same.","defEs":"Multiplica ambos números por 10 o 100. La respuesta es igual.","example":"12 ÷ 0.4 = 120 ÷ 4 = 30","img":"/assets/vocab-images/divide.svg","imgAlt":"Illustration of Equivalent division: Multiply both numbers by 10 or 100. The answer is the same.","cs":false,"formal":"Multiplying both numbers by 10 or 100 gives the same answer.","formalEs":"Multiplicar ambos números por 10 o 100 da la misma respuesta.","exampleEs":"12 ÷ 0.4 = 120 ÷ 4 = 30","exampleFormal":"7.56 ÷ 0.12 = 756 ÷ 12 = 63 (both multiplied by 100)"},{"term":"Evaluate Expressions","termEs":"Evaluar expresiones","def":"Put numbers in for the letters, then work in order.","defEs":"Poner números en lugar de las letras y calcular en orden.","example":"2n + 1 with n = 5 is 11","img":"/assets/vocab-images/concept-evaluate-expressions.svg","imgAlt":"Illustration of Evaluate Expressions: Put numbers in for the letters, then work in order.","cs":false,"formal":"Find the value of an expression by substituting numbers and following the order of operations.","formalEs":"Hallar el valor de una expresión sustituyendo números y siguiendo el orden de las operaciones.","exampleEs":"2n + 1 con n = 5 es 11","exampleFormal":"If x = 4, then 3x + 2 = 3(4) + 2 = 14."},{"term":"Expand","termEs":"Desarrollar","def":"Multiply so the ( ) are gone.","defEs":"Multiplicar para que desaparezcan los paréntesis.","example":"3(x + 2) = 3x + 6","img":"/assets/vocab-images/distributive-property.svg","imgAlt":"Illustration of Expand: Multiply so the ( ) are gone.","cs":false,"formal":"To multiply out the parentheses in an expression.","formalEs":"Multiplicar lo que está dentro del paréntesis en una expresión.","exampleEs":"3(x + 2) = 3x + 6","exampleFormal":"Expand 2(n + 6): multiply 2 × n = 2n and 2 × 6 = 12, so 2(n + 6) = 2n + 12"},{"term":"Expanded form","termEs":"Forma desarrollada","def":"A power written out in full, like 2 × 2 × 2.","defEs":"Una potencia escrita completa, como 2 × 2 × 2.","example":"2^3 = 2 × 2 × 2","img":"/assets/vocab-images/exponent.svg","imgAlt":"Illustration of Expanded form: A power written out in full, like 2 × 2 × 2.","cs":false,"formal":"A power written out as a product of its factors.","formalEs":"Una potencia escrita como el producto de sus factores."},{"term":"Extreme value","termEs":"Valor extremo","def":"The lowest or highest value, far from the rest.","defEs":"El valor más bajo o más alto, lejos de los demás.","example":"An extreme value stretches the range.","img":"/assets/vocab-images/range.svg","imgAlt":"Illustration of Extreme value: The lowest or highest value, far from the rest.","cs":false,"formal":"The least or greatest value in a data set, far from the rest.","formalEs":"El valor menor o mayor de un conjunto de datos, lejos del resto."},{"term":"Face","termEs":"Cara","def":"One flat side of a solid shape.","defEs":"Un lado plano de una figura sólida.","example":"A rectangular prism has 6 faces: top, bottom, front, back, left, right","img":"/assets/vocab-images/rectangular-prism.svg","imgAlt":"Illustration of Face: One flat side of a solid shape.","cs":false},{"term":"Factor an expression","termEs":"Factorizar una expresión","def":"Pull out a number that is in every part.","defEs":"Sacar un número que está en todas las partes.","example":"6x + 9 = 3(2x + 3)","img":"/assets/vocab-images/distributive-property.svg","imgAlt":"Illustration of Factor an expression: Pull out a number that is in every part.","cs":false,"formal":"Pull a shared factor outside parentheses.","formalEs":"Sacar un factor común fuera de los paréntesis.","exampleEs":"6x + 9 = 3(2x + 3)","exampleFormal":"18x + 24 = 6(3x + 4)"},{"term":"Factor pair","termEs":"Par de factores","def":"Two numbers that give the number as a product.","defEs":"Dos números cuyo producto es ese número.","example":"3 × 4 = 12 and 2 × 6 = 12","img":"/assets/vocab-images/factor.svg","imgAlt":"Illustration of Factor pair: Two numbers that give the number as a product.","cs":false,"formal":"Two factors that multiply to make a number. In a word problem, one is the number of groups and the other is the size of each group.","formalEs":"Dos factores que se multiplican para formar un número. En un problema, uno es la cantidad de grupos y el otro el tamaño de cada grupo.","exampleEs":"3 × 4 = 12 y 2 × 6 = 12","exampleFormal":"48 = 2 × 24, so 2 packs of 24 pencils"},{"term":"Factor tree","termEs":"Árbol de factores","def":"A picture that splits a number down to prime numbers.","defEs":"Un dibujo que separa un número hasta sus números primos.","example":"12 → 2 × 2 × 3","img":"/assets/vocab-images/prime-factorization.svg","imgAlt":"Illustration of Factor tree: A picture that splits a number down to prime numbers.","cs":false,"formal":"A picture that splits a number into its prime numbers, step by step.","formalEs":"Un dibujo que separa un número en sus números primos, paso a paso.","exampleEs":"12 → 2 × 2 × 3","exampleFormal":"24 → 4 × 6 → (2 × 2) × (2 × 3) → 2 × 2 × 2 × 3"},{"term":"Find Factors and Multiples","termEs":"Hallar factores y múltiplos","def":"List the factors and multiples, then see what two numbers share.","defEs":"Hacer la lista de factores y múltiplos y ver qué comparten dos números.","example":"GCF of 48 and 36 is 12 · LCM of 6 and 8 is 24","img":"/assets/vocab-images/factor.svg","imgAlt":"Illustration of Find Factors and Multiples: List the factors and multiples, then see what two numbers share.","cs":false,"formal":"Listing what divides a number evenly (its factors) and what it divides into evenly (its multiples), then finding what two numbers share.","formalEs":"Listar lo que divide un número exactamente (sus factores) y lo que el número forma al contar de esa cantidad (sus múltiplos), y luego hallar lo que dos números comparten."},{"term":"Five-number summary","termEs":"Resumen de cinco números","def":"Five numbers that sum up the data, from lowest to highest.","defEs":"Cinco números que resumen los datos, del menor al mayor.","example":"6, 8, 14, 19, 22 — the five values a box plot is built from.","img":"/assets/vocab-images/box-plot.svg","imgAlt":"Illustration of Five-number summary: Five numbers that sum up the data, from lowest to highest.","cs":false,"formal":"The minimum, first quartile, median, third quartile, and maximum of a data set.","formalEs":"El mínimo, el primer cuartil, la mediana, el tercer cuartil y el máximo de un conjunto de datos."},{"term":"Formula","termEs":"Fórmula","def":"A rule written with letters and numbers.","defEs":"Una regla escrita con letras y números.","example":"A = 5 × 3 = 15","img":"/assets/vocab-images/area-of-parallelograms.svg","imgAlt":"Illustration of Formula: A rule written with letters and numbers.","cs":false,"formal":"A math rule written with symbols.","formalEs":"Una regla matemática escrita con símbolos.","exampleEs":"A = 5 × 3 = 15","exampleFormal":"A = b × h means Area equals base times height; for a parallelogram with b = 6 and h = 4, A = 24"},{"term":"Fraction Division Problem Solving","termEs":"Resolución de problemas de división de fracciones","def":"Divide with fractions to find how many groups or how big.","defEs":"Dividir con fracciones para hallar cuántos grupos o qué tamaño.","example":"Number of groups = total amount ÷ amount in each group.","img":"/assets/vocab-images/concept-fraction-division-problem-solving.svg","imgAlt":"Illustration of Fraction Division Problem Solving: Divide with fractions to find how many groups or how big.","cs":false,"formal":"Use fraction division to find an unknown number of groups or the size of each group.","formalEs":"Usar la división de fracciones para hallar una cantidad desconocida de grupos o el tamaño de cada grupo."},{"term":"Fractions, Decimals, and Percents","termEs":"Fracciones, decimales y porcentajes","def":"Three ways to write the same part of a whole.","defEs":"Tres maneras de escribir la misma parte de un todo.","example":"1/2 = 0.5 = 50%","img":"/assets/vocab-images/concept-fractions-decimals-and-percents.svg","imgAlt":"Illustration of Fractions, Decimals, and Percents: Three ways to write the same part of a whole.","cs":false,"formal":"Three equivalent ways to name the same part of a whole.","formalEs":"Tres maneras equivalentes de nombrar la misma parte de un todo.","exampleEs":"1/2 = 0.5 = 50 %","exampleFormal":"1/2 = 0.5 = 50%"},{"term":"Frequency table","termEs":"Tabla de frecuencias","def":"A table that counts how many values are in each group.","defEs":"Una tabla que cuenta cuántos valores hay en cada grupo.","example":"10–19 . . . 3 means three values are between 10 and 19.","img":"/assets/vocab-images/frequency.svg","imgAlt":"Illustration of Frequency table: A table that counts how many values are in each group.","cs":false,"formal":"A table that lists each interval and how many values fall in it.","formalEs":"Una tabla que muestra cada intervalo y cuántos valores caen en él."},{"term":"Gap","termEs":"Brecha","def":"An empty space where there is no data.","defEs":"Un espacio vacío donde no hay datos.","example":"Nothing between 11 and 32 on the number line.","img":"/assets/vocab-images/histogram.svg","imgAlt":"Illustration of Gap: An empty space where there is no data.","cs":false,"formal":"A space on a display where no data values fall.","formalEs":"Un espacio en la representación donde no cae ningún valor de los datos."},{"term":"gear","termEs":"engranaje","def":"A wheel with teeth that turns another wheel.","defEs":"Una rueda con dientes que hace girar a otra.","example":"A 48-tooth gear turns a 12-tooth gear","img":"/assets/vocab-images/gear.svg","imgAlt":"Illustration of gear: A wheel with teeth that turns another wheel.","cs":false,"formal":"A toothed wheel that passes motion to another toothed wheel through a chain.","formalEs":"Una rueda con dientes que transmite el movimiento a otra rueda con dientes por medio de una cadena.","exampleEs":"Un engranaje de 48 dientes mueve uno de 12","exampleFormal":"A 48-tooth pedal gear pulling a 12-tooth wheel gear through the chain."},{"term":"generalization","termEs":"generalización","def":"A rule that is true for a whole pattern.","defEs":"Una regla que es cierta para todo un patrón.","example":"1 → 3, 2 → 5, 3 → 7 … so n → 2n + 1, for ANY n.","img":"/assets/vocab-images/generalization.svg","imgAlt":"Illustration of generalization: A rule that is true for a whole pattern.","cs":false,"formal":"A statement that is true for a whole pattern, made by noticing repeated calculations.","formalEs":"Una afirmación verdadera para todo un patrón, hecha al notar cálculos repetidos."},{"term":"Graph Inequalities","termEs":"Representar desigualdades en una recta numérica","def":"Show all the answers on a line with a dot and arrow.","defEs":"Mostrar todas las respuestas en una recta con un punto y una flecha.","example":"x > 3 uses an open circle at 3 and an arrow to the right.","img":"/assets/vocab-images/concept-graph-inequalities.svg","imgAlt":"Illustration of Graph Inequalities: Show all the answers on a line with a dot and arrow.","cs":false,"formal":"Show every solution to an inequality on a number line with a boundary point and an arrow.","formalEs":"Mostrar cada solución de una desigualdad en una recta numérica con un punto límite y una flecha."},{"term":"Graph on the Coordinate Plane","termEs":"Representar en el plano de coordenadas","def":"Mark a point: go across first, then up or down.","defEs":"Marcar un punto: primero a lo ancho, luego arriba o abajo.","example":"(3, 2): 3 across, 2 up","img":"/assets/vocab-images/concept-graph-on-the-coordinate-plane.svg","imgAlt":"Illustration of Graph on the Coordinate Plane: Mark a point: go across first, then up or down.","cs":false,"formal":"Plot a point by moving horizontally to its x-coordinate and vertically to its y-coordinate.","formalEs":"Ubicar un punto moviéndose horizontalmente hasta su coordenada x y verticalmente hasta su coordenada y.","exampleEs":"(3, 2): 3 a la derecha, 2 arriba","exampleFormal":"For (3, −2), move right 3 and down 2."},{"term":"Graph Ratio Tables","termEs":"Representar tablas de razones en una gráfica","def":"Plot each pair from the table as a point.","defEs":"Marcar cada pareja de la tabla como un punto.","example":"The ratio pairs 2:3 and 4:6 become points (2,3) and (4,6).","img":"/assets/vocab-images/concept-graph-ratio-tables.svg","imgAlt":"Illustration of Graph Ratio Tables: Plot each pair from the table as a point.","cs":false,"formal":"Plot the paired values from a ratio table as ordered pairs.","formalEs":"Ubicar los valores emparejados de una tabla de razones como pares ordenados."},{"term":"Greater than 100%","termEs":"Mayor que 100 %","def":"More than the whole thing. It is over 100%.","defEs":"Más que el total. Es más de 100 %.","example":"150% of 40 is 60","img":"/assets/vocab-images/percent.svg","imgAlt":"Illustration of Greater than 100%: More than the whole thing. It is over 100%.","cs":false,"formal":"More than one whole. A percent above 100 means the amount is larger than the thing it is being compared to.","formalEs":"Más de un entero. Un porcentaje mayor que 100 significa que la cantidad es mayor que aquello con lo que se compara.","exampleEs":"150 % de 40 es 60","exampleFormal":"150% of the gray kitten = 1.5 times its weight"},{"term":"Greatest common factor (GCF)","termEs":"Máximo común divisor (MCD)","def":"The biggest number that goes into both.","defEs":"El número más grande que divide a ambos.","example":"For 12 and 18, the biggest shared number is 6","img":"/assets/vocab-images/greatest-common-factor.svg","imgAlt":"Illustration of Greatest common factor (GCF): The biggest number that goes into both.","cs":false,"formal":"The largest number that is a factor of two or more numbers. It answers “how many equal groups can I make?”","formalEs":"El número más grande que es factor de dos o más números. Responde “¿cuántos grupos iguales puedo formar?”","exampleEs":"Para 12 y 18, el número compartido más grande es 6","exampleFormal":"48 and 36 share 1, 2, 3, 4, 6, 12 → GCF = 12"},{"term":"Grouping symbols","termEs":"Símbolos de agrupación","def":"Marks like ( ) that tell you what to do first.","defEs":"Marcas como ( ) que dicen qué hacer primero.","example":"2 × (3 + 4): do 3 + 4 first","img":"/assets/vocab-images/expression.svg","imgAlt":"Illustration of Grouping symbols: Marks like ( ) that tell you what to do first.","cs":false,"formal":"Parentheses or brackets; the work inside them is done first.","formalEs":"Paréntesis o corchetes; el trabajo dentro de ellos se hace primero.","exampleEs":"2 × (3 + 4): primero 3 + 4","exampleFormal":"(9 − 7) is worked before anything else."},{"term":"growth","termEs":"crecimiento","def":"How much more you can do now than before.","defEs":"Cuánto más puedes hacer ahora que antes.","example":"In Unit 1 you estimated 80 riders; now you find 480 riders per hour.","img":"/assets/vocab-images/rate.svg","imgAlt":"Illustration of growth: How much more you can do now than before.","cs":false,"formal":"The change between what you could do before and what you can do now.","formalEs":"El cambio entre lo que podías hacer antes y lo que puedes hacer ahora."},{"term":"Halfway value","termEs":"Valor intermedio","def":"The spot halfway between the two middle ones.","defEs":"El punto a medio camino entre los dos números del medio.","example":"Middle values 4 and 6: halfway is 5","img":"/assets/vocab-images/median.svg","imgAlt":"Illustration of Halfway value: The spot halfway between the two middle ones.","cs":false,"formal":"The number exactly between the two middle values of an even-count data set.","formalEs":"El número que está exactamente entre los dos valores centrales de un conjunto con una cantidad par de datos.","exampleEs":"Valores del medio 4 y 6: a medio camino está 5","exampleFormal":"Between 18 and 22, the halfway value is 20."},{"term":"Horizontal distance","termEs":"Distancia horizontal","def":"How far apart two points are, left to right.","defEs":"Qué tan separados están dos puntos, de izquierda a derecha.","example":"From (1, 2) to (6, 2) is 5","img":"/assets/vocab-images/distance.svg","imgAlt":"Illustration of Horizontal distance: How far apart two points are, left to right.","cs":false,"formal":"How far apart two points are going left or right.","formalEs":"Qué tan separados están dos puntos yendo a la izquierda o a la derecha.","exampleEs":"De (1, 2) a (6, 2) hay 5","exampleFormal":"From (-2, 3) to (5, 3): count from -2 to 5 = 7 units across"},{"term":"Identity Property","termEs":"Propiedad de identidad","def":"Add 0 or multiply by 1. The number stays.","defEs":"Sumar 0 o multiplicar por 1 no cambia nada.","example":"7 + 0 = 7 and 7 × 1 = 7","img":"/assets/vocab-images/identity-property.svg","imgAlt":"Illustration of Identity Property: Add 0 or multiply by 1. The number stays.","cs":false,"formal":"Adding 0 or multiplying by 1 keeps the same value.","formalEs":"Sumar 0 o multiplicar por 1 mantiene el mismo valor.","exampleEs":"7 + 0 = 7 y 7 × 1 = 7","exampleFormal":"9 + 0 = 9 (zero is the identity for addition); 6 × 1 = 6 (one is the identity for multiplication)"},{"term":"independent variable","termEs":"variable independiente","def":"The amount you choose. The other amount depends on it.","defEs":"La cantidad que eliges. La otra cantidad depende de ella.","example":"Miguel picks the number of MONTHS — nothing else decides it for him.","img":"/assets/vocab-images/variable.svg","imgAlt":"Illustration of independent variable: The amount you choose. The other amount depends on it.","cs":false,"formal":"The input quantity in a model, chosen or observed.","formalEs":"La cantidad de entrada de un modelo, elegida u observada."},{"term":"ingenuity","termEs":"ingenio","def":"Finding new and clever ways to solve a problem.","defEs":"Hallar maneras nuevas y creativas de resolver un problema.","example":"The Penny Farthing's huge wheel, then chains and gears — two clever fixes.","img":"/assets/vocab-images/ingenuity.svg","imgAlt":"Illustration of ingenuity: Finding new and clever ways to solve a problem.","cs":false,"formal":"Coming up with different, and sometimes unique, solutions to problems.","formalEs":"Idear soluciones diferentes, y a veces únicas, a los problemas."},{"term":"Input","termEs":"Entrada","def":"The number you put in to start.","defEs":"El número que pones para empezar.","example":"Input 3 gives output 7","img":"/assets/vocab-images/table-of-values.svg","imgAlt":"Illustration of Input: The number you put in to start.","cs":false,"formal":"The independent value you put in; it fills the first column of a table.","formalEs":"El valor independiente que introduces; llena la primera columna de una tabla.","exampleEs":"Entrada 3 da salida 7","exampleFormal":"Minutes jogged"},{"term":"Integers and Absolute Value","termEs":"Enteros y valor absoluto","def":"Whole numbers and their opposites, and how far each is from zero.","defEs":"Números enteros y sus opuestos, y qué tan lejos está cada uno del cero.","example":"|−6| = 6 because −6 is 6 units from zero.","img":"/assets/vocab-images/concept-integers-and-absolute-value.svg","imgAlt":"Illustration of Integers and Absolute Value: Whole numbers and their opposites, and how far each is from zero.","cs":false,"formal":"Integers are whole numbers and their opposites; absolute value is their distance from zero.","formalEs":"Los enteros son números enteros y sus opuestos; el valor absoluto es su distancia desde cero."},{"term":"Interpret","termEs":"Interpretar","def":"Say what a point on a graph means.","defEs":"Decir con palabras qué significa un punto en una gráfica.","example":"(4, 36) means 4 boxes hold 36 crayons.","img":"/assets/vocab-images/ordered-pair.svg","imgAlt":"Illustration of Interpret: Say what a point on a graph means.","cs":false,"formal":"Say in words what a point on a graph means.","formalEs":"Decir con palabras lo que significa un punto en una gráfica."},{"term":"Interval","termEs":"Intervalo","def":"A group of numbers between two values.","defEs":"Un grupo de números entre dos valores.","example":"Groups 0–4, 5–9, 10–14","img":"/assets/vocab-images/histogram.svg","imgAlt":"Illustration of Interval: A group of numbers between two values.","cs":false,"formal":"A range of numbers used to group data.","formalEs":"Un rango de números para agrupar datos.","exampleEs":"Grupos 0–4, 5–9, 10–14","exampleFormal":"0-9, 10-19, 20-29 are intervals of width 10 — each covers 10 values"},{"term":"inventory","termEs":"inventario","def":"The items a business has in stock.","defEs":"Los artículos que un negocio tiene guardados.","example":"The kitchen counts 40 lb of flour and 12 dozen eggs on hand.","img":"/assets/vocab-images/inventory.svg","imgAlt":"Illustration of inventory: The items a business has in stock.","cs":false,"formal":"The supply of items a business keeps on hand, tracked by counting.","formalEs":"Las existencias que un negocio tiene disponibles, controladas contándolas."},{"term":"Inverse operation","termEs":"Operación inversa","def":"Two actions that undo each other, like × and ÷.","defEs":"Dos acciones que se deshacen entre sí, como × y ÷.","example":"5 + 3 = 8, then 8 − 3 = 5","img":"/assets/vocab-images/equation.svg","imgAlt":"Illustration of Inverse operation: Two actions that undo each other, like × and ÷.","cs":false,"formal":"The operation that undoes another operation.","formalEs":"La operación que deshace otra operación.","exampleEs":"5 + 3 = 8, luego 8 − 3 = 5","exampleFormal":"Division undoes multiplication."},{"term":"Isolate","termEs":"Despejar","def":"Get the letter alone on one side.","defEs":"Dejar la letra sola en un lado.","example":"x + 3 = 10 → x = 7","img":"/assets/vocab-images/equation.svg","imgAlt":"Illustration of Isolate: Get the letter alone on one side.","cs":false,"formal":"To get the letter by itself on one side.","exampleEs":"x + 3 = 10 → x = 7","exampleFormal":"x + 5 = 12 → subtract 5 from both sides → x = 7 (x is isolated)"},{"term":"justify","termEs":"justificar","def":"Explain WHY your answer makes sense.","defEs":"Explicar POR QUÉ tu respuesta tiene sentido.","example":"“35 cars at $14.30 raises $500.50, which clears the $500 goal.”","img":"/assets/vocab-images/justify.svg","imgAlt":"Illustration of justify: Explain WHY your answer makes sense.","cs":false,"formal":"To explain WHY an answer or recommendation makes sense, using the mathematics.","formalEs":"Explicar POR QUÉ una respuesta o recomendación tiene sentido, usando las matemáticas."},{"term":"Keep, Change, Flip","termEs":"Mantener, cambiar, invertir","def":"Keep the first, change ÷ to ×, flip the second.","defEs":"Deja la primera, cambia ÷ por × y voltea la segunda.","example":"1/2 ÷ 1/4 → 1/2 × 4/1 = 2","img":"/assets/vocab-images/reciprocal.svg","imgAlt":"Illustration of Keep, Change, Flip: Keep the first, change ÷ to ×, flip the second.","cs":false,"formal":"A shortcut for dividing fractions: keep the first number, change ÷ to ×, flip the second. It works because dividing by a fraction gives the same answer as multiplying by its reciprocal.","formalEs":"Un atajo para dividir fracciones: deja el primer número, cambia ÷ por × y voltea el segundo. Funciona porque dividir entre una fracción da lo mismo que multiplicar por su recíproco.","exampleEs":"1/2 ÷ 1/4 → 1/2 × 4/1 = 2","exampleFormal":"6 ÷ 1/3 → Keep 6, Change ÷ to ×, Flip 1/3 to 3/1 → 6 × 3 = 18"},{"term":"Lateral area","termEs":"Área lateral","def":"The area of just the sides, not the bottom.","defEs":"El área solo de los lados, sin el fondo.","example":"For a square pyramid: lateral area = 4 × (½ × base edge × slant height)","img":"/assets/vocab-images/surface-area.svg","imgAlt":"Illustration of Lateral area: The area of just the sides, not the bottom.","cs":false,"formal":"The total area of just the side triangles, not the bottom.","formalEs":"El área total solo de los triángulos laterales, sin el fondo."},{"term":"Lateral face","termEs":"Cara lateral","def":"A side face of a solid, not the top or bottom.","defEs":"Un lado de un sólido, no la parte de arriba ni la de abajo.","example":"On a triangular prism, the 3 rectangles that wrap around the sides are lateral faces","img":"/assets/vocab-images/surface-area.svg","imgAlt":"Illustration of Lateral face: A side face of a solid, not the top or bottom.","cs":false,"formal":"The side faces of a solid, not the top or bottom.","formalEs":"Los lados de un sólido, no la parte de arriba ni la de abajo."},{"term":"Least common multiple (LCM)","termEs":"Mínimo común múltiplo (mcm)","def":"The smallest number both numbers count up to.","defEs":"El número más pequeño al que llegan ambos al contar.","example":"Counting by 4 and 6 first meets at 12","img":"/assets/vocab-images/least-common-multiple.svg","imgAlt":"Illustration of Least common multiple (LCM): The smallest number both numbers count up to.","cs":false,"formal":"The smallest number that is a multiple of two or more numbers. It answers “when will these line up again?”","formalEs":"El número más pequeño que es múltiplo de dos o más números. Responde “¿cuándo volverán a coincidir?”","exampleEs":"Contando de 4 y de 6, primero coinciden en 12","exampleFormal":"6, 12, 18, 24 and 8, 16, 24 → LCM = 24"},{"term":"Length, width, height","termEs":"Largo, ancho, altura","def":"How long, how wide, and how tall a box is.","defEs":"Qué tan largo, ancho y alto es una caja.","example":"A box 5 long, 3 wide, 2 tall","img":"/assets/vocab-images/dimensions.svg","imgAlt":"Illustration of Length, width, height: How long, how wide, and how tall a box is.","cs":false,"exampleEs":"Una caja de 5 de largo, 3 de ancho, 2 de alto","exampleFormal":"V = l × w × h: for a box 5 × 3 × 2, volume = 30 cubic units"},{"term":"Less than 1%","termEs":"Menor que 1%","def":"A percent below 1%. It is a very tiny part.","defEs":"Un porcentaje por debajo de 1 %. Es una parte muy pequeña.","example":"0.5% is half of 1%","img":"/assets/vocab-images/percent.svg","imgAlt":"Illustration of Less than 1%: A percent below 1%. It is a very tiny part.","cs":false,"formal":"A percent smaller than 1%, a very tiny part.","formalEs":"Un porcentaje menor que 1%, una parte muy pequeña.","exampleEs":"0.5 % es la mitad de 1 %","exampleFormal":"0.5% of 1,000 = only 5 items — a tiny sliver"},{"term":"line of symmetry","termEs":"eje de simetría","def":"A line that cuts a shape into two matching halves.","defEs":"Una línea que divide una figura en dos mitades iguales que se reflejan.","example":"The line straight down the butterfly's body.","img":"/assets/vocab-images/symmetric.svg","imgAlt":"Illustration of line of symmetry: A line that cuts a shape into two matching halves.","cs":false,"formal":"The line you can draw through a figure so each side is a reflection of the other.","formalEs":"La línea que puedes trazar por una figura de modo que cada lado sea el reflejo del otro."},{"term":"Linear pattern","termEs":"Patrón lineal","def":"Points that line up in a straight line.","defEs":"Puntos que forman una línea recta en una cuadrícula.","example":"(1,2), (2,4), (3,6) all line up","img":"/assets/vocab-images/pattern.svg","imgAlt":"Illustration of Linear pattern: Points that line up in a straight line.","cs":false,"formal":"Points that make a straight line on a grid."},{"term":"Magnitude","termEs":"Magnitud","def":"The size of a number: its distance from zero.","defEs":"El tamaño de un número: su distancia al cero.","example":"|−50| has magnitude 50.","img":"/assets/vocab-images/absolute-value.svg","imgAlt":"Illustration of Magnitude: The size of a number: its distance from zero.","cs":false,"formal":"The size of a number; its distance from zero.","formalEs":"El tamaño de un número; su distancia de cero."},{"term":"make sense of a problem","termEs":"comprender un problema","def":"Figure out what is asked and what you know.","defEs":"Descubrir qué se pregunta y qué sabes.","example":"KNOW: 16 wheels, 6 times as many. DON'T KNOW: how many bikes.","img":"/assets/vocab-images/make-sense-of-a-problem.svg","imgAlt":"Illustration of make sense of a problem: Figure out what is asked and what you know.","cs":false,"formal":"To figure out what a problem is asking — what you know, and what you don't know yet.","formalEs":"Descubrir qué pide un problema: qué sabes y qué no sabes todavía."},{"term":"Markup","termEs":"Recargo (margen)","def":"Money a store adds to its cost to set a price.","defEs":"Dinero que una tienda suma a su costo para fijar el precio.","example":"Cost $20 plus $5 markup is $25","img":"/assets/vocab-images/markup.svg","imgAlt":"Illustration of Markup: Money a store adds to its cost to set a price.","cs":false,"formal":"Money added to the cost to set the selling price.","formalEs":"Dinero que se suma al costo para fijar el precio de venta.","exampleEs":"Costo $20 más $5 de recargo son $25","exampleFormal":"A $30 item with 10% markup sells for $33"},{"term":"math biography","termEs":"biografía matemática","def":"The story of you and math.","defEs":"La historia de ti y las matemáticas.","example":"September: “I am not a math person.” June: “I can explain why it works.”","img":"/assets/vocab-images/math-biography.svg","imgAlt":"Illustration of math biography: The story of you and math.","cs":false,"formal":"The story of your relationship with math — and how it has changed over time.","formalEs":"La historia de tu relación con las matemáticas y cómo ha cambiado con el tiempo."},{"term":"math story","termEs":"historia matemática","def":"What you have done, felt, and learned about math.","defEs":"Lo que has hecho, sentido y aprendido sobre las matemáticas.","example":"“In 3rd grade I hated fractions; this year I can explain them.”","img":"/assets/vocab-images/math-story.svg","imgAlt":"Illustration of math story: What you have done, felt, and learned about math.","cs":false,"formal":"Your own history with mathematics — what you have done, felt, and learned so far.","formalEs":"Tu propia historia con las matemáticas: lo que has hecho, sentido y aprendido."},{"term":"Mean, Median, and Mode","termEs":"Media, mediana y moda","def":"Three ways to find the center of the data.","defEs":"Tres maneras de hallar el centro de los datos.","example":"For 2, 3, 3, 8: mean = 4, median = 3, mode = 3.","img":"/assets/vocab-images/concept-mean-median-and-mode.svg","imgAlt":"Illustration of Mean, Median, and Mode: Three ways to find the center of the data.","cs":false,"formal":"Measures that describe a data set's center: average, middle value, and most frequent value.","formalEs":"Medidas que describen el centro de un conjunto de datos: promedio, valor central y valor más frecuente."},{"term":"Measure of center","termEs":"Medida de tendencia central","def":"One number that tells what is typical.","defEs":"Un número que dice qué es típico.","example":"The median is one measure of center.","img":"/assets/vocab-images/mean.svg","imgAlt":"Illustration of Measure of center: One number that tells what is typical.","cs":false,"formal":"One number that describes a typical value in a data set.","formalEs":"Un número que describe un valor típico de un conjunto de datos."},{"term":"Measure of variation","termEs":"Medida de variación","def":"One number that tells how far apart the data is.","defEs":"Un número que dice qué tan separados están los datos.","example":"One number stands in for the spread of all 20 scores","img":"/assets/vocab-images/spread.svg","imgAlt":"Illustration of Measure of variation: One number that tells how far apart the data is.","cs":false,"formal":"A single number that describes the spread of a whole data set. The range and the IQR are both measures of variation.","formalEs":"Un solo número que describe la dispersión de todo un conjunto de datos. El rango y el RIC son medidas de variación."},{"term":"Measurement system","termEs":"Sistema de medidas","def":"A set of units that go together.","defEs":"Un conjunto de unidades que van juntas.","example":"Customary: 12 in = 1 ft · Metric: 1,000 mL = 1 L","img":"/assets/vocab-images/concept-measurement-system.svg","imgAlt":"Illustration of Measurement system: A set of units that go together.","cs":false,"formal":"A family of units that go together — customary units like inches and feet, or metric units like milliliters and liters.","formalEs":"Una familia de unidades que van juntas: unidades usuales como pulgadas y pies, o métricas como mililitros y litros."},{"term":"Metric system","termEs":"Sistema métrico","def":"Units like meters, grams, and liters, used in most of the world.","defEs":"Unidades como metros, gramos y litros, usadas en casi todo el mundo.","example":"cm · m · km · g · kg · mL · L","img":"/assets/vocab-images/concept-metric-system.svg","imgAlt":"Illustration of Metric system: Units like meters, grams, and liters, used in most of the world.","cs":false,"formal":"The measurement system used in most of the world, built on tens: centimeters, meters, kilometers, grams, kilograms, liters.","formalEs":"El sistema de medidas que se usa en casi todo el mundo, basado en decenas: centímetros, metros, kilómetros, gramos, kilogramos y litros."},{"term":"Metric units","termEs":"Unidades métricas","def":"Units like meters, liters, and grams.","defEs":"Unidades como metros, litros y gramos.","example":"1 meter = 100 centimeters, 1 kilogram = 1,000 grams","img":"/assets/vocab-images/measurement.svg","imgAlt":"Illustration of Metric units: Units like meters, liters, and grams.","cs":false,"formal":"A way of measuring by 10s, like meters, liters, and grams.","formalEs":"Una forma de medir de 10 en 10, como metros, litros y gramos."},{"term":"Middle half","termEs":"Mitad central","def":"The box part of a box plot. It holds half the data.","defEs":"La caja de un diagrama de caja. Tiene la mitad de los datos.","example":"The box holds half of the data.","img":"/assets/vocab-images/interquartile-range.svg","imgAlt":"Illustration of Middle half: The box part of a box plot. It holds half the data.","cs":false,"formal":"The values from the first quartile to the third quartile, which the box covers.","formalEs":"Los valores desde el primer cuartil hasta el tercer cuartil, que la caja cubre."},{"term":"mirror image","termEs":"imagen reflejada","def":"A flip of a shape across a line.","defEs":"Una figura volteada al otro lado de una línea.","example":"Fold the layer down the middle: each leaf lands on its partner.","img":"/assets/vocab-images/reflection.svg","imgAlt":"Illustration of mirror image: A flip of a shape across a line.","cs":false,"formal":"A copy of a figure flipped across a line, so the two halves face each other.","formalEs":"Una copia de una figura volteada al otro lado de una línea, de modo que las dos mitades se miran entre sí."},{"term":"Mode","termEs":"Moda","def":"The number that shows up most.","defEs":"El número que aparece más veces.","example":"2, 3, 3, 5: the mode is 3","img":"/assets/vocab-images/mode.svg","imgAlt":"Illustration of Mode: The number that shows up most.","cs":false,"formal":"The number that shows up most often.","exampleEs":"2, 3, 3, 5: la moda es 3","exampleFormal":"Data: 2, 3, 3, 5, 7 → 3 appears twice (most often), so mode = 3"},{"term":"Multi-step problem","termEs":"Problema de varios pasos","def":"A problem that takes more than one step.","defEs":"Un problema que lleva más de un paso.","example":"Convert the unit, then multiply.","img":"/assets/vocab-images/strategy.svg","imgAlt":"Illustration of Multi-step problem: A problem that takes more than one step.","cs":false,"formal":"A problem that needs two or more operations done in order.","formalEs":"Un problema que necesita dos o más operaciones hechas en orden."},{"term":"Multiplication Property of Equality","termEs":"Propiedad de multiplicación de la igualdad","def":"Multiply both sides by the same number. They stay equal.","defEs":"Multiplica ambos lados por el mismo número. Siguen siendo iguales.","example":"x ÷ 2 = 5 → x = 10","img":"/assets/vocab-images/equation.svg","imgAlt":"Illustration of Multiplication Property of Equality: Multiply both sides by the same number. They stay equal.","cs":false,"formal":"Multiplying both sides by the same number keeps an equation balanced.","formalEs":"Multiplicar ambos lados por el mismo número mantiene una ecuación equilibrada.","exampleEs":"x ÷ 2 = 5 → x = 10","exampleFormal":"Both sides × 4"},{"term":"Multiplicative inverse","termEs":"Inverso multiplicativo","def":"Two numbers that multiply to make 1.","defEs":"Dos números que al multiplicarse dan 1.","example":"2/3 × 3/2 = 1","img":"/assets/vocab-images/reciprocal.svg","imgAlt":"Illustration of Multiplicative inverse: Two numbers that multiply to make 1.","cs":false,"formal":"Two numbers whose product is 1; each is the reciprocal of the other.","formalEs":"Dos números cuyo producto es 1; cada uno es el recíproco del otro.","exampleEs":"2/3 × 3/2 = 1","exampleFormal":"4 and 1/4 · 2/3 and 3/2"},{"term":"Multiply Decimals","termEs":"Multiplicar decimales","def":"Multiply as whole numbers. Then count the digits after the dot.","defEs":"Multiplica como enteros. Luego cuenta los dígitos después del punto.","example":"0.3 × 0.2: 3 × 2 = 6, so 0.06","img":"/assets/vocab-images/concept-multiply-decimals.svg","imgAlt":"Illustration of Multiply Decimals: Multiply as whole numbers. Then count the digits after the dot.","cs":false,"formal":"Find the product of decimals, then use place value to place the decimal point.","formalEs":"Hallar el producto de decimales y luego usar el valor posicional para colocar el punto decimal.","exampleEs":"0.3 × 0.2: 3 × 2 = 6, así 0.06","exampleFormal":"3.4 × 2.6 = 8.84"},{"term":"Negative","termEs":"Negativo","def":"A number less than zero.","defEs":"Un número menor que cero.","example":"-3 means 3 below zero, like 3 floors underground","img":"/assets/vocab-images/negative.svg","imgAlt":"Illustration of Negative: A number less than zero.","cs":false,"formal":"A number smaller than zero, to the left of zero on a number line.","formalEs":"Un número menor que cero, a la izquierda del cero en la recta numérica."},{"term":"Negative coordinate","termEs":"Coordenada negativa","def":"A number less than zero. It means left or below the center.","defEs":"Un número menor que cero. Significa a la izquierda o abajo del centro.","example":"(-3, 2) means 3 left and 2 up from the origin","img":"/assets/vocab-images/negative.svg","imgAlt":"Illustration of Negative coordinate: A number less than zero. It means left or below the center.","cs":false,"formal":"A coordinate less than zero. It means left or below the center point.","formalEs":"Una coordenada menor que cero. Significa a la izquierda o debajo del centro."},{"term":"Negative integer","termEs":"Entero negativo","def":"A whole number less than zero, like −5.","defEs":"Un número entero menor que cero, como −5.","example":"-4 is 4 units to the LEFT of zero on the number line","img":"/assets/vocab-images/negative.svg","imgAlt":"Illustration of Negative integer: A whole number less than zero, like −5.","cs":false,"formal":"A whole number smaller than zero, like -5.","formalEs":"Un número entero menor que cero, como -5."},{"term":"Negative number","termEs":"Número negativo","def":"A number less than 0, written with a − sign.","defEs":"Un número menor que 0, escrito con signo −.","example":"−5 is left of 0","img":"/assets/vocab-images/negative.svg","imgAlt":"Illustration of Negative number: A number less than 0, written with a − sign.","cs":false,"formal":"A number less than 0, written with a − sign. On a number line it sits to the left of 0.","formalEs":"Un número menor que 0, escrito con un signo −. En la recta numérica queda a la izquierda del 0.","exampleEs":"−5 está a la izquierda del 0","exampleFormal":"-86 meters means 86 meters BELOW sea level"},{"term":"No more than","termEs":"No más de","def":"This much or less. It is the same as ≤.","defEs":"Esta cantidad o menos. Es lo mismo que ≤.","example":"No more than 5 means 5 or less","img":"/assets/vocab-images/inequality.svg","imgAlt":"Illustration of No more than: This much or less. It is the same as ≤.","cs":false,"formal":"A phrase meaning less than or equal to (≤).","formalEs":"Una frase que significa menor o igual que (≤).","exampleEs":"No más de 5 significa 5 o menos","exampleFormal":"“No more than 8 people” means people ≤ 8."},{"term":"Non-statistical Question","termEs":"Pregunta no estadística","def":"A question with only one answer.","defEs":"Una pregunta con una sola respuesta.","example":"“How tall am I?” → one answer: 60 in. Everyone who measures gets the same number.","img":"/assets/vocab-images/concept-non-statistical-question.svg","imgAlt":"Illustration of Non-statistical Question: A question with only one answer.","cs":false,"formal":"A question that does not anticipate variability in the data used to answer it. It may ask for one fact or measurement.","formalEs":"Una pregunta que no anticipa variabilidad en los datos usados para responderla. Puede pedir un solo dato o una medición."},{"term":"Number line","termEs":"Recta numérica","def":"A line with numbers in order, left to right.","defEs":"Una recta con los números en orden, de izquierda a derecha.","example":"-3, -2, -1, 0, 1, 2, 3 marked in order from left to right","img":"/assets/vocab-images/number-line.svg","imgAlt":"Illustration of Number line: A line with numbers in order, left to right.","cs":false,"formal":"A straight line where numbers are placed in order. It extends to the left of 0 to show values less than 0.","formalEs":"Una recta donde los números se colocan en orden. Se extiende a la izquierda del 0 para mostrar valores menores que 0."},{"term":"Numerical expression","termEs":"Expresión numérica","def":"A math phrase with numbers and signs, but no letters.","defEs":"Una frase matemática con números y signos, pero sin letras.","example":"3 + 4 × 2","img":"/assets/vocab-images/expression.svg","imgAlt":"Illustration of Numerical expression: A math phrase with numbers and signs, but no letters.","cs":false,"formal":"A math phrase built from numbers and operations, with no equal sign and no variable.","formalEs":"Una frase matemática hecha de números y operaciones, sin signo de igual y sin variable.","exampleEs":"3 + 4 × 2","exampleFormal":"4 × 20 is an expression; 4 × 20 = 80 is an equation"},{"term":"One-step equation","termEs":"Ecuación de un paso","def":"An equation you solve with just one step.","defEs":"Una ecuación que resuelves con un solo paso.","example":"x + 4 = 9 → x = 5","img":"/assets/vocab-images/equation.svg","imgAlt":"Illustration of One-step equation: An equation you solve with just one step.","cs":false,"formal":"An equation you can solve in a single step using one inverse operation.","formalEs":"Una ecuación que puedes resolver en un solo paso usando una operación inversa.","exampleEs":"x + 4 = 9 → x = 5","exampleFormal":"x + 4 = 9 is solved in one step: subtract 4 from both sides, so x = 5."},{"term":"Open circle","termEs":"Círculo abierto","def":"An empty circle. The number is left out.","defEs":"Un círculo vacío. El número NO está incluido.","example":"x > 5: open circle at 5 means 5 itself is NOT a solution, but 5.1, 6, 7, ... are","img":"/assets/vocab-images/open-circle.svg","imgAlt":"Illustration of Open circle: An empty circle. The number is left out.","cs":false,"formal":"An empty circle showing a number is NOT included.","formalEs":"Un círculo vacío que muestra que un número NO está incluido."},{"term":"Opposite of the opposite","termEs":"Opuesto del opuesto","def":"Switching the sign twice gives the first number.","defEs":"Cambiar el signo dos veces da el primer número.","example":"−(−7) = 7","img":"/assets/vocab-images/opposite.svg","imgAlt":"Illustration of Opposite of the opposite: Switching the sign twice gives the first number.","cs":false,"formal":"Taking the opposite twice brings you back to the first number.","formalEs":"Tomar el opuesto dos veces te devuelve al primer número.","exampleEs":"−(−7) = 7","exampleFormal":"−(−6) = 6"},{"term":"Order","termEs":"Ordenar","def":"Put numbers from smallest to biggest, or the reverse.","defEs":"Poner números del menor al mayor, o al revés.","example":"9, 2, 5 → 2, 5, 9","img":"/assets/vocab-images/number-line.svg","imgAlt":"Illustration of Order: Put numbers from smallest to biggest, or the reverse.","cs":false,"formal":"To arrange numbers by size, from least to greatest or greatest to least.","formalEs":"Acomodar números por tamaño, de menor a mayor o de mayor a menor.","exampleEs":"9, 2, 5 → 2, 5, 9","exampleFormal":"Least to greatest: -5, -2, 0, 3, 7 (left to right on the number line)"},{"term":"Order of operations","termEs":"Orden de las operaciones","def":"Do ( ) first, powers next, then × and ÷, then + and −, left to right.","defEs":"Primero ( ), luego potencias, luego × y ÷, y al final + y −, de izquierda a derecha.","example":"2 + 3 × 4 = 14, not 20","img":"/assets/vocab-images/operation.svg","imgAlt":"Illustration of Order of operations: Do ( ) first, powers next, then × and ÷, then + and −, left to right.","cs":false,"formal":"The agreed order for evaluating: grouping symbols, then exponents, then multiply and divide left to right, then add and subtract left to right.","formalEs":"El orden acordado para evaluar: signos de agrupación, luego exponentes, luego multiplicar y dividir de izquierda a derecha, y por último sumar y restar de izquierda a derecha.","exampleEs":"2 + 3 × 4 = 14, no 20","exampleFormal":"3 + 4 × 2² → 3 + 4 × 4 → 3 + 16 = 19"},{"term":"Ordered Pairs in All Four Quadrants","termEs":"Pares ordenados en los cuatro cuadrantes","def":"Plot (x, y) points in all four parts of the grid.","defEs":"Ubicar puntos (x, y) en cualquiera de las cuatro partes de la cuadrícula.","example":"(−3, 4) is in Quadrant II.","img":"/assets/vocab-images/concept-ordered-pairs-in-all-four-quadrants.svg","imgAlt":"Illustration of Ordered Pairs in All Four Quadrants: Plot (x, y) points in all four parts of the grid.","cs":false,"formal":"Points written as (x, y) whose positive or negative coordinates place them in one of four quadrants.","formalEs":"Puntos escritos como (x, y) cuyas coordenadas positivas o negativas los ubican en uno de cuatro cuadrantes."},{"term":"organize","termEs":"organizar","def":"Put facts in a table so patterns are easy to see.","defEs":"Poner los datos en una tabla para ver los patrones con facilidad.","example":"Discs 1, 2, 3 in one column and steps 1, 3, 7 in the next.","img":"/assets/vocab-images/organize.svg","imgAlt":"Illustration of organize: Put facts in a table so patterns are easy to see.","cs":false,"formal":"To arrange information — often in a table — so patterns become easier to see.","formalEs":"Ordenar la información, muchas veces en una tabla, para que los patrones sean más fáciles de ver."},{"term":"Output","termEs":"Salida","def":"The number that comes out.","defEs":"El número que sale.","example":"Input 3 gives output 7","img":"/assets/vocab-images/table-of-values.svg","imgAlt":"Illustration of Output: The number that comes out.","cs":false,"formal":"The dependent value that comes out; it fills the second column of a table.","formalEs":"El valor dependiente que resulta; llena la segunda columna de una tabla.","exampleEs":"Entrada 3 da salida 7","exampleFormal":"Calories burned"},{"term":"Parallel","termEs":"Paralelas","def":"Lines that stay the same distance apart and never meet.","defEs":"Líneas que siempre están a la misma distancia y nunca se cruzan.","example":"The top and bottom of a parallelogram never get closer together — matching arrowheads (›) mark one parallel pair, double arrowheads (››) mark the other.","img":"/assets/vocab-images/parallel.svg","imgAlt":"Illustration of Parallel: Lines that stay the same distance apart and never meet.","cs":false,"formal":"Two lines or sides that stay the same distance apart and never meet.","formalEs":"Dos líneas o lados que se mantienen a la misma distancia y nunca se cruzan."},{"term":"Part-to-part","termEs":"Parte a parte","def":"Compares one piece of a group with another piece.","defEs":"Compara una parte de un grupo con otra parte.","example":"3 boys to 2 girls","img":"/assets/vocab-images/part-to-part.svg","imgAlt":"Illustration of Part-to-part: Compares one piece of a group with another piece.","cs":false,"formal":"A ratio comparing one part of a group to another part.","formalEs":"Una razón que compara una parte de un grupo con otra parte.","exampleEs":"3 niños a 2 niñas","exampleFormal":"3 teal counters to 5 amber counters → 3:5"},{"term":"Part-to-whole","termEs":"Parte a todo","def":"Compares one piece with the whole group.","defEs":"Compara una parte con todo el grupo.","example":"3 boys to 5 kids in all","img":"/assets/vocab-images/part-to-whole.svg","imgAlt":"Illustration of Part-to-whole: Compares one piece with the whole group.","cs":false,"formal":"A ratio comparing one part to the whole group.","formalEs":"Una razón que compara una parte con todo el grupo.","exampleEs":"3 niños de 5 en total","exampleFormal":"3 teal counters out of 8 counters in all → 3:8"},{"term":"pattern rule","termEs":"regla del patrón","def":"The rule that tells how to get the next number.","defEs":"La regla que dice cómo obtener el siguiente número.","example":"Add 3 each time: 4, 7, 10","img":"/assets/vocab-images/pattern-rule.svg","imgAlt":"Illustration of pattern rule: The rule that tells how to get the next number.","cs":false,"formal":"The instruction that tells how to get from one number in a pattern to the next.","formalEs":"La instrucción que dice cómo pasar de un número del patrón al siguiente.","exampleEs":"Sumar 3 cada vez: 4, 7, 10","exampleFormal":"2, 4, 6, 8 … the rule is “+ 2 every time”."},{"term":"pattern unit","termEs":"unidad del patrón","def":"The smallest part that repeats.","defEs":"La parte más pequeña que se repite.","example":"circle · square · triangle — the chunk that starts over.","img":"/assets/vocab-images/pattern.svg","imgAlt":"Illustration of pattern unit: The smallest part that repeats.","cs":false,"formal":"The smallest chunk of a pattern that repeats.","formalEs":"La parte más pequeña de un patrón que se repite."},{"term":"Peak","termEs":"Pico","def":"The tallest bar or stack of dots.","defEs":"La barra o pila de puntos más alta.","example":"The tallest bar of the histogram is the peak.","img":"/assets/vocab-images/mode.svg","imgAlt":"Illustration of Peak: The tallest bar or stack of dots.","cs":false,"formal":"The tallest bar or stack in a data display.","formalEs":"La barra o pila más alta en una representación de datos."},{"term":"Per hundred","termEs":"Por cada cien","def":"For every group of 100. That is what percent means.","defEs":"Por cada grupo de 100. Eso significa porcentaje.","example":"23% = 23/100","img":"/assets/vocab-images/percent.svg","imgAlt":"Illustration of Per hundred: For every group of 100. That is what percent means.","cs":false,"formal":"The meaning hidden inside the word percent: for every group of 100. It is why every percent can be written as a fraction over 100.","formalEs":"El significado dentro de la palabra porcentaje: por cada grupo de 100. Por eso todo porcentaje se puede escribir como fracción sobre 100."},{"term":"Per Unit","termEs":"Por unidad","def":"For each single item.","defEs":"Por cada artículo.","example":"$2 for each 1 pen","img":"/assets/vocab-images/unit-rate.svg","imgAlt":"Illustration of Per Unit: For each single item.","cs":false,"exampleEs":"$2 por cada 1 bolígrafo","exampleFormal":"$0.50 per token means each token costs $0.50"},{"term":"Percent of a Number","termEs":"Porcentaje de un número","def":"The piece of a number that the percent names.","defEs":"La parte de un número que indica el porcentaje.","example":"25% of 80 = 0.25 × 80 = 20","img":"/assets/vocab-images/percent-of-a-number.svg","imgAlt":"Illustration of Percent of a Number: The piece of a number that the percent names.","cs":false,"formal":"A part of a number found by multiplying the number by the percent written as a decimal.","formalEs":"Una parte de un número que se halla multiplicando el número por el porcentaje escrito como decimal.","exampleEs":"25 % de 80 = 0.25 × 80 = 20","exampleFormal":"25% of 80 = 0.25 × 80 = 20"},{"term":"Percent Problem Solving","termEs":"Resolución de problemas con porcentajes","def":"Use a percent to find a part, a whole, or a change.","defEs":"Usar un porcentaje para hallar una parte, un total o un cambio.","example":"Sale price = original price − discount.","img":"/assets/vocab-images/concept-percent-problem-solving.svg","imgAlt":"Illustration of Percent Problem Solving: Use a percent to find a part, a whole, or a change.","cs":false,"formal":"Use a percent to find a part, a whole, or a percent change in a real situation.","formalEs":"Usar un porcentaje para hallar una parte, un total o un cambio porcentual en una situación real."},{"term":"Percents Greater Than 100% and Less Than 1%","termEs":"Porcentajes mayores que 100% y menores que 1%","def":"A percent can be more than the whole or very tiny.","defEs":"Un porcentaje puede ser más que el total o muy pequeño.","example":"150% = 1.5 and 0.5% = 0.005","img":"/assets/vocab-images/concept-percents-greater-than-100-and-less-than-1.svg","imgAlt":"Illustration of Percents Greater Than 100% and Less Than 1%: A percent can be more than the whole or very tiny.","cs":false,"formal":"Percents can describe amounts greater than one whole or smaller than one hundredth of a whole.","formalEs":"Los porcentajes pueden describir cantidades mayores que un entero o menores que una centésima de un entero."},{"term":"Perpendicular","termEs":"Perpendicular","def":"Lines that meet at a square corner (90°).","defEs":"Líneas que se cruzan en una esquina cuadrada (90°).","example":"The dashed height meets the base at a square corner — the small 90° box is what makes it perpendicular, not slanted.","img":"/assets/vocab-images/perpendicular.svg","imgAlt":"Illustration of Perpendicular: Lines that meet at a square corner (90°).","cs":false,"formal":"Two lines that meet to make a square corner (90 degrees).","formalEs":"Dos líneas que se cruzan formando una esquina cuadrada (90 grados)."},{"term":"persevere","termEs":"perseverar","def":"Keep going when a problem is hard.","defEs":"Seguir intentando cuando un problema es difícil.","example":"Stuck on the tram problem → try a tape diagram instead → keep going.","img":"/assets/vocab-images/persevere.svg","imgAlt":"Illustration of persevere: Keep going when a problem is hard.","cs":false,"formal":"To keep working on a problem, checking your progress and adjusting your plan when you get stuck.","formalEs":"Seguir trabajando en un problema, revisando tu progreso y ajustando tu plan cuando te atascas."},{"term":"portion","termEs":"porción","def":"The amount of food for one person.","defEs":"La cantidad de comida para una persona.","example":"Each bowl of soup uses 2 cups of broth — one person's serving.","img":"/assets/vocab-images/part-to-whole.svg","imgAlt":"Illustration of portion: The amount of food for one person.","cs":false,"formal":"The measured amount of food served to one person.","formalEs":"La cantidad medida de comida que se sirve a una persona."},{"term":"Positive","termEs":"Positivo","def":"A number more than zero.","defEs":"Un número mayor que cero.","example":"+5 means 5 above zero, like 5 floors above ground level","img":"/assets/vocab-images/positive.svg","imgAlt":"Illustration of Positive: A number more than zero.","cs":false,"formal":"A number bigger than zero, to the right of zero on a number line.","formalEs":"Un número mayor que cero, a la derecha del cero en la recta numérica."},{"term":"Positive number","termEs":"Número positivo","def":"A number greater than 0, to the right of 0.","defEs":"Un número mayor que 0, a la derecha del 0.","example":"9°C is 9 degrees ABOVE zero","img":"/assets/vocab-images/positive.svg","imgAlt":"Illustration of Positive number: A number greater than 0, to the right of 0.","cs":false,"formal":"A number greater than 0. On a number line it sits to the right of 0.","formalEs":"Un número mayor que 0. En la recta numérica queda a la derecha del 0."},{"term":"Power of ten","termEs":"Potencia de diez","def":"Ten, one hundred, one thousand, and so on.","defEs":"Diez, cien, mil, y así sucesivamente.","example":"Multiplying by 10 slides every digit one place.","img":"/assets/vocab-images/place-value.svg","imgAlt":"Illustration of Power of ten: Ten, one hundred, one thousand, and so on.","cs":false},{"term":"Powers and Exponents","termEs":"Potencias y exponentes","def":"Short ways to write the same number times itself.","defEs":"Formas cortas de escribir un número multiplicado por sí mismo.","example":"5² = 5 × 5 = 25","img":"/assets/vocab-images/concept-powers-and-exponents.svg","imgAlt":"Illustration of Powers and Exponents: Short ways to write the same number times itself.","cs":false,"formal":"A power uses a base and an exponent to show repeated multiplication.","formalEs":"Una potencia usa una base y un exponente para mostrar multiplicación repetida.","exampleEs":"5² = 5 × 5 = 25","exampleFormal":"2⁴ = 2 × 2 × 2 × 2 = 16"},{"term":"predictability","termEs":"previsibilidad","def":"Knowing what comes next because of a rule.","defEs":"Saber qué sigue porque hay una regla.","example":"Shape 25 must be a circle — the unit repeats every 3.","img":"/assets/vocab-images/pattern.svg","imgAlt":"Illustration of predictability: Knowing what comes next because of a rule.","cs":false,"formal":"Being able to know what comes next because the design follows a rule.","formalEs":"Poder saber qué viene después porque el diseño sigue una regla."},{"term":"Prime number","termEs":"Número primo","def":"A number over 1 that only splits by 1 and itself.","defEs":"Un número mayor que 1 que solo se divide entre 1 y sí mismo.","example":"7 is prime: only 1 and 7 divide it","img":"/assets/vocab-images/prime-number.svg","imgAlt":"Illustration of Prime number: A number over 1 that only splits by 1 and itself.","cs":false,"formal":"A number bigger than 1 that you can only divide by 1 and itself.","formalEs":"Un número mayor que 1 que solo se puede dividir entre 1 y sí mismo.","exampleEs":"7 es primo: solo 1 y 7 lo dividen","exampleFormal":"7 has only two factors: 1 × 7. So 7 is prime."},{"term":"Problem solving","termEs":"Resolución de problemas","def":"Use ratios and rates to find a missing amount.","defEs":"Usar razones y tasas para hallar una cantidad que falta.","example":"Set up → Plan → Solve → Check","img":"/assets/vocab-images/number.svg","imgAlt":"Illustration of Problem solving: Use ratios and rates to find a missing amount.","cs":false,"formal":"Using ratios and rates to find a missing amount.","formalEs":"Usar razones y tasas para encontrar una cantidad que falta."},{"term":"profession","termEs":"profesión","def":"A job someone is trained to do.","defEs":"Un trabajo para el que alguien se preparó.","example":"A chef prices a menu; a nurse measures a dose; a carpenter cuts to length.","img":"/assets/vocab-images/profession.svg","imgAlt":"Illustration of profession: A job someone is trained to do.","cs":false,"formal":"A job someone is trained to do, like chef, nurse, or carpenter.","formalEs":"Un trabajo para el que alguien se ha preparado, como chef, enfermero o carpintero."},{"term":"Properties of Operations","termEs":"Propiedades de las operaciones","def":"Rules that let you change the order or grouping.","defEs":"Reglas que permiten cambiar el orden o la agrupación.","example":"3 + 5 = 5 + 3 (commutative property).","img":"/assets/vocab-images/concept-properties-of-operations.svg","imgAlt":"Illustration of Properties of Operations: Rules that let you change the order or grouping.","cs":false,"formal":"Rules that let you reorder or regroup numbers without changing an expression's value.","formalEs":"Reglas que permiten reordenar o reagrupar números sin cambiar el valor de una expresión."},{"term":"Property","termEs":"Propiedad","def":"A rule that is always true in math.","defEs":"Una regla que siempre es cierta en matemáticas.","example":"Commutative works for + and ×, but NOT for − or ÷ (since 5 − 3 = 2 but 3 − 5 = −2)","img":"/assets/vocab-images/operation.svg","imgAlt":"Illustration of Property: A rule that is always true in math.","cs":false,"formalEs":"Una regla que siempre es verdadera en matemáticas."},{"term":"Proportional","termEs":"Proporcional","def":"Two amounts that grow together at the same rate.","defEs":"Dos cantidades que crecen juntas al mismo ritmo.","example":"A straight line from (0,0) through (2,6) and (4,12)","img":"/assets/vocab-images/proportion.svg","imgAlt":"Illustration of Proportional: Two amounts that grow together at the same rate.","cs":false},{"term":"puzzle","termEs":"rompecabezas","def":"A problem to play with. It has rules and a goal.","defEs":"Un problema para jugar, con reglas y una meta.","example":"Tower of Hanoi: three rods, a stack of discs, and two rules.","img":"/assets/vocab-images/puzzle.svg","imgAlt":"Illustration of puzzle: A problem to play with. It has rules and a goal.","cs":false,"formal":"A problem designed to be played with — it has rules, a goal, and room to imagine solutions.","formalEs":"Un problema diseñado para jugarse: tiene reglas, una meta y espacio para imaginar soluciones."},{"term":"quantity","termEs":"cantidad","def":"A number with a meaning, like 540 meters.","defEs":"Un número con un significado, como 540 metros.","example":"540 meters — the number 540 AND what it measures.","img":"/assets/vocab-images/quantity.svg","imgAlt":"Illustration of quantity: A number with a meaning, like 540 meters.","cs":false,"formal":"An amount in a problem — a number with a meaning attached, like 540 meters.","formalEs":"Una cantidad en un problema: un número con un significado, como 540 metros."},{"term":"Range","termEs":"Rango","def":"How far it is from the least to the greatest.","defEs":"Qué tan lejos está del valor menor al mayor.","example":"Values 2 to 9: range is 9 − 2 = 7","img":"/assets/vocab-images/range.svg","imgAlt":"Illustration of Range: How far it is from the least to the greatest.","cs":false,"formal":"The distance from the least value to the greatest value, found by subtracting: greatest − least.","formalEs":"La distancia del valor menor al mayor, que se halla restando: mayor − menor.","exampleEs":"Valores de 2 a 9: el rango es 9 − 2 = 7","exampleFormal":"94 − 68 = 26"},{"term":"Range and Interquartile Range","termEs":"Rango y rango intercuartílico","def":"Two numbers that tell how far apart the data is.","defEs":"Dos números que dicen qué tan separados están los datos.","example":"Range 26 covers 68 to 94; IQR 12.5 covers only 75.5 to 88","img":"/assets/vocab-images/interquartile-range.svg","imgAlt":"Illustration of Range and Interquartile Range: Two numbers that tell how far apart the data is.","cs":false,"formal":"Two numbers that describe spread: the range covers all the data, and the interquartile range covers only the middle half.","formalEs":"Dos números que describen la dispersión: el rango cubre todos los datos y el rango intercuartílico solo la mitad central."},{"term":"Rate of change","termEs":"Tasa de cambio","def":"How much y changes each time x goes up by one.","defEs":"Cuánto cambia y cada vez que x sube en uno.","example":"Up $4 for each hour.","img":"/assets/vocab-images/rate.svg","imgAlt":"Illustration of Rate of change: How much y changes each time x goes up by one.","cs":false,"formalEs":"Cuánto cambia y cada vez que x aumenta en uno."},{"term":"Rates and Unit Rates","termEs":"Tasas y tasas unitarias","def":"A rate compares two amounts. A unit rate is for 1.","defEs":"Una tasa compara dos cantidades. Una tasa unitaria es por 1.","example":"180 miles in 3 hours = 60 miles per 1 hour.","img":"/assets/vocab-images/concept-rates-and-unit-rates.svg","imgAlt":"Illustration of Rates and Unit Rates: A rate compares two amounts. A unit rate is for 1.","cs":false,"formal":"A rate compares different units; a unit rate compares a quantity to 1 unit.","formalEs":"Una tasa compara unidades diferentes; una tasa unitaria compara una cantidad con 1 unidad."},{"term":"Ratio and Rate Problem Solving","termEs":"Resolución de problemas de razones y tasas","def":"Use ratios and rates to find what is missing.","defEs":"Usar razones y tasas para hallar lo que falta.","example":"Cost = number of items × cost per item.","img":"/assets/vocab-images/concept-ratio-and-rate-problem-solving.svg","imgAlt":"Illustration of Ratio and Rate Problem Solving: Use ratios and rates to find what is missing.","cs":false,"formal":"Use ratios and rates to compare quantities and solve real-world problems.","formalEs":"Usar razones y tasas para comparar cantidades y resolver problemas del mundo real."},{"term":"Ratio Reasoning","termEs":"Razonamiento con razones","def":"Use tables, graphs, or equal ratios to solve a problem.","defEs":"Usar tablas, gráficas o razones iguales para resolver un problema.","example":"If 3 notebooks cost $6, then 5 notebooks cost $10.","img":"/assets/vocab-images/concept-ratio-reasoning.svg","imgAlt":"Illustration of Ratio Reasoning: Use tables, graphs, or equal ratios to solve a problem.","cs":false,"formal":"Use equivalent ratios, tables, graphs, or unit rates to solve a problem.","formalEs":"Usar razones equivalentes, tablas, gráficas o tasas unitarias para resolver un problema."},{"term":"Ratio table","termEs":"Tabla de razones","def":"A table that lists equal ratios.","defEs":"Una tabla que muestra razones iguales.","example":"Row 1: 2 to 3. Row 2: 4 to 6","img":"/assets/vocab-images/ratio-table.svg","imgAlt":"Illustration of Ratio table: A table that lists equal ratios.","cs":false,"formal":"A table of equal ratios that shows a pattern.","formalEs":"Una tabla de razones iguales que muestra un patrón.","exampleEs":"Fila 1: 2 a 3. Fila 2: 4 a 6","exampleFormal":"Cups of juice: 2, 4, 6 | Cups of water: 3, 6, 9"},{"term":"Rational number","termEs":"Número racional","def":"A number you can write as a fraction.","defEs":"Un número que puedes escribir como fracción.","example":"0.5 = 1/2 and −3 = −3/1","img":"/assets/vocab-images/concept-rational-number.svg","imgAlt":"Illustration of Rational number: A number you can write as a fraction.","cs":false,"formal":"A number that can be written as a fraction of two integers, with a bottom number that is not zero.","formalEs":"Un número que se puede escribir como una fracción de dos enteros, con un denominador que no sea cero.","exampleEs":"0.5 = 1/2 y −3 = −3/1","exampleFormal":"−1/2, 0 and 5/4 each sit at one exact point."},{"term":"Rational Numbers on the Number Line","termEs":"Números racionales en la recta numérica","def":"Each fraction or decimal has one exact spot on the line.","defEs":"Cada fracción o decimal tiene un lugar exacto en la recta.","example":"−3/2 = −1.5 and 1/2 = 0.5 each sit at one exact point.","img":"/assets/vocab-images/concept-rational-numbers-on-the-number-line.svg","imgAlt":"Illustration of Rational Numbers on the Number Line: Each fraction or decimal has one exact spot on the line.","cs":false,"formal":"Every rational number has one exact spot on the number line. Writing it as a fraction, a decimal, or an integer does not change where it sits.","formalEs":"Cada número racional tiene un lugar exacto en la recta numérica. Escribirlo como fracción, decimal o entero no cambia dónde queda."},{"term":"reasonable","termEs":"razonable","def":"An answer that makes sense.","defEs":"Una respuesta que tiene sentido.","example":"5/6 of 540 must be under 540, so 450 is reasonable and 650 is not.","img":"/assets/vocab-images/reasonable.svg","imgAlt":"Illustration of reasonable: An answer that makes sense.","cs":false,"formal":"A solution that makes sense in the context of the problem.","formalEs":"Una solución que tiene sentido en el contexto del problema."},{"term":"reasonableness","termEs":"sensatez del resultado","def":"Checking that an answer makes sense.","defEs":"Comprobar que una respuesta tiene sentido.","example":"5/6 of 540 should land BELOW 540, so 650 fails the check.","img":"/assets/vocab-images/reasonableness.svg","imgAlt":"Illustration of reasonableness: Checking that an answer makes sense.","cs":false,"formal":"Whether an answer makes sense — checked as you work, with adjustments made when needed.","formalEs":"Si una respuesta tiene sentido — se comprueba mientras trabajas y se ajusta cuando es necesario."},{"term":"Rectangular prism","termEs":"Prisma rectangular","def":"A box shape with six flat sides.","defEs":"Una figura en forma de caja con seis lados planos.","example":"A tissue box, a fish tank, a brick — all rectangular prisms","img":"/assets/vocab-images/rectangular-prism.svg","imgAlt":"Illustration of Rectangular prism: A box shape with six flat sides.","cs":false,"formal":"A solid box shape with six flat rectangle sides.","formalEs":"Una figura sólida en forma de caja con seis lados rectangulares."},{"term":"reflect","termEs":"reflexionar","def":"Look back at what you did and learned.","defEs":"Pensar en lo que hiciste y aprendiste.","example":"Looking back at the tram problem: what worked, what you would change.","img":"/assets/vocab-images/reflection.svg","imgAlt":"Illustration of reflect: Look back at what you did and learned.","cs":false,"formal":"To look back at what you did, felt, and learned, and think about what it means.","formalEs":"Mirar atrás a lo que hiciste, sentiste y aprendiste, y pensar en lo que significa."},{"term":"Reflect Points Across Axes","termEs":"Reflejar puntos sobre los ejes","def":"Flip a point over an axis, keeping the same distance.","defEs":"Voltear un punto sobre un eje, a la misma distancia.","example":"(2, 3) over the x-axis is (2, −3)","img":"/assets/vocab-images/concept-reflect-points-across-axes.svg","imgAlt":"Illustration of Reflect Points Across Axes: Flip a point over an axis, keeping the same distance.","cs":false,"formal":"Flip a point across an axis so it stays the same perpendicular distance from that axis.","formalEs":"Voltear un punto sobre un eje para que quede a la misma distancia perpendicular de ese eje.","exampleEs":"(2, 3) sobre el eje x es (2, −3)","exampleFormal":"Across the x-axis: (3, 2) → (3, −2)."},{"term":"Reflection","termEs":"Reflexión","def":"A flip of a shape across a line.","defEs":"Una figura volteada al otro lado de una línea.","example":"(3, 2) reflected over the x-axis becomes (3, -2) — same x, opposite y","img":"/assets/vocab-images/reflection.svg","imgAlt":"Illustration of Reflection: A flip of a shape across a line.","cs":false,"formal":"A flipped, mirror image across a line.","formalEs":"Una imagen reflejada al otro lado de una línea."},{"term":"Regular Polygon","termEs":"Polígono regular","def":"A closed shape with equal sides and equal angles.","defEs":"Una figura cerrada con lados iguales y ángulos iguales.","example":"A stop sign is a regular octagon — all 8 sides are the same length and all 8 angles are equal","img":"/assets/vocab-images/regular-polygon.svg","imgAlt":"Illustration of Regular Polygon: A closed shape with equal sides and equal angles.","cs":false,"formal":"A closed flat shape made of straight sides, where every side is the same length and every angle is the same size.","formalEs":"Una figura plana cerrada de lados rectos, donde todos los lados miden lo mismo y todos los ángulos son iguales."},{"term":"relationship","termEs":"relación","def":"How two amounts are linked.","defEs":"Cómo están conectadas dos cantidades.","example":"1 hour → 48 km, 2 hours → 96 km: as one grows, so does the other.","img":"/assets/vocab-images/relationship.svg","imgAlt":"Illustration of relationship: How two amounts are linked.","cs":false,"formal":"How two quantities compare or connect to each other.","formalEs":"Cómo se comparan o se conectan dos cantidades entre sí."},{"term":"Repeated multiplication","termEs":"Multiplicación repetida","def":"Times the same number again and again.","defEs":"Multiplicar el mismo número una y otra vez.","example":"2 × 2 × 2 × 2","img":"/assets/vocab-images/exponent.svg","imgAlt":"Illustration of Repeated multiplication: Times the same number again and again.","cs":false,"formal":"Multiplying the same factor again and again.","formalEs":"Multiplicar el mismo factor una y otra vez.","exampleEs":"2 × 2 × 2 × 2","exampleFormal":"9 × 9 × 9 × 9"},{"term":"repetition","termEs":"repetición","def":"The same shape used again and again.","defEs":"La misma figura usada una y otra vez.","example":"The same tile, over and over, all the way along the border.","img":"/assets/vocab-images/pattern.svg","imgAlt":"Illustration of repetition: The same shape used again and again.","cs":false,"formal":"The same object, shape, or form repeated multiple times.","formalEs":"El mismo objeto, figura o forma repetido varias veces."},{"term":"represent","termEs":"representar","def":"Show it with a table, a graph, or an equation.","defEs":"Mostrarlo con una tabla, una gráfica o una ecuación.","example":"The same membership shown as a table, a graph, AND c = 24.95m.","img":"/assets/vocab-images/bar-model.svg","imgAlt":"Illustration of represent: Show it with a table, a graph, or an equation.","cs":false,"formal":"To show a relationship using a tool such as a table, a graph, or an equation.","formalEs":"Mostrar una relación usando una herramienta como una tabla, una gráfica o una ecuación."},{"term":"representation","termEs":"representación","def":"A picture or table that shows a problem.","defEs":"Un dibujo o tabla que muestra un problema.","example":"The same 12 shown three ways: a tape diagram, a table, and 3 × 4.","img":"/assets/vocab-images/representation.svg","imgAlt":"Illustration of representation: A picture or table that shows a problem.","cs":false,"formal":"A picture, diagram, table, or equation that shows the mathematics in a situation.","formalEs":"Un dibujo, diagrama, tabla o ecuación que muestra las matemáticas de una situación."},{"term":"rhythm","termEs":"ritmo","def":"Changing the size, spot, or order of the same shapes.","defEs":"Cambiar el tamaño, el lugar o el orden de las mismas figuras.","example":"The same circles, but sizes and spacing change as your eye travels.","img":"/assets/vocab-images/pattern.svg","imgAlt":"Illustration of rhythm: Changing the size, spot, or order of the same shapes.","cs":false,"formal":"A design element created by varying the placement, size, orientation, or order of the same objects or shapes.","formalEs":"Un elemento de diseño creado al variar la posición, el tamaño, la orientación o el orden de los mismos objetos o figuras."},{"term":"Right trapezoid","termEs":"Trapecio rectángulo","def":"A trapezoid with two square corners.","defEs":"Un trapecio con dos esquinas cuadradas.","example":"One side stands straight up from the base.","img":"/assets/vocab-images/trapezoid.svg","imgAlt":"Illustration of Right trapezoid: A trapezoid with two square corners.","cs":false},{"term":"rotation","termEs":"rotación","def":"One full turn all the way around.","defEs":"Una vuelta completa.","example":"One full turn of the pedal — 360° all the way around.","img":"/assets/vocab-images/rotation.svg","imgAlt":"Illustration of rotation: One full turn all the way around.","cs":false,"formal":"One full turn of a wheel, gear, or pedal all the way around.","formalEs":"Una vuelta completa de una rueda, un engranaje o un pedal."},{"term":"round trip","termEs":"viaje de ida y vuelta","def":"A trip there and back.","defEs":"Ir a un lugar y regresar.","example":"5 miles out plus 5 miles back = 10 miles in all.","img":"/assets/vocab-images/round-trip.svg","imgAlt":"Illustration of round trip: A trip there and back.","cs":false,"formal":"A complete journey from the start, to the destination, and back to the start.","formalEs":"Un recorrido completo desde el inicio hasta el destino y de regreso al inicio."},{"term":"Scale","termEs":"Escalar","def":"Change both parts of a ratio the same way.","defEs":"Cambiar ambas partes de una razón de la misma manera.","example":"2:3 scaled by 2 is 4:6","img":"/assets/vocab-images/scale-factor.svg","imgAlt":"Illustration of Scale: Change both parts of a ratio the same way.","cs":false,"formal":"To multiply or divide both parts of a ratio by the same number.","formalEs":"Multiplicar o dividir ambas partes de una razón por el mismo número.","exampleEs":"2:3 escalado por 2 es 4:6","exampleFormal":"5:8 × 3 → 15:24"},{"term":"Shape of Data Distributions","termEs":"Forma de las distribuciones de datos","def":"How the data looks: even, lopsided, bunched, or with gaps.","defEs":"Cómo se ven los datos: parejos, ladeados, juntos o con espacios.","example":"A long tail to the right means the distribution is skewed right.","img":"/assets/vocab-images/concept-shape-of-data-distributions.svg","imgAlt":"Illustration of Shape of Data Distributions: How the data looks: even, lopsided, bunched, or with gaps.","cs":false,"formal":"The overall pattern of data, such as symmetric, skewed, clustered, or containing gaps.","formalEs":"El patrón general de los datos, como simétrico, sesgado, agrupado o con espacios."},{"term":"Shape of the data","termEs":"Forma de los datos","def":"The pattern the bars or dots make.","defEs":"El patrón que forman las barras o los puntos.","example":"Tall in the middle and short on both sides is one shape.","img":"/assets/vocab-images/distribution.svg","imgAlt":"Illustration of Shape of the data: The pattern the bars or dots make.","cs":false,"formal":"The pattern the bars or dots make across the intervals.","formalEs":"El patrón que forman las barras o los puntos a lo largo de los intervalos."},{"term":"Side length","termEs":"Longitud del lado","def":"How long one side is.","defEs":"Qué tan largo es un lado.","example":"Found with absolute value when the points share a coordinate.","img":"/assets/vocab-images/segment.svg","imgAlt":"Illustration of Side length: How long one side is.","cs":false,"formal":"The distance between two vertices that are joined by a side.","formalEs":"La distancia entre dos vértices unidos por un lado."},{"term":"Simplest form","termEs":"Forma más simple","def":"A ratio with the smallest whole numbers that still match.","defEs":"Una razón con los números enteros más pequeños que sigue igual.","example":"6:8 in simplest form is 3:4","img":"/assets/vocab-images/equivalent-ratio.svg","imgAlt":"Illustration of Simplest form: A ratio with the smallest whole numbers that still match.","cs":false,"formal":"A ratio whose terms have been divided by the largest number that divides both.","formalEs":"Una razón cuyos términos se han dividido entre el mayor número que divide a ambos.","exampleEs":"6:8 en su forma más simple es 3:4","exampleFormal":"6 : 9 → 2 : 3"},{"term":"Simplify Algebraic Expressions","termEs":"Simplificar expresiones algebraicas","def":"Make an expression shorter. It keeps the same value.","defEs":"Hacer una expresión más corta. Tiene el mismo valor.","example":"2x + 3x = 5x","img":"/assets/vocab-images/concept-simplify-algebraic-expressions.svg","imgAlt":"Illustration of Simplify Algebraic Expressions: Make an expression shorter. It keeps the same value.","cs":false,"formal":"Rewrite an expression in a shorter equivalent form by combining like terms and using properties.","formalEs":"Reescribir una expresión en una forma equivalente más corta combinando términos semejantes y usando propiedades.","exampleEs":"2x + 3x = 5x","exampleFormal":"3x + 2 + 4x − 1 = 7x + 1"},{"term":"Skewed","termEs":"Sesgado","def":"Most data sits on one side, with a tail on the other.","defEs":"La mayoría de los datos está de un lado, con una cola del otro.","example":"Scores: 5, 6, 7, 8, 8, 35 → most scores are low, but 35 creates a tail to the right (skewed right)","img":"/assets/vocab-images/skewed.svg","imgAlt":"Illustration of Skewed: Most data sits on one side, with a tail on the other.","cs":false,"formal":"When most data sits on one side with a tail on the other.","formalEs":"Cuando la mayoría de los datos está de un lado con una cola del otro."},{"term":"Skip counting","termEs":"Conteo salteado","def":"Counting by a number, like 2, 4, 6.","defEs":"Contar de un número en un número, como 2, 4, 6.","example":"Skip count by 6: 6, 12, 18, 24, 30 — each jump adds 6","img":"/assets/vocab-images/multiple.svg","imgAlt":"Illustration of Skip counting: Counting by a number, like 2, 4, 6.","cs":false,"formal":"Counting by a number, like 2, 4, 6, to list its multiples.","formalEs":"Contar de un número en un número, como 2, 4, 6, para listar sus múltiplos."},{"term":"Slant height","termEs":"Altura inclinada (apotema)","def":"The height of a side triangle, measured along the tilted side.","defEs":"La altura de un triángulo lateral, medida por su lado inclinado.","example":"If you slide your finger from the bottom edge up the triangle face to the top point — that distance is the slant height","img":"/assets/vocab-images/slant-height-pyramid.svg","imgAlt":"Illustration of Slant height: The height of a side triangle, measured along the tilted side.","cs":false,"formal":"The height of a side triangle, measured along its slanted face.","formalEs":"La altura de un triángulo lateral, medida por su cara inclinada."},{"term":"Slanted side","termEs":"Lado inclinado","def":"A side that leans. It is not the straight-up height.","defEs":"Un lado que se inclina. No es la altura en línea recta.","example":"In a leaning parallelogram, use the dashed 90° height—not the slanted side—in A = b × h.","img":"/assets/vocab-images/slanted-side.svg","imgAlt":"Illustration of Slanted side: A side that leans. It is not the straight-up height.","cs":false,"formal":"A side that leans instead of going straight up and down. It is not the perpendicular height.","formalEs":"Un lado que está inclinado en vez de subir y bajar verticalmente. No es la altura perpendicular."},{"term":"Solution","termEs":"Solución","def":"A value that makes the math sentence true.","defEs":"Un valor que hace verdadera la oración matemática.","example":"In x + 2 = 5, the answer is x = 3","img":"/assets/vocab-images/equation.svg","imgAlt":"Illustration of Solution: A value that makes the math sentence true.","cs":false,"formal":"A number that makes the equation or inequality true.","formalEs":"Un número que hace verdadera la ecuación o desigualdad.","exampleEs":"En x + 2 = 5, la respuesta es x = 3","exampleFormal":"In 3/4 ÷ 1/8 = 6, the solution is 6 portions"},{"term":"Solution set","termEs":"Conjunto solución","def":"All the values that make the sentence true.","defEs":"Todos los valores que hacen verdadera la oración.","example":"x > 3: 4, 5, 6 and more all work","img":"/assets/vocab-images/solution-set.svg","imgAlt":"Illustration of Solution set: All the values that make the sentence true.","cs":false,"formal":"All the values that make an inequality true.","formalEs":"Todos los valores que hacen verdadera una desigualdad.","exampleEs":"x > 3: 4, 5, 6 y más sirven","exampleFormal":"Every number 7 or below."},{"term":"Solve","termEs":"Resolver","def":"Find the number that makes it true.","defEs":"Hallar el número que lo hace verdadero.","example":"x + 3 > 10 → subtract 3 → x > 7 — any number greater than 7 works","img":"/assets/vocab-images/equation.svg","imgAlt":"Illustration of Solve: Find the number that makes it true.","cs":false,"formal":"To find the number that makes it true.","formalEs":"Encontrar el número que la hace verdadera."},{"term":"Solve and Graph Inequalities","termEs":"Resolver y representar desigualdades","def":"Get the letter alone, then show all answers on a line.","defEs":"Dejar la letra sola y mostrar todas las respuestas en una recta.","example":"x + 2 ≤ 7 → x ≤ 5; closed circle at 5, arrow left.","img":"/assets/vocab-images/concept-solve-and-graph-inequalities.svg","imgAlt":"Illustration of Solve and Graph Inequalities: Get the letter alone, then show all answers on a line.","cs":false,"formal":"Isolate the variable, then show the complete solution set on a number line.","formalEs":"Aislar la variable y luego mostrar el conjunto completo de soluciones en una recta numérica."},{"term":"Solve Multiplication and Division Equations","termEs":"Resolver ecuaciones de multiplicación y división","def":"Undo the × or ÷ to get the letter alone.","defEs":"Deshacer × o ÷ para dejar la letra sola.","example":"3x = 12 → x = 4","img":"/assets/vocab-images/concept-solve-multiplication-and-division-equations.svg","imgAlt":"Illustration of Solve Multiplication and Division Equations: Undo the × or ÷ to get the letter alone.","cs":false,"formal":"Use inverse multiplication or division to isolate the variable.","formalEs":"Usar la multiplicación o división inversa para aislar la variable.","exampleEs":"3x = 12 → x = 4","exampleFormal":"4x = 20 → x = 5"},{"term":"Solve One-Step Addition and Subtraction Equations","termEs":"Resolver ecuaciones de suma y resta de un paso","def":"Undo the + or − to get the letter alone.","defEs":"Deshacer + o − para dejar la letra sola.","example":"x + 5 = 9 → x = 4","img":"/assets/vocab-images/concept-solve-one-step-addition-and-subtraction-equations.svg","imgAlt":"Illustration of Solve One-Step Addition and Subtraction Equations: Undo the + or − to get the letter alone.","cs":false,"formal":"Use one inverse addition or subtraction operation to isolate the variable.","formalEs":"Usar una operación inversa de suma o resta para aislar la variable.","exampleEs":"x + 5 = 9 → x = 4","exampleFormal":"x + 7 = 12 → x = 5"},{"term":"Spread","termEs":"Dispersión","def":"How far apart the numbers are.","defEs":"Qué tan separados están los números.","example":"Low spread: 8, 9, 10, 11 (close together). High spread: 2, 9, 10, 25 (far apart)","img":"/assets/vocab-images/spread.svg","imgAlt":"Illustration of Spread: How far apart the numbers are.","cs":false},{"term":"Squared","termEs":"Al cuadrado","def":"A number times itself.","defEs":"Un número multiplicado por sí mismo.","example":"3² = 3 × 3 = 9","img":"/assets/vocab-images/exponent.svg","imgAlt":"Illustration of Squared: A number times itself.","cs":false,"formal":"A base used as a factor two times.","formalEs":"Una base usada como factor dos veces.","exampleEs":"3² = 3 × 3 = 9","exampleFormal":"4^2 = 4 × 4"},{"term":"Statistical Question","termEs":"Pregunta estadística","def":"A question with answers that change from person to person.","defEs":"Una pregunta cuyas respuestas cambian de una persona a otra.","example":"“How tall are the players on the team?” → answers vary: 60 in, 63 in, 58 in, 65 in","img":"/assets/vocab-images/data.svg","imgAlt":"Illustration of Statistical Question: A question with answers that change from person to person.","cs":false,"formal":"A question answered with data that are expected to vary.","formalEs":"Una pregunta que se responde con datos que se espera que varíen."},{"term":"Statistical Questions and Data","termEs":"Preguntas estadísticas y datos","def":"Questions that have many answers, and the facts you collect.","defEs":"Preguntas con muchas respuestas, y los datos que reúnes.","example":"How many minutes do students in our class read each night?","img":"/assets/vocab-images/concept-statistical-questions-and-data.svg","imgAlt":"Illustration of Statistical Questions and Data: Questions that have many answers, and the facts you collect.","cs":false,"formal":"A statistical question expects varied answers that can be collected as data.","formalEs":"Una pregunta estadística espera respuestas variadas que se pueden recopilar como datos."},{"term":"strategy","termEs":"estrategia","def":"A plan for how to solve a problem.","defEs":"Un plan para resolver un problema.","example":"“I will draw a tape diagram first, then divide” — chosen before computing.","img":"/assets/vocab-images/strategy.svg","imgAlt":"Illustration of strategy: A plan for how to solve a problem.","cs":false,"formal":"A plan for how to solve a problem before you start computing.","formalEs":"Un plan para resolver un problema antes de empezar a calcular."},{"term":"strength","termEs":"fortaleza","def":"Something you do well and can share.","defEs":"Algo que haces bien y puedes compartir.","example":"“I am good at mental math with money” — a strength you can teach.","img":"/assets/vocab-images/strength.svg","imgAlt":"Illustration of strength: Something you do well and can share.","cs":false,"formal":"Something you already do well and can share with others.","formalEs":"Algo que ya haces bien y puedes compartir con otros."},{"term":"Subtraction Property of Equality","termEs":"Propiedad de sustracción de la igualdad","def":"Subtract the same number from both sides. They stay equal.","defEs":"Resta el mismo número de ambos lados. Siguen siendo iguales.","example":"x + 3 = 10 → x = 7","img":"/assets/vocab-images/equation.svg","imgAlt":"Illustration of Subtraction Property of Equality: Subtract the same number from both sides. They stay equal.","cs":false,"formal":"Subtracting the same amount from both sides keeps an equation balanced.","formalEs":"Restar la misma cantidad de ambos lados mantiene una ecuación equilibrada.","exampleEs":"x + 3 = 10 → x = 7","exampleFormal":"Both sides − 7"},{"term":"Surface Area of Prisms","termEs":"Área de superficie de prismas","def":"Add the area of every face of a prism.","defEs":"Sumar el área de cada cara de un prisma.","example":"SA = 2B + lateral area","img":"/assets/vocab-images/surface-area-of-prisms.svg","imgAlt":"Illustration of Surface Area of Prisms: Add the area of every face of a prism.","cs":false,"formal":"The total area of all bases and lateral faces of a prism. Formula: SA = 2B + lateral area.","formalEs":"El área total de las bases y caras laterales de un prisma. Fórmula: SA = 2B + área lateral."},{"term":"Surface Area of Pyramids","termEs":"Área de superficie de pirámides","def":"Add the area of the base and the triangle sides.","defEs":"Sumar el área de la base y de los lados triangulares.","example":"Square base 6×6 with 4 triangles of ½ × 6 × 5: 36 + 60 = 96 square units","img":"/assets/vocab-images/surface-area-of-pyramids.svg","imgAlt":"Illustration of Surface Area of Pyramids: Add the area of the base and the triangle sides.","cs":false,"formal":"The total area of a pyramid's base and triangular faces. Formula: SA = B + lateral area.","formalEs":"El área total de la base y las caras triangulares de una pirámide. Fórmula: SA = B + área lateral."},{"term":"Surface Area Using Nets","termEs":"Área de superficie usando redes","def":"Unfold the solid. Then add up every face.","defEs":"Desplegar el sólido y sumar el área de cada cara.","example":"A box with 6 faces: 2(8×5) + 2(8×3) + 2(5×3) = 158 square units","img":"/assets/vocab-images/surface-area-of-prisms.svg","imgAlt":"Illustration of Surface Area Using Nets: Unfold the solid. Then add up every face.","cs":false,"formal":"The total area of all the faces of a solid. A net unfolds the solid flat so you can see every face and add their areas.","formalEs":"El área total de todas las caras de un cuerpo. Una plantilla lo despliega para ver cada cara y sumar sus áreas."},{"term":"Survey","termEs":"Encuesta","def":"Ask people questions to get facts.","defEs":"Hacer preguntas a las personas para reunir datos.","example":"Asking 50 students 'What is your favorite sport?' and recording the answers","img":"/assets/vocab-images/data.svg","imgAlt":"Illustration of Survey: Ask people questions to get facts.","cs":false,"formal":"Collecting facts by asking people questions.","formalEs":"Recoger datos haciendo preguntas a las personas."},{"term":"symmetric","termEs":"simétrico","def":"Both halves match, like a mirror.","defEs":"Las dos mitades coinciden, como en un espejo.","example":"A butterfly: the left wing is the mirror of the right.","img":"/assets/vocab-images/symmetric.svg","imgAlt":"Illustration of symmetric: Both halves match, like a mirror.","cs":false,"formal":"Having two halves that match — one side is a mirror image of the other.","formalEs":"Que tiene dos mitades que coinciden: un lado es la imagen reflejada del otro."},{"term":"Symmetry","termEs":"Simetría","def":"When both sides of a line match.","defEs":"Cuando los dos lados de una línea coinciden.","example":"A butterfly's wings are symmetric — fold it down the middle and both sides match","img":"/assets/vocab-images/symmetric.svg","imgAlt":"Illustration of Symmetry: When both sides of a line match.","cs":false,"formal":"When a shape looks the same on both sides of a line.","formalEs":"Cuando una figura se ve igual a ambos lados de una línea."},{"term":"table of values","termEs":"tabla de valores","def":"A table that lists matching pairs of numbers.","defEs":"Una tabla que muestra pares de números que se corresponden.","example":"x: 1, 2, 3 and y: 2, 4, 6","img":"/assets/vocab-images/table-of-values.svg","imgAlt":"Illustration of table of values: A table that lists matching pairs of numbers.","cs":false,"formal":"A table that lists each step of a pattern so you can check that a solution is reasonable.","formalEs":"Una tabla que muestra cada paso de un patrón para comprobar que una solución es razonable.","exampleEs":"x: 1, 2, 3 y y: 2, 4, 6","exampleFormal":"discs 1, 2, 3 beside steps 1, 3, 7 — one row per step."},{"term":"tape diagram","termEs":"diagrama de cintas","def":"A bar cut into equal parts to show amounts.","defEs":"Una barra dividida en partes iguales para mostrar cantidades.","example":"One bar of 4,000 passengers cut into equal groups of 80.","img":"/assets/vocab-images/bar-model.svg","imgAlt":"Illustration of tape diagram: A bar cut into equal parts to show amounts.","cs":false,"formal":"A rectangle cut into equal parts that helps you visualize how a total breaks apart.","formalEs":"Un rectángulo dividido en partes iguales que te ayuda a visualizar cómo se separa un total."},{"term":"Target mean","termEs":"Media objetivo","def":"The mean you want to reach.","defEs":"La media que quieres alcanzar.","example":"A goal average of 29 points.","img":"/assets/vocab-images/mean.svg","imgAlt":"Illustration of Target mean: The mean you want to reach.","cs":false,"formal":"The mean a person is trying to reach.","formalEs":"La media que una persona intenta alcanzar."},{"term":"Target total","termEs":"Total objetivo","def":"The total the data must add up to.","defEs":"El total al que deben sumar los datos.","example":"Mean 5 for 4 values: total 20","img":"/assets/vocab-images/sum.svg","imgAlt":"Illustration of Target total: The total the data must add up to.","cs":false,"formal":"The target mean times the number of values.","formalEs":"La media objetivo multiplicada por la cantidad de valores.","exampleEs":"Media 5 con 4 valores: total 20","exampleFormal":"mean × count = total"},{"term":"Tax","termEs":"Impuesto","def":"A percent of the price, paid on top.","defEs":"Un porcentaje del precio que se paga además.","example":"5% of $40 is $2 tax","img":"/assets/vocab-images/tax.svg","imgAlt":"Illustration of Tax: A percent of the price, paid on top.","cs":false,"formal":"Extra money added to the price of a purchase for the government, found by taking a percent of the price. Price + tax = total.","formalEs":"Dinero extra que se suma al precio de una compra para el gobierno, hallado tomando un porcentaje del precio. Precio + impuesto = total.","exampleEs":"5 % de $40 son $2 de impuesto","exampleFormal":"Price $20, 6% tax = $1.20, so you pay $21.20"},{"term":"The Distributive Property","termEs":"La propiedad distributiva","def":"Multiply by each part inside the ( ).","defEs":"Multiplicar por cada parte dentro del paréntesis.","example":"3(4 + 5) = 3 × 4 + 3 × 5","img":"/assets/vocab-images/concept-the-distributive-property.svg","imgAlt":"Illustration of The Distributive Property: Multiply by each part inside the ( ).","cs":false,"formal":"Multiply a factor by every term inside parentheses.","formalEs":"Multiplicar un factor por cada término dentro de los paréntesis.","exampleEs":"3(4 + 5) = 3 × 4 + 3 × 5","exampleFormal":"3(x + 4) = 3x + 12"},{"term":"the whole","termEs":"el todo","def":"The full amount. It counts as 100%.","defEs":"La cantidad completa. Cuenta como 100 %.","example":"“Of the USED storage” makes 4 GB the whole — not the 6 GB total.","img":"/assets/vocab-images/part-to-whole.svg","imgAlt":"Illustration of the whole: The full amount. It counts as 100%.","cs":false,"formal":"The quantity that counts as 100% in a problem — and it can change between questions.","formalEs":"La cantidad que representa el 100% en un problema, y puede cambiar entre preguntas."},{"term":"Tip","termEs":"Propina","def":"A percent of the bill that you add for service.","defEs":"Un porcentaje de la cuenta que agregas por el servicio.","example":"10% of a $20 bill is $2","img":"/assets/vocab-images/tip.svg","imgAlt":"Illustration of Tip: A percent of the bill that you add for service.","cs":false,"formal":"Extra money you add for good service, found by taking a percent of the bill. Bill + tip = total.","formalEs":"Dinero extra que agregas por un buen servicio, hallado tomando un porcentaje de la cuenta. Cuenta + propina = total.","exampleEs":"10 % de una cuenta de $20 son $2","exampleFormal":"Bill $40, 15% tip = $6, so you pay $46"},{"term":"Total parts","termEs":"Partes totales","def":"Add the two parts of a ratio.","defEs":"La suma de las dos partes de una razón.","example":"3:2 has 3 + 2 = 5 parts","img":"/assets/vocab-images/bar-model.svg","imgAlt":"Illustration of Total parts: Add the two parts of a ratio.","cs":false,"formal":"The two terms of a ratio added together.","formalEs":"Los dos términos de una razón sumados.","exampleEs":"3:2 tiene 3 + 2 = 5 partes","exampleFormal":"3 + 1 = 4 parts in a tape diagram."},{"term":"Total price","termEs":"Precio total","def":"What the whole package costs.","defEs":"Lo que cuesta todo el paquete.","example":"3 pens for $6: total price is $6","img":"/assets/vocab-images/unit-rate.svg","imgAlt":"Illustration of Total price: What the whole package costs.","cs":false,"formal":"What the whole package costs, not the cost of one item.","formalEs":"Lo que cuesta el paquete completo, no el costo de un solo artículo.","exampleEs":"3 bolígrafos por $6: el precio total es $6","exampleFormal":"$9.60 for the whole bag."},{"term":"Triangular prism","termEs":"Prisma triangular","def":"A solid with two triangle ends and three flat sides.","defEs":"Un sólido con dos extremos triangulares y tres lados planos.","example":"Shaped like a tent or a wedge of cheese — 2 triangle ends + 3 rectangle sides","img":"/assets/vocab-images/rectangular-prism.svg","imgAlt":"Illustration of Triangular prism: A solid with two triangle ends and three flat sides.","cs":false,"formal":"A solid with two triangle ends and three flat rectangle sides.","formalEs":"Un sólido con dos extremos triangulares y tres lados rectangulares."},{"term":"True statement","termEs":"Enunciado verdadero","def":"A math sentence that is correct.","defEs":"Una oración matemática que es correcta.","example":"3 + 4 = 7 is true","img":"/assets/vocab-images/inequality.svg","imgAlt":"Illustration of True statement: A math sentence that is correct.","cs":false,"formal":"A sentence that the numbers make correct.","formalEs":"Un enunciado que los números hacen correcto.","exampleEs":"3 + 4 = 7 es verdadero","exampleFormal":"9 > 5 is true."},{"term":"Two-dimensional","termEs":"Bidimensional","def":"A flat shape with length and width, but no thickness.","defEs":"Una figura plana con largo y ancho, pero sin grosor.","example":"A rectangle drawn on paper is 2D — it has length and width but no depth","img":"/assets/vocab-images/square-unit.svg","imgAlt":"Illustration of Two-dimensional: A flat shape with length and width, but no thickness.","cs":false},{"term":"Understand Percent","termEs":"Comprender el porcentaje","def":"A percent tells how many out of 100.","defEs":"Un porcentaje dice cuántos de cada 100.","example":"4 out of 10 = 40 out of 100 = 40%","img":"/assets/vocab-images/percent.svg","imgAlt":"Illustration of Understand Percent: A percent tells how many out of 100.","cs":false,"formal":"A percent is a ratio that compares a number to 100, so every percent answers the question “how many out of 100?”","formalEs":"Un porcentaje es una razón que compara un número con 100, así que todo porcentaje responde “¿cuántos de cada 100?”"},{"term":"Understand Ratios","termEs":"Comprender razones","def":"A ratio compares two things.","defEs":"Una razón compara dos cantidades.","example":"3 red to 2 blue","img":"/assets/vocab-images/concept-understand-ratios.svg","imgAlt":"Illustration of Understand Ratios: A ratio compares two things.","cs":false,"formal":"Use a ratio to compare two quantities by division.","formalEs":"Usar una razón para comparar dos cantidades mediante la división.","exampleEs":"3 rojas a 2 azules","exampleFormal":"3 red tiles to 5 blue tiles can be written 3:5 or 3/5."},{"term":"Unit cube","termEs":"Cubo unitario","def":"A cube with every edge one unit long.","defEs":"Un cubo con todas las aristas de una unidad.","example":"Unit cubes fill a prism with no gaps.","img":"/assets/vocab-images/cubic-units.svg","imgAlt":"Illustration of Unit cube: A cube with every edge one unit long.","cs":false,"formal":"A cube that measures one unit on every edge.","formalEs":"Un cubo que mide una unidad en cada arista."},{"term":"Unit fraction","termEs":"Fracción unitaria","def":"A fraction with 1 on top, like 1/4.","defEs":"Una fracción con 1 arriba, como 1/4.","example":"1/2, 1/3, 1/4, 1/5 — each represents one equal part of a whole","img":"/assets/vocab-images/unit-fraction.svg","imgAlt":"Illustration of Unit fraction: A fraction with 1 on top, like 1/4.","cs":false},{"term":"Unit price","termEs":"Precio unitario","def":"The cost of just one item, like $0.60 a game.","defEs":"El costo de un solo artículo, como $0.60 por juego.","example":"$3 for 5 games → $0.60 per 1 game","img":"/assets/vocab-images/unit-rate.svg","imgAlt":"Illustration of Unit price: The cost of just one item, like $0.60 a game.","cs":false,"formal":"A unit rate that gives the cost of exactly 1 item, like $0.60 per game.","formalEs":"Una tasa unitaria que da el costo de exactamente 1 artículo, como $0.60 por juego."},{"term":"Unit rate point","termEs":"Punto de tasa unitaria","def":"The point (1, r): r is the amount for 1.","defEs":"El punto (1, r): r es la cantidad para 1.","example":"(1, 9) means 9 for each 1.","img":"/assets/vocab-images/unit-rate.svg","imgAlt":"Illustration of Unit rate point: The point (1, r): r is the amount for 1.","cs":false,"formal":"The point (1, r) on a graph, where r is the amount for one.","formalEs":"El punto (1, r) en una gráfica, donde r es la cantidad que corresponde a uno."},{"term":"Unit Rate Problem Solving","termEs":"Resolución de problemas con tasas unitarias","def":"Find the amount for 1, then use it to compare or solve.","defEs":"Hallar la cantidad para 1 y usarla para comparar o resolver.","example":"$12 for 4 items = $3 per item.","img":"/assets/vocab-images/concept-unit-rate-problem-solving.svg","imgAlt":"Illustration of Unit Rate Problem Solving: Find the amount for 1, then use it to compare or solve.","cs":false,"formal":"Find an amount per 1 unit and use it to compare choices or solve a problem.","formalEs":"Hallar una cantidad por 1 unidad y usarla para comparar opciones o resolver un problema."},{"term":"Unit ratio","termEs":"Razón unitaria","def":"A ratio for 1 unit, like 12 inches to 1 foot.","defEs":"Una razón para 1 unidad, como 12 pulgadas por 1 pie.","example":"12 : 1 — twelve inches for every one foot","img":"/assets/vocab-images/unit-rate.svg","imgAlt":"Illustration of Unit ratio: A ratio for 1 unit, like 12 inches to 1 foot.","cs":false,"formal":"A ratio that compares an amount to exactly 1 unit of another quantity, like 12 inches to 1 foot.","formalEs":"Una razón que compara una cantidad con exactamente 1 unidad de otra cantidad, como 12 pulgadas por 1 pie."},{"term":"Unknown","termEs":"Incógnita","def":"The value you want to find.","defEs":"El valor que quieres hallar.","example":"In x + 2 = 5, the unknown is x","img":"/assets/vocab-images/variable.svg","imgAlt":"Illustration of Unknown: The value you want to find.","cs":false,"formal":"The value you are trying to find, usually shown with a variable.","formalEs":"El valor que intentas encontrar, mostrado normalmente con una variable.","exampleEs":"En x + 2 = 5, la incógnita es x","exampleFormal":"In n + 5 = 12, n is the unknown; you solve to find n = 7."},{"term":"Variability","termEs":"Variabilidad","def":"How far apart the numbers are.","defEs":"Qué tan separados están los números.","example":"Scores 10, 12, 11 are close together (low variability); scores 2, 15, 30 are far apart (high variability)","img":"/assets/vocab-images/spread.svg","imgAlt":"Illustration of Variability: How far apart the numbers are.","cs":false,"formal":"How spread out the numbers are."},{"term":"Variation","termEs":"Variación","def":"How much the values vary.","defEs":"Cuánto varían los valores entre sí.","example":"A larger MAD means more variation.","img":"/assets/vocab-images/spread.svg","imgAlt":"Illustration of Variation: How much the values vary.","cs":false,"formal":"How much the values in a data set differ from one another.","formalEs":"Cuánto difieren entre sí los valores de un conjunto de datos."},{"term":"Vertical distance","termEs":"Distancia vertical","def":"How far apart two points are, up or down.","defEs":"Qué tan separados están dos puntos, hacia arriba o abajo.","example":"From (4, 1) to (4, 7) is 6","img":"/assets/vocab-images/distance.svg","imgAlt":"Illustration of Vertical distance: How far apart two points are, up or down.","cs":false,"formal":"How far apart two points are going up or down.","formalEs":"Qué tan separados están dos puntos yendo hacia arriba o hacia abajo.","exampleEs":"De (4, 1) a (4, 7) hay 6","exampleFormal":"From (4, -1) to (4, 6): count from -1 to 6 = 7 units up"},{"term":"Volume of Rectangular Prisms","termEs":"Volumen de prismas rectangulares","def":"Length times width times height.","defEs":"Largo por ancho por alto.","example":"5 × 3 × 2 = 30 cubes","img":"/assets/vocab-images/volume-of-rectangular-prisms.svg","imgAlt":"Illustration of Volume of Rectangular Prisms: Length times width times height.","cs":false,"formal":"The space inside a rectangular prism. Formula: V = Bh = l × w × h.","formalEs":"El espacio dentro de un prisma rectangular. Fórmula: V = Bh = l × w × h.","exampleEs":"5 × 3 × 2 = 30 cubos","exampleFormal":"V = Bh = l × w × h"},{"term":"Volume with Whole-Number Edges","termEs":"Volumen con aristas de números enteros","def":"Count the unit cubes that fill the box.","defEs":"Contar los cubos unitarios que llenan la caja.","example":"4 by 3 by 2 is 24 unit cubes","img":"/assets/vocab-images/volume-of-rectangular-prisms.svg","imgAlt":"Illustration of Volume with Whole-Number Edges: Count the unit cubes that fill the box.","cs":false,"formal":"The number of unit cubes inside a rectangular prism. Formula: V = l × w × h.","formalEs":"La cantidad de cubos unitarios dentro de un prisma rectangular. Fórmula: V = l × w × h.","exampleEs":"4 por 3 por 2 son 24 cubos unitarios","exampleFormal":"V = l × w × h; 3 × 4 × 5 = 60 cubic units."},{"term":"Whisker","termEs":"Bigote","def":"A line from the box out to the lowest or highest value.","defEs":"Una línea desde la caja hasta el valor más bajo o más alto.","example":"The left whisker reaches the minimum; the right whisker reaches the maximum.","img":"/assets/vocab-images/box-plot.svg","imgAlt":"Illustration of Whisker: A line from the box out to the lowest or highest value.","cs":false,"formal":"A line on a box plot that reaches from the box out to the least or greatest value.","formalEs":"Una línea en un diagrama de caja que va desde la caja hasta el valor menor o mayor."},{"term":"Work backward","termEs":"Trabajar hacia atrás","def":"Start at the end and undo each step.","defEs":"Empezar por el final y deshacer cada paso.","example":"Goal first, then undo.","img":"/assets/vocab-images/strategy.svg","imgAlt":"Illustration of Work backward: Start at the end and undo each step.","cs":false,"formal":"Start from the output and undo each step to find the input.","formalEs":"Empezar desde el resultado y deshacer cada paso para encontrar la entrada."},{"term":"Write Algebraic Expressions","termEs":"Escribir expresiones algebraicas","def":"Turn words into numbers and letters.","defEs":"Convertir palabras en números y letras.","example":"5 more than n is n + 5","img":"/assets/vocab-images/concept-write-algebraic-expressions.svg","imgAlt":"Illustration of Write Algebraic Expressions: Turn words into numbers and letters.","cs":false,"formal":"Translate words or a situation into numbers, variables, and operation symbols.","formalEs":"Traducir palabras o una situación a números, variables y símbolos de operaciones.","exampleEs":"5 más que n es n + 5","exampleFormal":"Five more than n becomes n + 5."},{"term":"Write and Evaluate Numerical Expressions with Exponents","termEs":"Escribir y evaluar expresiones numéricas con exponentes","def":"Write a number phrase with powers, then find its value.","defEs":"Escribir una frase numérica con potencias y hallar su valor.","example":"3 + 2² = 3 + 4 = 7","img":"/assets/vocab-images/expression.svg","imgAlt":"Illustration of Write and Evaluate Numerical Expressions with Exponents: Write a number phrase with powers, then find its value.","cs":false,"formal":"Turning a situation into a number sentence without an equal sign, then finding its value in the correct order.","formalEs":"Convertir una situación en una expresión numérica sin signo de igual y luego hallar su valor en el orden correcto.","exampleEs":"3 + 2² = 3 + 4 = 7","exampleFormal":"2 × 15 + 4 × 20 + 8 × 2^3 = 174"},{"term":"Write Equations","termEs":"Escribir ecuaciones","def":"Use an equal sign to show two sides match.","defEs":"Usar un signo igual para mostrar que dos lados coinciden.","example":"5 more than n is 12: n + 5 = 12","img":"/assets/vocab-images/concept-write-equations.svg","imgAlt":"Illustration of Write Equations: Use an equal sign to show two sides match.","cs":false,"formal":"Represent a relationship with expressions joined by an equal sign.","formalEs":"Representar una relación con expresiones unidas por un signo igual.","exampleEs":"5 más que n es 12: n + 5 = 12","exampleFormal":"A $5 fee plus $3 per game for g games: 5 + 3g = total."},{"term":"Write Inequalities","termEs":"Escribir desigualdades","def":"Use <, >, ≤, or ≥ to show many numbers.","defEs":"Usar <, >, ≤ o ≥ para mostrar muchos valores posibles.","example":"At least 3 apples: a ≥ 3","img":"/assets/vocab-images/concept-write-inequalities.svg","imgAlt":"Illustration of Write Inequalities: Use <, >, ≤, or ≥ to show many numbers.","cs":false,"formal":"Represent a range of possible values with <, >, ≤, or ≥.","formalEs":"Representar un rango de valores posibles con <, >, ≤ o ≥.","exampleEs":"Al menos 3 manzanas: a ≥ 3","exampleFormal":"You must be at least 12 years old: a ≥ 12."},{"term":"x-axis","termEs":"Eje x","def":"The number line that goes left to right.","defEs":"La recta numérica que va de izquierda a derecha.","example":"Runs left and right.","img":"/assets/vocab-images/axis.svg","imgAlt":"Illustration of x-axis: The number line that goes left to right.","cs":false,"formal":"The horizontal number line through the origin.","formalEs":"La recta numérica horizontal que pasa por el origen."},{"term":"x-coordinate","termEs":"Coordenada x","def":"The first number in a pair. It tells left or right.","defEs":"El primer número de un par. Dice cuánto a la derecha o izquierda.","example":"In (3, 2), the x is 3","img":"/assets/vocab-images/ordered-pair.svg","imgAlt":"Illustration of x-coordinate: The first number in a pair. It tells left or right.","cs":false,"formal":"The first number in an ordered pair; how far right or left.","formalEs":"El primer número de un par ordenado; cuánto hacia la derecha o la izquierda.","exampleEs":"En (3, 2), la x es 3","exampleFormal":"In (−3, 4), the x-coordinate is −3."},{"term":"y-axis","termEs":"Eje y","def":"The number line that goes up and down.","defEs":"La recta numérica que va hacia arriba y abajo.","example":"Runs up and down.","img":"/assets/vocab-images/axis.svg","imgAlt":"Illustration of y-axis: The number line that goes up and down.","cs":false,"formal":"The vertical number line through the origin.","formalEs":"La recta numérica vertical que pasa por el origen."}];
